create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q748579', 'Mickey Mania est un jeu vidéo de plate-forme développé par Traveller''s Tales et édité en 1994 par Sony Imagesoft sur Mega Drive, Super Nintendo et Mega-CD. Puis, il est porté en 1996 sur PlayStation sous le titre Mickey''s Wild Adventure.', 'https://fr.wikipedia.org/wiki/Mickey_Mania'),
  ('Q742244', 'Colony Wars: Red Sun, appelé Colony Wars III: Red Sun aux États-Unis, est un jeu vidéo de combat spatial développé par Psygnosis, sorti en 2000 sur PlayStation.

Il s''agit du troisième et dernier opus de la série Colony Wars.', 'https://fr.wikipedia.org/wiki/Colony_Wars:_Red_Sun'),
  ('Q741716', 'Warcraft II: Tides of Darkness est un jeu vidéo de stratégie en temps réel (STR) développé par Blizzard Entertainment. Les versions PC et Macintosh sont publiées en Amérique du Nord par Blizzard Entertainment en 1995 et en Europe par Ubisoft en 1996. Il est bien accueilli par les critiques l''année suivant sa sortie et connaît un grand succès commercial avec plus de 2 millions d''exemplaires vendus à ce jour.

Plus tard en 1996, Blizzard Entertainment publie une extension Warcraft II: Beyond the Dark Portal sur PC et Macintosh et en 1997 Electronic Arts édite une version regroupant le jeu original et son extension Warcraft II: The Dark Saga pour les consoles Sega Saturn et PlayStation. Warcraft II: Battle.net Edition regroupant le jeu original et son extension, permet de jouer sur la plate-forme multijoueur Battle.net créée par Blizzard Entertainment (et déjà utilisée pour Diablo et StarCraft) et sort en 1999, remplaçant la version PC fonctionnant sous MS-DOS par une version fonctionnant sous Windows.', 'https://fr.wikipedia.org/wiki/Warcraft_II:_Tides_of_Darkness'),
  ('Q753164', 'Silent Hill est un jeu vidéo de type survival horror développé par Konami CE Tokyo et édité par Konami en 1999 sur PlayStation. Réputé pour avoir révolutionné le jeu d''horreur par son approche psychologique de la peur, le titre de Keiichiro Toyama a connu un succès international. Il marque les débuts d''une longue série de jeux qui s''est poursuivie jusqu''en 2025. Christophe Gans en a réalisé l''adaptation cinématographique en 2006.

Silent Hill possède une identité souvent jugée plus aboutie que d''autres titres de l''époque, comme ceux de la série concurrente Resident Evil. Les idées originales de gameplay, la mise en scène ingénieuse de par le positionnement des caméras et l''expressivité des personnages, la bande-son maîtrisée d''Akira Yamaoka et le scénario recherché, rappelant L''Échelle de Jacob d''Adrian Lyne auquel le jeu emprunte un bon nombre d''éléments visuels, certains films de David Lynch ou encore l''univers de H. P. Lovecraft, font de cette production une œuvre notable de la cinquième génération de console.', 'https://fr.wikipedia.org/wiki/Silent_Hill_(jeu_vid%C3%A9o)'),
  ('Q2274988', 'Croc 2 ou Croc 2: Kingdom of the Gobbos en version remasterisé est un jeu vidéo de plates-formes développé par Argonaut Software et édité par Fox Interactive, sorti en 1999 sur PlayStation et l''année suivante sur Windows.

Il fait suite à Croc: Legend of the Gobbos, sorti en 1997 sur PlayStation, Saturn et Windows.

Une adaptation du jeu, portant le même nom, paraît à partir de janvier 2001 sur Game Boy Color.

Un remaster du jeu sous le nom de Croc 2: Kingfom of the Gobbos est prévu pour le quatrième trimestre 2026 sur PlayStation 5, PlayStation 4, Xbox Series X/S et PC sur les plateformes de jeu Steam et Gog.', 'https://fr.wikipedia.org/wiki/Croc_2'),
  ('Q2281114', 'Bloody Roar est un jeu vidéo de combat développé par Raizing sur borne d''arcade, puis adapté par Hudson Soft sur PlayStation en 1997. C''est le premier de la série Bloody Roar.

Ce jeu de combat a la particularité d''offrir à chaque combattant le pouvoir de se transformer en un animal (tigre, loup, lapin...). Ces combattants sont appelés les zoanthropes.', 'https://fr.wikipedia.org/wiki/Bloody_Roar_(jeu_vid%C3%A9o)'),
  ('Q2291123', 'Les Chevaliers de Baphomet (Broken Sword: The Shadow of the Templars) est un jeu vidéo d''aventure développé par Revolution Software et sorti sur PC (DOS/Windows), Mac et PlayStation fin 1996. Il est porté en 2002 sur Game Boy Advance, et en 2005 sur Palm OS.

En 2009, le jeu sort dans une nouvelle version au scénario plus étoffé sur Nintendo DS et Wii. La version Director''s Cut est portée sur iOS, iPad et PC en 2010 puis Android en 2012.

L''intrigue du jeu met en scène George Stobbart, un touriste américain en vacances à Paris qui est témoin d''un attentat commis dans un café par un homme déguisé en clown. Poussé par sa curiosité et son désir de connaître les raisons de cet attentat, George se retrouve embarqué dans une aventure teintée de mystères et de conspiration. Il est épaulé par Nicole Collard, une journaliste française qui a décidé d''enquêter sur les évènements étranges qui se sont déroulés à Paris. De fil en aiguille, George et Nico parcourront le monde pour tenter de résoudre cette énigme qui a un rapport avec l''ordre des Templiers.', 'https://fr.wikipedia.org/wiki/Les_Chevaliers_de_Baphomet_(jeu_vid%C3%A9o)'),
  ('Q2292393', 'Rayman 2: The Great Escape est un jeu vidéo de plate-forme de la série Rayman, développé et édité par Ubisoft. Il est sorti sur Nintendo 64 et PC pour les fêtes de fin d''année 1999, sur Dreamcast en février 2000 puis en septembre 2000 sur PlayStation. Il a aussi été développé sur PlayStation 2 la même année sous le nom Rayman Revolution, sur Nintendo DS en 2005 sous le nom Rayman DS, sur iOS en 2010 sous le nom original puis sur Nintendo 3DS sous le nom Rayman 3D en 2011.

Rayman 2: The Great Escape marque un changement important puisque le jeu passe d''un affichage 2D à un affichage en 3D. Ce n''est pas le seul bouleversement puisque l''histoire, le monde et l''ambiance générale du jeu n''ont plus grand-chose en commun avec le premier opus, Rayman.', 'https://fr.wikipedia.org/wiki/Rayman_2:_The_Great_Escape'),
  ('Q2292512', 'Croc: Legend of the Gobbos (aussi appelé Croc) est un jeu vidéo de plates-formes développé par Argonaut Games et édité par Fox Interactive, sorti sur PlayStation, Saturn et Windows en 1997.

Le joueur suit les aventures d''un jeune crocodile nommé Croc, dont la mission est de parcourir les quatre îles de la vallée des Gobbos, afin de libérer les Gobbos, un peuple de créatures poilues qui constitue sa famille adoptive, des griffes du baron Dante, un sorcier et le chef du peuple des Dantinis. Croc traverse des environnements variés, entre la forêt, les glaces, le désert et le château du baron Dante.', 'https://fr.wikipedia.org/wiki/Croc:_Legend_of_the_Gobbos'),
  ('Q288296', 'Spider-Man est un jeu vidéo d’action-aventure développé par Neversoft et édité par Activision en 2000 sur Nintendo 64 et PlayStation et en 2001 sur Windows, MacOS et Dreamcast. Parallèlement, une version a été développée par Vicarious Visions sur Game Boy Color, ce qui mènera à deux lignes temporelles différentes dans les suites, l''une pour les jeux de Neversoft, et l''autre pour les jeux de Vicarious Visions.

Le jeu est basé sur la série de comics The Amazing Spider-Man. Et bien qu’il ait plus ou moins la même esthétique et les mêmes personnages, le jeu n''est pas basé sur la série animée des années 1990[réf. souhaitée].', 'https://fr.wikipedia.org/wiki/Spider-Man_(jeu_vid%C3%A9o,_2000)'),
  ('Q286205', 'Wipeout (stylisé wipE''out'''' ou WipEout) est un jeu vidéo de course futuriste développé et édité par la société britannique Psygnosis, sorti en 1995 sur PlayStation et PC, et en 1996 sur Sega Saturn. Inspiré par Super Mario Kart, le jeu met en scène des courses de vaisseaux anti-gravité opposant huit concurrents et mêlant vitesse élevée et affrontements armés sur des circuits fantaisistes.

Accompagnant le lancement européen de la PlayStation, Wipeout connait un large succès critique et commercial et participe à la réputation de la machine de Sony. Il se distingue par sa direction artistique marquée, notamment conçue avec The Designers Republic, ainsi que par sa bande-son électronique. Les critiques saluent son concept innovant, son univers futuriste et son ambiance immersive. Aux côtés de F-Zero, Wipeout est devenu l''une des références du genre du jeu de course futuriste. Le gameplay exigeant ainsi que la sensation de vitesse et la conception des circuits sont particulièrement mis en avant. Cependant, plusieurs lacunes sont relevées, comme une maniabilité difficile à maîtriser, un contenu relativement limité et certains aspects techniques perfectibles.', 'https://fr.wikipedia.org/wiki/Wipeout_(jeu_vid%C3%A9o)'),
  ('Q317620', 'Tomb Raider est un jeu vidéo d''action-aventure sorti en 1996, développé par Core Design et édité par Eidos Interactive (futur Square Enix Europe). Il est le premier opus de la franchise médiatique Tomb Raider. Le jeu est d''abord publié sur Sega Saturn, puis rapidement sur PlayStation et MS-DOS. D''autres versions suivent pour Mac OS, Pocket PC, N-Gage, iOS et Android.

Le jeu suit Lara Croft, une archéologue et aventurière engagée par la femme d''affaires Jacqueline Natla pour retrouver un artefact légendaire, le Scion, caché dans un tombeau perdu des montagnes péruviennes. Le système de jeu consiste à explorer des niveaux, tout en combattant des ennemis et en résolvant des énigmes pour progresser. Une extension, Unfinished Business, sort en 1997 avec de nouveaux niveaux indépendants.', 'https://fr.wikipedia.org/wiki/Tomb_Raider_(jeu_vid%C3%A9o,_1996)'),
  ('Q282941', 'Fade to Black est un jeu vidéo d''action-aventure en 3D développé par Delphine Software et édité par Electronic Arts en 1995 sur compatible PC (DOS). Il a été édité sur PlayStation en 1996. Il fait suite à Flashback, un jeu d''action-aventure en 2D sorti en 1992.', 'https://fr.wikipedia.org/wiki/Fade_to_Black_(jeu_vid%C3%A9o)'),
  ('Q336100', 'Tales of Destiny est un jeu vidéo de rôle développé par Wolf Team et édité par Namco en 1997 sur PlayStation. Un remake est sorti en 2006 sur PlayStation 2.

La bande originale du jeu, Yume de Aruyouni, est interprétée par le groupe japonais Deen.', 'https://fr.wikipedia.org/wiki/Tales_of_Destiny'),
  ('Q220960', 'Diablo est un jeu vidéo de type hack ''n'' slash développé par Blizzard North. La version PC fonctionnant sous Windows a été publiée en janvier 1997 en Amérique du Nord et en Europe par Blizzard Entertainment. Une version pour PlayStation, développée par Electronic Arts, et une version Macintosh sont publiées l''année suivante en mars 1998.

Diablo se déroule dans un univers médiéval-fantastique où le joueur explore des donjons peuplés de créatures qu''il doit combattre pour gagner de l''expérience et des trésors, l''objectif du jeu étant de retrouver Diablo et le tuer. Le jeu est considéré comme ayant réinventé le genre du jeu vidéo de rôle en y introduisant le principe du pointer-et-cliquer et en le rendant plus accessible. Diablo a ainsi fortement influencé l''industrie du jeu vidéo, son système de jeu ayant été repris dans de nombreux titres qualifiés de « clones » ou de « Diablo-like ».', 'https://fr.wikipedia.org/wiki/Diablo_(jeu_vid%C3%A9o)'),
  ('Q282623', 'Legacy of Kain: Soul Reaver est un jeu vidéo d''action-aventure développé par Crystal Dynamics et édité par Eidos Interactive. Il est sorti sur PC et PlayStation en 1999 puis sur Dreamcast en 2000. En tant que deuxième jeu de la série Legacy of Kain, Soul Reaver est la suite de Blood Omen: Legacy of Kain. Il est lui-même suivi par Soul Reaver 2.

Se déroulant 1 500 ans après les événements de Blood Omen, Soul Reaver se déroule dans le monde de Nosgoth dévasté. L''histoire est centrée sur Raziel, ancien lieutenant du seigneur vampire Kain. Assassiné par son maître, Raziel est ressuscité par une divinité, se transforme en spectre et devient l’instrument de sa vengeance. Au cours de son périple, il s’empare de la Soul Reaver, la légendaire épée buveuse d’âmes de Kain.', 'https://fr.wikipedia.org/wiki/Legacy_of_Kain:_Soul_Reaver'),
  ('Q1810472', 'Space Station Silicon Valley est un jeu vidéo de plates-formes sorti en 1998 sur Nintendo 64. Le jeu est développé par DMA Design (devenu Rockstar North) et édité par Take-Two Interactive. Une version sort peu de temps après sur Game Boy Color; puis, en 2000, le jeu est porté sur PlayStation sous le titre Evo''s Space Adventures.', 'https://fr.wikipedia.org/wiki/Space_Station_Silicon_Valley'),
  ('Q1758708', 'Technomage: En quête de l’éternité (Technomage: Return of Eternity) est un jeu vidéo de rôle développé et édité par Sunflowers, sorti en 2001 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/Technomage_:_En_qu%C3%AAte_de_l%27%C3%A9ternit%C3%A9'),
  ('Q1780344', 'Strider est un jeu vidéo d''action-plates-formes développé et édité par Capcom sur système d''arcade CP System en mars 1989. Son système de jeu novateur fit de ce jeu un des grands succès de l''éditeur nippon, avant Street Fighter II. Le jeu fut adapté sur console de jeu, console portable et micro-ordinateurs. Il est basé sur le manga Strider Hiryu créé par Moto Kikaku et c''est le premier jeu de la série Strider.', 'https://fr.wikipedia.org/wiki/Strider_(jeu_vid%C3%A9o,_mars_1989)'),
  ('Q1767176', 'SimCity 2000 est un jeu vidéo de gestion de type city-builder développé par Maxis et édité à partir de 1994. Initialement commercialisé sur DOS et Mac OS, le jeu a été porté sur divers micro-ordinateurs et consoles. C''est le second opus de la série SimCity.

En 1995, SimCity 2000 a reçu l''Origins Award du « meilleur jeu de stratégie sur ordinateur ».', 'https://fr.wikipedia.org/wiki/SimCity_2000'),
  ('Q1757803', 'Vib-Ribbon est un jeu vidéo de rythme développé par la société japonaise NanaOn-Sha et édité par Sony Computer Entertainment en 1999 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Vib-Ribbon'),
  ('Q2015773', 'WWF Attitude est un jeu vidéo de catch professionnel basé sur l''univers de la World Wrestling Federation (désormais WWE) commercialisé par Acclaim Entertainment en 1999 initialement sur consoles PlayStation et Nintendo 64. Une adaptation sur Dreamcast et Game Boy Color a par la suite été commercialisée.

Il s''agit de la suite du jeu WWF War Zone et du dernier jeu vidéo WWF à être publié par Acclaim. La WWF signe un contrat avec THQ plus tard en 1999, mettant ainsi fin au partenariat avec Acclaim. Par la suite, Acclaim signe un partenariat avec la Extreme Championship Wrestling, et développe deux jeux en son nom intitulés ECW Hardcore Revolution et ECW Anarchy Rulz.', 'https://fr.wikipedia.org/wiki/WWF_Attitude'),
  ('Q2019330', '3Xtreme est un jeu vidéo de sport de glisse développé et édité par 989 Studios, sorti en 1999 sur PlayStation. Le jeu propose de participer à des courses de BMX, de roller ou de skateboard, comme c''était déjà le cas dans 2Xtreme, le précédent opus de la série.', 'https://fr.wikipedia.org/wiki/3Xtreme'),
  ('Q2019386', '2Xtreme est un jeu vidéo de sport de glisse développé et édité par Sony Computer Entertainment en 1996 sur PlayStation. Il s''agit de la suite de ESPN Extreme Games et précède 3Xtreme.

Sponsorisé par ESPN, le jeu permet au joueur de choisir entre différents sports extrêmes (roller, vélo, snowboard et skateboard) pour faire la course avec d''autres concurrents à travers le monde.', 'https://fr.wikipedia.org/wiki/2Xtreme'),
  ('Q2020334', 'WCW Backstage Assault est un jeu vidéo de catch professionnel développé par Electronic Arts. Il s''agit du dernier jeu vidéo de la World Championship Wrestling à être commercialiser avant le rachat de la fédération par la World Wrestling Federation. Le jeu comprend les commentaires de Tony Schiavone (en) et Bobby « The Brain » Heenan.', 'https://fr.wikipedia.org/wiki/WCW_Backstage_Assault'),
  ('Q2014874', 'Mega Man 3 ou Mega Man III (Rockman 3: Dr. Wily no Saigo!? au Japon), est un jeu d''action-plates-formes développé et édité par Capcom sur console NES en 1990, puis porté sur borne d''arcade (PlayChoice-10), PlayStation, Console virtuelle (Wii, Wii U, Nintendo 3DS), PlayStation Network (PlayStation 3, PlayStation Portable), et téléphone mobile (J2ME, Android, iOS). C''est le troisième jeu de la série principale de Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_3_(jeu_vid%C3%A9o,_1990)'),
  ('Q2014882', 'Mega Man 2 (Rockman 2 au Japon) est un jeu de plates-formes développé et édité par Capcom sur NES en 1988, puis porté sur Console virtuelle (Wii, Wii U, Nintendo 3DS), et téléphone mobile (J2ME, iOS). C''est le deuxième jeu de la série principale de Mega Man. Le jeu est un gros succès commercial pour Capcom, avec plus d''un million et demi de copies écoulées, faisant de cet opus la meilleure vente de la série.', 'https://fr.wikipedia.org/wiki/Mega_Man_2'),
  ('Q1115082', 'Syndicate Wars est un jeu vidéo de tactique en temps réel développé par Bullfrog, sorti en 1996. Suite de Syndicate (1993). Il est situé dans un univers futuriste cyberpunk.

Comme son prédécesseur, il est particulièrement novateur pour l''époque grâce à son mode de jeu et aussi grâce à ses graphismes en 3D temps réel. Le joueur est aux commandes de deux organisations souhaitant faire main basse sur le monde: un syndicat du crime high tech ou une secte futuriste. Pour arriver à ses fins, le joueur peut tout utiliser: espionnage industriel, meurtre, enlèvement, destruction de matériel, l''équipe d''agents doit s''adapter pour accomplir chacune des missions (en utilisant la violence de préférence).', 'https://fr.wikipedia.org/wiki/Syndicate_Wars'),
  ('Q198081', 'The King of Fighters ''94 est un jeu vidéo de combat développé et édité par SNK sur Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD en 1994 (NGM 055).

Il s''agit du premier épisode de la série The King of Fighters.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_%2794'),
  ('Q198096', 'The King of Fighters ''98: The Slugfest, couramment abrégé KOF ''98, est un jeu vidéo de combat développé et édité par SNK sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES et Neo-Geo CD en 1998 (NGM 242). Sous-titré « Dream Match Never Ends » au Japon et « The Slugfest » aux États-Unis, il est le cinquième épisode de la série The King of Fighters. Cet épisode est un « Dream Match »: il ne s''inscrit pas dans la continuité scénaristique des épisodes précédents, ne possède pas d''histoire établie et intègre des personnages apparus dans les opus précédents (KOF ''94 à ''97), indépendamment du fait que ces personnages peuvent être décédés dans l''histoire continue de la série (qui sera repris dans l''épisode suivant avec une nouvelle histoire).', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_%2798:_The_Slugfest'),
  ('Q136597', 'Z est un jeu vidéo de stratégie en temps réel développé par Bitmap Brothers et publié le 31 juillet 1996 sous MS-DOS. Il oppose deux armées de robots se disputant la possession des planètes occupées. Le jeu sera ensuite porté sur PlayStation, Saturn, Mac OS, ainsi qu''une version Windows 95. La suite, Z: Steel Soldiers sera développée en 2001.

Le jeu a été bien accueilli par la presse du jeu vidéo pour ses graphismes, son humour et son intelligence artificielle, mais il n''a pas eu autant d''influence auprès des joueurs que les jeux Command and Conquer: Conflit du Tibérium ou encore Warcraft II: Tides of Darkness, se situant dans le même genre vidéoludique et parus pendant les deux années précédentes.', 'https://fr.wikipedia.org/wiki/Z_(jeu_vid%C3%A9o)'),
  ('Q214232', 'Final Fantasy VII est un jeu vidéo de rôle développé par Square (devenu depuis Square Enix) sous la direction de Yoshinori Kitase et sorti en 1997 sur Playstation, constituant le septième opus de la série Final Fantasy. Premier jeu de la série à être produit pour la console de Sony ainsi que pour les ordinateurs dotés de Windows, c’est aussi le premier Final Fantasy à utiliser des graphismes en 3D avec des personnages rendus en temps réel et des arrière-plans précalculés.

L’histoire du jeu, dans une perspective eschatologique, est centrée sur le combat d’un groupe éco-terroriste nommé « Avalanche » contre une puissante organisation appelée la « Shinra », qui exploite jusqu''à épuisement l’énergie vitale de la planète pour produire de l''énergie et des armes. Au fur et à mesure du jeu, le conflit s’intensifie et l''avenir du monde devient l''enjeu majeur.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_VII'),
  ('Q1967293', 'Twisted Metal est un jeu vidéo de combat motorisé développé par SingleTrac Entertainment et édité par Sony Computer Entertainment, sorti en 1995 sur PlayStation.

Twisted Metal a été réédité dans la collection « Greatest Hits ».', 'https://fr.wikipedia.org/wiki/Twisted_Metal_(jeu_vid%C3%A9o,_1995)'),
  ('Q1998794', 'Racing Simulation: Monaco Grand Prix (Monaco Grand Prix) est un jeu vidéo de Formule 1 sorti en 1999 sur Nintendo 64 et Dreamcast. Le jeu a été développé et édité par Ubisoft.', 'https://fr.wikipedia.org/wiki/Monaco_Grand_Prix:_Racing_Simulation_2'),
  ('Q74061', 'Star Wars: Rebel Assault II - The Hidden Empire est un jeu vidéo en full motion video, basé sur l''univers de Star Wars, où le joueur incarne Rookie One, un rebelle qui doit effectuer différentes missions (appelées "chapitres" dans le jeu), comme combattre dans l''espace ou détruire des bases de l''Empire, et voler des vaisseaux secrets. Il s''agit d''un scénario totalement inédit dans la saga.

Les cinématiques du jeu ont été tournées avec de vrais acteurs (Jamison Jones et Julie Eccles) spécialement pour le jeu, ce qui n''a jamais été refait depuis pour un jeu sous licence Star wars. De plus, pour chacun des 15 chapitres, si le héros meurt ou épuise l''ensemble de ses vies, des cinématiques spécialement tournées montrent la défaite du joueur et la victoire de l''Empire galactique. La fin du jeu diffère selon la difficulté choisie.', 'https://fr.wikipedia.org/wiki/Star_Wars:_Rebel_Assault_II_-_The_Hidden_Empire'),
  ('Q220665', 'Space Invaders スペースインベーダー (Supēsu Inbēdā) est un jeu vidéo développé par la société japonaise Taito, sorti en 1978 sur borne d''arcade. Il s''agit d''un shoot ''em up fixe. Tomohiro Nishikado conçoit et programme le jeu, en s''inspirant de plusieurs médias populaires de l''époque tels que Breakout ou La Guerre des mondes. Considéré comme le premier archétype du shoot ''em up, il est aussi l''un des titres les plus influents et célèbres de l''histoire du jeu vidéo.

Le principe est de détruire des vagues d''aliens au moyen d''un canon laser en se déplaçant horizontalement sur l''écran. Il fait partie des classiques du jeu vidéo au même titre que Pac-Man et d''autres de ses contemporains. Il contribue à élargir l''industrie du jeu vidéo au niveau mondial. Space Invaders rencontre un énorme succès populaire. Après sa sortie au Japon, il aurait entraîné une pénurie de pièces de 100 yens.[réf. nécessaire] En 2007, Taito annonce que le jeu a rapporté 500 millions de dollars de recettes depuis sa parution.', 'https://fr.wikipedia.org/wiki/Space_Invaders'),
  ('Q767086', 'Persona 2 correspond à deux jeux vidéo de rôle développés par la société japonaise Atlus et édités en deux titres distincts: Innocent Sin et Eternal Punishment. Ils sont sortis respectivement en 1999 et 2000 sur PlayStation, puis portés respectivement sur PlayStation Portable en 2011 et 2012. Les sous-titres sont en japonais des clins d''œil à Crime et Châtiment.', 'https://fr.wikipedia.org/wiki/Persona_2:_Innocent_Sin'),
  ('Q1974823', 'Zoop est un jeu vidéo de puzzle de Viacom International, Inc. sorti sur DOS, Jaguar, Mega Drive, PlayStation, Saturn, Super Nintendo, Game Boy et Game Gear en 1995.

Un mois avant sa sortie, Zoop est l''un des quatre jeux joués lors des tours préliminaires de la compétition Blockbuster World Video Game Championship II, un cas rare d''utilisation d''un jeu non encore sorti dans une compétition de jeux vidéo.', 'https://fr.wikipedia.org/wiki/Zoop'),
  ('Q153602', 'The Incredible Hulk: The Pantheon Saga est un jeu vidéo d''action développé par Silicon Dreams et édité par Eidos Interactive sur PlayStation et Saturn en 1996.', 'https://fr.wikipedia.org/wiki/The_Incredible_Hulk:_The_Pantheon_Saga'),
  ('Q1980794', 'NASCAR 99 est un jeu vidéo de course NASCAR sorti en 1998 sur PlayStation et Nintendo 64.

Le jeu est développé par Stormfront Studios et édité par EA Sports. Il s''agit du second titre NASCAR d''Electronic Arts, un an après NASCAR 98.', 'https://fr.wikipedia.org/wiki/NASCAR_99'),
  ('Q94501', 'Grand Theft Auto (souvent et communément abrégé en GTA) est un jeu vidéo d''action-aventure développé par DMA Design, sorti sur MS-DOS, Microsoft Windows et macOS en novembre 1997, puis porté sur PlayStation en février 1998. Il s''agit de l''épisode originel qui donnera son nom à une série désormais culte du domaine vidéoludique. Le joueur incarne un malfrat ayant pour objectif de commettre des vols à main armée tout en parcourant une ville dans divers véhicules terriens, marins ou aériens.

Le jeu est réédité sur Game Boy Color en novembre 1999. La version Windows du jeu est mise à disposition gratuitement sur le site web officiel de Rockstar Games depuis 2004, mais n''est plus actuellement en service. Elle est ensuite mise à disposition sur Steam le 4 janvier 2008 puis retiré de la plateforme en 2023.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto_(jeu_vid%C3%A9o)'),
  ('Q1998483', 'Ronaldo V-Football est un jeu vidéo de sport (football) développé par PAM Development et édité par Infogrames, sur PlayStation, Game Boy et Game Boy Color.

Il tient son nom du joueur brésilien Ronaldo.', 'https://fr.wikipedia.org/wiki/Ronaldo_V-Football'),
  ('Q1998508', 'TOCA 2 Touring Cars est un jeu vidéo de course automobile développé par le studio britannique Codemasters sur PlayStation et PC. Il est sorti en Europe en décembre 1998, puis en novembre 1999 en Amérique du Nord, où, édité par Activision, il est intitulé TOCA 2 Touring Car Challenge. Il fait suite à TOCA Touring Car Championship, publié en 1997.

Le jeu met en scène les écuries et les circuits du championnat britannique des voitures de tourisme 1998 dans divers modes de jeu, dont le championnat, permettant au joueur d''affronter les pilotes de la saison 1998 ou de s''adonner au multijoueur. L''une des principales nouveautés du jeu réside dans la présence du mode championnat de soutien, qui permet au joueur de prendre part à des courses au volant d''autres voitures.', 'https://fr.wikipedia.org/wiki/TOCA_2_Touring_Cars'),
  ('Q94460', 'Grand Theft Auto 2 (souvent abrégé en GTA 2) est un jeu vidéo d''action-aventure développé par DMA Design et distribué par Rockstar Games, commercialisé le 30 septembre 1999 sur Microsoft Windows, et le 22 octobre 1999 sur PlayStation. Le jeu est ensuite adapté sur Dreamcast (ce qui en fait le premier opus de la franchise à cheval sur deux générations de consoles), et plus tard sur Game Boy Color. Il s''agit du quatrième opus et du second volet majeur de la série Grand Theft Auto. En décembre 2004, Rockstar offre le jeu en téléchargement gratuit sur son site officiel.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto_2'),
  ('Q1133204', 'Street Fighter II: The World Warrior est un jeu vidéo de combat développé et édité par Capcom, sorti en 1991 sur système d''arcade CP System, et sujet à un très grand nombre d''adaptations, y compris sur les téléphones Blackberry. Le jeu fait s''affronter plusieurs personnages dans des combats en un-contre-un. Le premier joueur mettant KO son adversaire par deux fois sort victorieux du combat.

Street Fighter II propose huit personnages jouables de base et sept styles de combat différents, un système de jeu novateur, des graphismes et une bande sonore riche et variée. Street Fighter II est considéré comme l''une des références des jeux de combat en un-contre-un, en plus d''en être l''un des pionniers.', 'https://fr.wikipedia.org/wiki/Street_Fighter_II:_The_World_Warrior'),
  ('Q189784', 'Doom, ou DOOM, est un jeu vidéo de tir à la première personne (en anglais First person shooter ou FPS), développé et édité par id Software et publié le 10 décembre 1993.

Doom fait partie des premiers jeux vidéo à utiliser des graphismes en 3D immersive, à présenter un mode de jeu multijoueur en réseau et à permettre aux joueurs de créer leur propre contenu pour le jeu.

Distribué en tant que shareware (partagiciel, que l''on peut essayer gratuitement de manière limitée), Doom a été téléchargé approximativement 10 millions de fois en une année, popularisant ainsi un type de gameplay et engendrant une sous-culture par lui-même.', 'https://fr.wikipedia.org/wiki/Doom_(jeu_vid%C3%A9o,_1993)'),
  ('Q761815', 'Chrono Trigger est un jeu vidéo de rôle, développé et édité par Square sur Super Nintendo le 11 mars 1995 au Japon et le 11 août 1995 en Amérique du Nord. Le jeu est affiché en deux dimensions, se déroule au tour par tour dans une carte du monde en vue de dessus. Le scénario, qui s''inscrit dans une uchronie, relate les exploits d''un groupe de jeunes aventuriers transportés accidentellement dans le temps, qui découvrent que le monde court à sa destruction et cherchent les moyens de le sauver.

Le jeu est développé par une équipe composée de Yūji Horii, créateur de la série Dragon Quest, Hironobu Sakaguchi, celui de Final Fantasy, et Akira Toriyama, créateur de Dragon Ball. Yasunori Mitsuda compose la bande-son et est remplacé sur la fin du processus par Nobuo Uematsu, le compositeur de Final Fantasy, qui l''achève. Le jeu intègre plusieurs innovations, telles que son système de combat, abandonnant les rencontres aléatoires. Les combats se déroulent dans l''aire de jeu plutôt que dans une fenêtre de combat dédiée et l''usage du système Active Time Battle rajoute également du dynamisme au système au tour par tour. En outre, le joueur peut combiner les magies des personnages, et les attaques peuvent être choisies en fonction de leur effet dans l''espace et du placement des personnages. Enfin, le jeu propose un panel de plus d''une dizaine de fins différentes.', 'https://fr.wikipedia.org/wiki/Chrono_Trigger'),
  ('Q1997345', 'Moto Racer est un jeu vidéo de course de moto développé par Delphine Software, sorti en 1997 sur PlayStation et Windows.

Un remake, Moto Racer 15th Anniversary, réalisé par Nobilis et Anuman Interactive, est sorti en 2011 sur iPhone, iPad et iPod Touch. Il a ensuite été porté sur la plateforme Android.

Le jeu a connu plusieurs suites: Moto Racer 2 en 1998, Moto Racer World Tour en septembre 2000, Moto Racer 3 en 2001 (ce dernier ayant été réexaminé par Nobilis pour faire sortir « Moto Racer 3 Gold Edition » le 24 avril 2006) et Moto Racer 4 en 2016.', 'https://fr.wikipedia.org/wiki/Moto_Racer'),
  ('Q1986054', 'Vandal Hearts II est un jeu vidéo de rôle tactique japonais développé et édité par Konami sur PlayStation en 1999. C''est la suite du jeu Vandal Hearts.

Le jeu se concentre sur le personnage de Joshua, du village de Polata, dont le joueur suit le récit de son enfance à la fin d''une guerre civile qui a éclaté dans son pays d''origine. La version Européenne est localisée en Français, Anglais et Allemand.', 'https://fr.wikipedia.org/wiki/Vandal_Hearts_II'),
  ('Q1121317', 'Ehrgeiz est un jeu vidéo de combat développé par DreamFactory, sorti en 1998 sur borne d''arcade et en 1999 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Ehrgeiz'),
  ('Q761941', 'Die Hard Trilogy est un jeu vidéo d''action basé sur la série de films Die Hard, développé par Probe Entertainment, commercialisé sur les consoles PlayStation, Saturn et sur Microsoft Windows en 1996. Die Hard Trilogy est composé de trois jeux en un, chacun étant basé sur l''un des trois premiers films de la saga Die Hard et possédant un gameplay différent des deux autres.

Dans les trois éditions, le joueur incarne le personnage de John McClane. Le jeu a également une suite, Die Hard Trilogy 2: Viva Las Vegas, qui conserve les trois genres de jouabilité, mais dont l''histoire varie par rapport à celle des films.', 'https://fr.wikipedia.org/wiki/Die_Hard_Trilogy'),
  ('Q1978200', 'Twisted Metal III est le troisième épisode de la série de jeux de combat motorisé Twisted Metal, sorti en 1998. Le jeu devint un best-seller, et comme ses prédécesseurs, il a été réédité dans la collection « Greatest Hits » de Sony.', 'https://fr.wikipedia.org/wiki/Twisted_Metal_III'),
  ('Q756646', 'Atlantis: Secrets d''un monde oublié (ou Atlantis tout court, en anglais Atlantis: The Lost Tales) est un jeu vidéo d''aventure développé et édité par le studio français Cryo Interactive et sorti en 1997. Il est le premier de la série de jeux d''aventure Atlantis.

Le jeu se déroule dans l''univers mythologique de l''Atlantide. La reine Rhéa est enlevée au début de l''aventure. Le héros du jeu, Seth, qui fait partie des Compagnons de la reine, mène l''enquête et lève peu à peu le voile sur un complot politique dont les enjeux le conduisent à explorer le mystère des origines de la civilisation atlante. Au cours du jeu, Seth voyage hors de l''Atlantide et se rend dans plusieurs lieux historiques liés aux principales théories ésotériques relatives aux origines de la civilisation atlante: Stonehenge, le Spitzberg et l''île de Pâques.', 'https://fr.wikipedia.org/wiki/Atlantis_:_Secrets_d%27un_monde_oubli%C3%A9'),
  ('Q810984', 'Battle Arena Toshinden est jeu de combat développé par Tamsoft et édité par Takara et Sony Interactive Entertainment en 1995/1996 sur PlayStation, Sega Saturn, Game Boy et MS-DOS. Battle Arena Toshinden est l''un des premiers jeux de combat en 3D après Tekken et Virtua Fighter.

Le titre est d''abord publié en tant qu''exclusivité pour la PlayStation le 1er janvier 1995 au Japon, le 9 septembre 1995 en Amérique du Nord et le 29 septembre 1995 en Europe. Battle Arena Toshinden fait partie des jeux de lancement pour les versions américaine et européenne de la PlayStation. Il est ensuite porté sur Sega Saturn courant 1996 sous le titre de Toh Shin Den S pour le Japon et Battle Arena Toshinden Remix pour l''Amérique du Nord et l''Europe. La version saturn comporte un personnage en plus, du nom de Cupido.', 'https://fr.wikipedia.org/wiki/Battle_Arena_Toshinden'),
  ('Q845417', 'LSD est un jeu vidéo d''aventure expérimental développé et édité par Asmik Ace Entertainment, sorti en 1998 sur PlayStation.

Il a été créé d''après le journal de rêves de Hiroko Nishikawa, une membre de l''équipe de développement, qu''elle avait tenu pendant une décennie. Il s''agit d''un des trois produits sortis liés à ce journal (les autres étant un CD de musique, appelé LSD And Remixes et le journal lui-même, publié sous le nom de Lovely Sweet Dream en nombre de tirages limité).', 'https://fr.wikipedia.org/wiki/LSD_(jeu_vid%C3%A9o)'),
  ('Q798365', 'CT Special Forces est un jeu vidéo de type run and gun développé par LSP Games, sorti sur Game Boy Advance et PlayStation à partir de 2002. Son gameplay et son univers visuel s''inspirent de la série Metal Slug et d''autres jeux dans le même genre.

Le jeu met en scène deux personnages jouables, Stealth Owl et Raptor, membre l''organisation CT Special Forces qui lutte contre une organisation terroriste internationale. Le jeu propose quatre missions à travers le monde (Russie, Somalie, Amérique du Sud, Europe). Le jeu intercale dans son gameplay principal des phases de jeux annexes comme du saut en parachute et des séquences de sniper.', 'https://fr.wikipedia.org/wiki/CT_Special_Forces'),
  ('Q845290', 'Civilization II, abrégé Civ II ou Civ 2, est un jeu 4X de stratégie au tour par tour qui retrace l''évolution de grandes civilisations humaines, du XLe siècle av. J.-C. jusqu''au XXIe siècle. Il fut développé et édité par MicroProse. L''auteur principal en est Brian Reynolds, et Douglas Caspian-Kaufman et Jeff Briggs (en) participèrent à sa réalisation. Civilization II représente le deuxième volet de la série Civilization, mais ni Sid Meier, créateur du premier Civilization, ni Bruce Shelley, collaborateur de Sid Meier, ne furent impliqués dans son développement.

La première version de Civilization II sort le 29 février 1996, mais uniquement en version anglaise et pour Windows. Suscitant l''intérêt de joueurs du monde entier, le jeu est traduit en plusieurs langues; la version française est commercialisée en 1997. Civilization II est ensuite adapté à la PlayStation (édité par Activision) et au Mac (édité par MacPlay). Plusieurs extensions officielles et de nombreux correctifs enrichissent le jeu.', 'https://fr.wikipedia.org/wiki/Civilization_II'),
  ('Q840431', 'Shin Megami Tensei if... est un opus à part dans la branche officielle de Shin Megami Tensei. Bien qu''il ne soit pas numéroté comme le troisième opus, il n''est pas considéré comme un spin-off par les développeurs.

Il s''agit d''un RPG japonais édité par Atlus en 1994 sur la Super Famicom. Il n''est jamais sorti en dehors du Japon.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei_if...'),
  ('Q796510', 'Breath of Fire IV est un jeu vidéo de type jeu de rôle, développé par Capcom Production Studio 3 et édité par Capcom, qui signe là, le 4e volet de la série. Le jeu est sorti sur PlayStation en 2000 - 2001 dans le monde. Le portage PC lui, n''est sorti qu''en 2003.', 'https://fr.wikipedia.org/wiki/Breath_of_Fire_IV'),
  ('Q1992015', 'R-Type Delta ou R-TYPE Δ est un jeu vidéo de type shoot ''em up en 3D développé par Irem, sorti sur PlayStation en 1998 au Japon, puis en 1999 aux États-Unis et en Europe.', 'https://fr.wikipedia.org/wiki/R-Type_Delta'),
  ('Q773090', 'Tobal n°1 est un jeu de combat sorti sur PlayStation en 1996.', 'https://fr.wikipedia.org/wiki/Tobal_n%C2%B01'),
  ('Q1992748', 'Shin Megami Tensei II est un jeu vidéo de rôle développé et édité par Atlus. Il sort sur Super Nintendo en 1994, puis est réédité sur Mega-CD, sur PlayStation et sur Game Boy Advance en 2001.

Il s''agit de la suite directe de Shin Megami Tensei.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei_II'),
  ('Q776211', 'Premier Manager est une série de jeux vidéo de gestion sportive (football) créée en 1992.', 'https://fr.wikipedia.org/wiki/Premier_Manager'),
  ('Q1991333', 'International Superstar Soccer Pro 98 est un jeu vidéo de football développé par KCET et édité par Konami, sorti en 1998 sur PlayStation.', 'https://fr.wikipedia.org/wiki/International_Superstar_Soccer_Pro_98'),
  ('Q1989219', 'NBA Live 99 est un jeu vidéo de basket-ball sorti en 1998 et fonctionne sur PlayStation, Windows et Nintendo 64. Le jeu a été développé par EA Sports puis édité par EA Sports.', 'https://fr.wikipedia.org/wiki/NBA_Live_99'),
  ('Q840308', 'Crash Bandicoot 3: Warped est un jeu vidéo de plates-formes développé par Naughty Dog et édité par Sony Computer Entertainment en 1998 sur PlayStation. Le jeu est réédité pour la gamme Greatest Hits le 23 août 1999 et The Best for Family le 14 octobre 1999 ainsi que pour la gamme Platinum en 2000. Il est également disponible sur PlayStation Store depuis septembre 2007 au Japon et 2008 en Amérique du Nord et en Europe. C''est le troisième épisode de la série Crash Bandicoot, débutée en 1996. Un remake de cet épisode est inclus dans la compilation Crash Bandicoot: N. Sane Trilogy sortie en 2017 sur PlayStation 4.', 'https://fr.wikipedia.org/wiki/Crash_Bandicoot_3:_Warped'),
  ('Q1992120', 'Sentinel Returns est un jeu vidéo de puzzle sorti en 1998 sur PlayStation et sous Windows. Il fait suite au jeu de puzzle 3D The Sentinel édité par Firebird en 1986 et disponible sur la majorité des ordinateurs de l''époque.

Tout comme son prédécesseur avant-gardiste, Sentinel Returns présente en vue subjective un environnement en 3D intégrale. Si la vue subjective était une gageure en 1986 (et reposait sur un principe ingénieux mais limitatif), ce second opus profite pour sa part des technologies de son temps et remplace la performance technique du premier épisode par l''utilisation d''un moteur 3D temps réel.', 'https://fr.wikipedia.org/wiki/Sentinel_Returns'),
  ('Q2302461', 'Breath of Fire III est un jeu vidéo de rôle développé et édité par Capcom sur PlayStation. Originellement commercialisé au Japon en 1997, le jeu sorti en Amérique du Nord et en Europe en 1998. C''est le troisième opus de la série Breath of Fire, et le premier à présenter des environnements et des éléments en trois dimensions, ainsi que plusieurs nouveaux éléments de gameplay, comme un système de combat plus complet, la capacité d''apprendre les compétences d''ennemis, et l''interaction avec l''environnement. En 2005, Breath of Fire III est porté sur PlayStation Portable au Japon, puis en 2006 en Europe, mais uniquement en anglais.', 'https://fr.wikipedia.org/wiki/Breath_of_Fire_III'),
  ('Q2302721', 'Mega Man 8 (sous-titré Anniversary Edition aux États-Unis, Rockman 8: Metal Heroes au Japon) est un jeu d''action-plate-formes développé et édité par Capcom sur PlayStation en 1996 et Saturn en 1997, puis réédité sur PlayStation Network (PlayStation 3, PlayStation Portable, PlayStation Vita). C''est le huitième jeu de la série principale de Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_8'),
  ('Q2300289', 'Ace Combat 3: Electrosphere est un jeu vidéo de simulateur de vol de combat développé par Namco, édité par Namco et SCEE, sorti en 1999 sur PlayStation. Il fait partie de la série de jeux vidéo Ace Combat.

L''histoire se déroule entre le premier janvier et le 21 juillet 2040. Les nations de Strangereal sont dissoutes et remplacés par une corporatocratie globale dont les deux plus puissantes sociétés sont la General Resource LTD et Neucom Incorporated.

Dans ce simulateur de vol, le joueur incarne un pilote de l''UPEO et combat avec ses forces des airs contre des terroristes, ou contre des puissances économiques ou militaires (par exemple, la General Resource ou Neucom Technology Inc.). Le joueur peut très bien se retrouver à soutenir un camp dans une mission, et l''autre camp dans une autre mission.', 'https://fr.wikipedia.org/wiki/Ace_Combat_3:_Electrosphere'),
  ('Q2304471', 'King''s Field II est un jeu vidéo de type dungeon crawler développé et édité par FromSoftware sorti en 1995 sur PlayStation.', 'https://fr.wikipedia.org/wiki/King%27s_Field_II'),
  ('Q1994927', 'Paro Wars est un jeu vidéo de tactique au tour par tour appartenant à la série de jeux vidéo Parodius, développé par Konami, sorti sur PlayStation en 1997 (avec la réédition en tant que le titre de Konami the Best en décembre 1999).', 'https://fr.wikipedia.org/wiki/Paro_Wars'),
  ('Q843486', 'Mortal Kombat II, communément abrégé MKII, est un jeu vidéo de combat développé par la société américaine Midway Manufacturing Company et initialement sorti en novembre 1993 sur borne d''arcade. Il s''agit du second titre de la série Mortal Kombat.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_II'),
  ('Q845526', 'Uncharted Waters II: New Horizons est un jeu vidéo de rôle sorti à partir de 1994 sur DOS, Windows, FM Towns, PC-98, X68000, Mega Drive, Super Nintendo, PlayStation et Saturn. Le jeu a été développé et édité par Koei. Il fait suite à Uncharted Waters.', 'https://fr.wikipedia.org/wiki/Uncharted_Waters_II:_New_Horizons'),
  ('Q2007458', 'Gauntlet Legends est un jeu vidéo d''action RPG sorti en 1998 sur borne d''arcade, Nintendo 64, Dreamcast et PlayStation. Le jeu a été initialement développé par Atari Games puis édité sur consoles par Midway Games.

Il s''agit de la suite de Gauntlet et Gauntlet II, sortis respectivement en 1985 et 1986.', 'https://fr.wikipedia.org/wiki/Gauntlet_Legends'),
  ('Q2007022', 'Castlevania: Symphony of the Night — titre original japonais: Akumajō Dracula X Gekka no Yasōkyoku: 悪魔城ドラキュラX 月下の夜想曲 — est un jeu vidéo de type metroidvania développé et édité par Konami en 1997 sorti sur PlayStation puis l’année suivante sur Saturn. Le jeu a été conçu par Koji Igarashi et Ayami Kojima.

Cet épisode est souvent mentionné pour être l''un des meilleurs de la série Castlevania, avec l''épisode Akumajō Dracula X: Chi no Rondo, dont il constitue la suite directe.

Le jeu a été adapté en 1998 sur Saturn (sorti au Japon uniquement) et réédité en 2007 sur Xbox 360, via le Xbox Live Arcade.', 'https://fr.wikipedia.org/wiki/Castlevania:_Symphony_of_the_Night'),
  ('Q784447', 'Puzzle Bobble 3 (aussi appelé Bust-a-Move 3, Bust-a-Move 3 DX ou Bust-a-Move ''99) est un jeu vidéo de puzzle sorti en 1997 sur Sega Saturn, puis en 1998 sur Nintendo 64, PlayStation et Game Boy. Le jeu a été développé par Taito et édité par Acclaim.

Le jeu fait partie de la série Puzzle Bobble.', 'https://fr.wikipedia.org/wiki/Puzzle_Bobble_3'),
  ('Q2301154', 'Tales of Eternia est un jeu vidéo de rôle développé par Wolf Team et édité par Namco qui a été conçu pour la console de jeu PlayStation. Ce jeu fait partie de la série de jeux vidéo Tales of. Il est réédité à partir de 2005 sur PlayStation Portable.

Une version remasterisée intitulée Tales of Eternia Remastered est prévue pour le 16 octobre 2026. Le jeu sera pour la première fois disponible en français.', 'https://fr.wikipedia.org/wiki/Tales_of_Eternia'),
  ('Q779988', 'Rapid Racer est un jeu vidéo de course nautique développé par SCE Studio Soho et édité par Sony Computer Entertainment, sorti en 1997 sur PlayStation. Il a été conçu par les créateurs de Porsche Challenge (1997).

Le jeu est titré Turbo Prop Racing en Amérique du Nord et Rapid Racer au Japon.', 'https://fr.wikipedia.org/wiki/Rapid_Racer'),
  ('Q844223', 'Romance of the Three Kingdoms III: Dragon of Destiny est un jeu vidéo de grande stratégie développé et édité par Koei en 1992. C''est le troisième titre d''une série populaire, qui en est rendu à sa onzième édition en 2007.

Inspiré du roman Histoire des Trois Royaumes écrit par Luo Guanzhong au XIVe siècle, ce jeu fait partie des séries de simulation historique développées par Koei telles que Nobunaga''s Ambition, Genghis Khan et Uncharted Waters.', 'https://fr.wikipedia.org/wiki/Romance_of_the_Three_Kingdoms_III'),
  ('Q2040154', 'Viewpoint est un jeu vidéo de type shoot ''em up en 3D isométrique sorti en 1992 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES, puis sur Neo-Geo CD en 1995 (NGM 051). Le jeu est par la suite porté sur Mega Drive et PlayStation, Saturn, ainsi que sur les systèmes Sharp X68000 et FM Towns.', 'https://fr.wikipedia.org/wiki/Viewpoint'),
  ('Q1141304', 'Bugs Bunny et Taz: La Spirale du temps (Bugs Bunny and Taz: Time Busters) est un jeu vidéo se déroulant dans l''univers des Looney Tunes, sorti sur PlayStation et PC en 2000.

Il s''agit d''une suite indirecte du jeu Bugs Bunny: Voyage à travers le temps, développé sur les mêmes supports et sorti en 1999.', 'https://fr.wikipedia.org/wiki/Bugs_Bunny_et_Taz_:_La_Spirale_du_temps'),
  ('Q2322709', 'Coupe du monde FIFA 2002 (2002 FIFA World Cup) est un jeu vidéo de football développé par Electronic Arts et sorti en 2002.

C''est le jeu officiel de la Coupe du monde de football 2002 qui a eu lieu en Corée du Sud et au Japon. Le jeu reprend toutes les équipes nationales qui ont participé à cette compétition. Tous les joueurs et toutes les statistiques des équipes ont été incluses dans le jeu. Il est sorti sur la plupart des consoles de jeux vidéo de l''époque (PlayStation, PS2, GameCube, Xbox et GBA) et sur PC à l''occasion de l''ouverture de la Coupe du monde.', 'https://fr.wikipedia.org/wiki/Coupe_du_monde_FIFA_2002_(jeu_vid%C3%A9o)'),
  ('Q1158895', 'Madden NFL 2004 est un jeu vidéo de sport (football américain) sorti en 2003 sur PlayStation, PlayStation 2, Xbox, GameCube, Game Boy Advance et PC (Windows).

Le jeu fait partie de la série Madden NFL.', 'https://fr.wikipedia.org/wiki/Madden_NFL_2004'),
  ('Q1170309', 'Destruction Derby 2 est un jeu vidéo de course de stock-car développé par Reflections Software et édité par Psygnosis en 1996 sur PC et PlayStation. Il s''agit de la suite de Destruction Derby.', 'https://fr.wikipedia.org/wiki/Destruction_Derby_2'),
  ('Q2042305', 'Overboard!, appelé Shipwreckers! aux États-Unis, est un jeu vidéo d''action développé et édité par Psygnosis en 1997 sur compatible PC et PlayStation.

Aux commandes d''un galion, le joueur parcourt les mers à la recherche de trésors perdus. Le périple l''amène à affronter monstres marins et bateaux pirates ainsi qu''à résoudre quelques énigmes de progression.', 'https://fr.wikipedia.org/wiki/Overboard!'),
  ('Q374320', 'Hercule (titre complet: Disney jeu d''action - Disney présente Hercule) est un jeu vidéo de plates-formes, développé par Eurocom et édité par Disney Interactive, sorti en Europe en 1997 sur PlayStation, Windows et Game Boy. C''est l''adaptation du dessin animé éponyme sorti la même année. En 2009, le jeu paraît sur le PlayStation Network.', 'https://fr.wikipedia.org/wiki/Hercule_(jeu_vid%C3%A9o,_1997)'),
  ('Q2052976', 'Tales of Fandom Vol.1 est un jeu vidéo d''aventure développé et édité par la société japonaise Namco sur PlayStation en 2002 sous deux versions, Cless et Mint.', 'https://fr.wikipedia.org/wiki/Tales_of_Fandom_Vol.1'),
  ('Q2305500', 'Final Fantasy I and II Premium Package est une compilation collector de deux jeux vidéo de rôle développée par Square Co., Ltd., sortie sur PlayStation en 2002 au Japon ainsi qu''en 2003 en Europe et Amérique du Nord. Dans ces deux dernières régions, la compilation a été publiée sous le nom Final Fantasy Origins et sous forme d''une édition ordinaire.

Il s''agit d''un coffret collector regroupant les versions PlayStation des deux jeux, qui sont également sortis séparément le même jour au Japon en édition ordinaire. Ils sont basés sur les remakes WonderSwan Color de Final Fantasy et Final Fantasy II, dont ils sont proches graphiquement.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_Origins'),
  ('Q2052915', 'Fear Effect 2: Retro Helix est un jeu vidéo d''action-aventure développé par Kronos Digital Entertainment (en) et édité par Eidos Interactive en 2001 sur PlayStation. C''est la préquelle de Fear Effect.', 'https://fr.wikipedia.org/wiki/Fear_Effect_2:_Retro_Helix'),
  ('Q535940', 'Final Fantasy VI est un jeu vidéo de rôle, développé et publié par Square Co., Ltd. (maintenant Square Enix) en 1994 pour la console de jeux vidéo Super Nintendo. Final Fantasy VI est ressorti pour la PlayStation en 1999, pour la Game Boy Advance en 2006 puis sur la Console Virtuelle de la Nintendo Wii en 2011.

Final Fantasy VI est le dernier titre de la série à être sorti sur Super Nintendo, et le premier Final Fantasy de la série où Hironobu Sakaguchi, créateur de la série, a produit plutôt que dirigé.

Final Fantasy VI n''est que le troisième jeu de la série à être sorti en Amérique du Nord (suivant la sortie du premier Final Fantasy et de Final Fantasy IV, respectivement nommés Final Fantasy et Final Fantasy II), la localisation américaine du jeu a été lancée sur le marché sous le titre Final Fantasy III. Quand Square a ressorti le jeu pour la console PlayStation en Amérique du Nord dans la collection Final Fantasy Anthology, le nom japonais a été restauré ainsi que le système de numérotation original. Le jeu ne bénéficiait d''une sortie officielle européenne et australienne qu''en 2002, accompagné d''une démo jouable de Final Fantasy X. Malgré tout, le jeu était populaire sur le marché des jeux importés en Europe et en Australie durant le milieu des années 1990. Il est à nouveau publié sous le titre de Final Fantasy III lors de sa réédition sur Super Nintendo Mini en 2017 en Amérique du Nord et en Europe.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_VI'),
  ('Q536833', 'Nightmare Creatures est un jeu vidéo de type beat''em all à composante horrifique sorti en 1997 sur PC, Nintendo 64 et PlayStation. Le jeu a été développé par Kalisto Entertainment et édité par Sony Computer Entertainment et Activision.', 'https://fr.wikipedia.org/wiki/Nightmare_Creatures'),
  ('Q1143139', 'Gex: Enter the Gecko (Gex 64: Enter the Gecko sur Nintendo 64, Gex 3D: Enter the Gecko sur PlayStation, PC) est un jeu vidéo de plate-forme et d''action-aventure en 3D sorti sur PlayStation, Game Boy Color, PC, et Nintendo 64 le 21 novembre 1997[réf. souhaitée].

C''est la résurrection d''un jeu de Crystal Dynamics sorti en 1994 sur 3DO. Gex est un lézard aux allures de James Bond, qui doit accomplir diverses missions dans chacun des niveaux du jeu, qui parodient l''univers télévisuel américain. Gex est la mascotte officielle de Crystal Dynamics durant l''année 1998.', 'https://fr.wikipedia.org/wiki/Gex:_Enter_the_Gecko'),
  ('Q384153', 'Speedball est un jeu vidéo de sport futuriste développé par The Bitmap Brothers et édité par Image Works en 1988 sur Amiga et Atari ST. Le jeu fut adapté sur Commodore 64, DOS, Master System et NES.', 'https://fr.wikipedia.org/wiki/Speedball_(jeu_vid%C3%A9o)'),
  ('Q839768', 'Wipeout 3 (stylisé wip3out) est un jeu vidéo de course futuriste développé et édité par Psygnosis sur PlayStation. Il s''agit du troisième épisode de la série Wipeout sur cette console, le quatrième toutes machines confondues, sorti le 31 août 1999 en Amérique du Nord, le 8 septembre 1999 en Europe et le 2 février 2000 au Japon. Le 14 juillet 2000, une réédition du jeu, Wipeout 3: Special Edition, est sortie exclusivement en Europe. Le joueur contrôle un vaisseau armé à grande vitesse dans le but d''éliminer ses adversaires de la course.

Le développeur de Wipeout 3, Psygnosis, a embauché l''entreprise de design graphique The Designers Republic pour créer un jeu aux couleurs, aux menus et aux circuits simples, afin de créer un environnement futuriste mais « crédible », selon un membre du personnel de Psygnosis. C''est l''un des seuls jeux de la PlayStation à être en haute résolution, offrant un graphisme plus net. La bande-son de Wipeout 3 est composée de musiques techno et électro, créées par Sasha, Orbital et The Chemical Brothers.', 'https://fr.wikipedia.org/wiki/Wipeout_3'),
  ('Q2326787', 'Test Drive 5 est un jeu vidéo de course automobile développé par Pitbull Syndicate et édité par Accolade en 1998. Le jeu est sorti sur PC et PlayStation. Il est le cinquième jeu de la série Test Drive, dont la première production est sortie en 1987.', 'https://fr.wikipedia.org/wiki/Test_Drive_5'),
  ('Q2310470', 'Dragon Quest IV est un jeu vidéo de rôle développé par Chunsoft pour l''éditeur japonais Enix. Il sort sur NES en février 1990 au Japon puis en octobre 1992 en Amérique du Nord.

Le jeu est porté sur PlayStation par Heartbeat et ArtePiazza en 2001 puis sur Nintendo DS par ArtePiazza et Cattle Call en 2007. Cette dernière version est la première à être distribuée en Europe et bénéficie d''une traduction dans les principales langues européennes. À cette occasion, le jeu est renommé Dragon Quest: L''Épopée des élus dans sa version française.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_IV_:_L%27%C3%89pop%C3%A9e_des_%C3%A9lus'),
  ('Q2320677', 'Digimon World est un jeu vidéo de rôle, développé, distribué et édité par la société Bandai, initialement publié le 28 janvier 1999 au Japon sur console PlayStation. Le jeu est ensuite sorti le 27 juillet 2000 en Amérique du Nord, puis en juillet 2001 en Europe. Une version Windows est commercialisée en Corée du Sud le 27 avril 2002.

Digimon World inclut près de deux cents créatures numériques appartenant à la franchise médiatique Digimon, créée en 1997 par Akiyoshi Hongo. Il s''agit du deuxième jeu vidéo dérivé de la franchise, succédant Digital Monster Ver. S: Digimon Tamers, publié en 1998 sur Sega Saturn. Il met en scène un jeune garçon transporté dans le Digimonde, dont la mission est de convaincre les Digimon de revenir dans la Capitale qu''ils ont quittée après avoir perdu la mémoire. Pour ce faire, le protagoniste doit élever et entraîner son propre Digimon.', 'https://fr.wikipedia.org/wiki/Digimon_World'),
  ('Q834872', 'Crash Team Racing (abrégé en CTR et intitulé Crash Bandicoot Racing au Japon) est un jeu vidéo de course de karting paru en 1999, développé par le studio américain Naughty Dog et édité par Sony Computer Entertainment sur la console PlayStation. Il s''agit du quatrième jeu de la franchise Crash Bandicoot, du premier jeu de course de la série, et du dernier à avoir été développé par Naughty Dog.

Le scénario de Crash Team Racing est centré sur les personnages de la série Crash Bandicoot, défiés par l''égocentrique Nitros Oxide qui menace de détruire la Terre s''il les bat à la course. Dans cet opus, les joueurs peuvent choisir parmi quinze personnages de la franchise. Durant les courses, les joueurs peuvent tirer avantage de plusieurs objets leur permettant d’handicaper ou de rattraper leurs adversaires.', 'https://fr.wikipedia.org/wiki/Crash_Team_Racing'),
  ('Q524267', 'Frogger est un jeu vidéo d''arcade développé par Konami et sorti en 1981. Il est généralement considéré comme un classique de ce média.

Avant sa sortie, le jeu a failli être abandonné par la direction de Sega/Gremlin qui le jugeait trop enfantin. C''est Elizabeth Falconer, une analyste de marché de l''entreprise, qui a convaincu ses supérieurs de tester le jeu. Le prototype a été installé au ''''Spanky''s Saloon'''', un bar de San Diego fréquenté par une clientèle masculine adulte, où il a rencontré un succès immédiat, validant sa production.', 'https://fr.wikipedia.org/wiki/Frogger'),
  ('Q536851', 'Tenchu 2: Birth of the Stealth Assassins est un jeu vidéo d''infiltration, développé par Acquire, sorti sur PlayStation en 2000.', 'https://fr.wikipedia.org/wiki/Tenchu_2:_Birth_of_the_Stealth_Assassins'),
  ('Q385812', 'Prisoner of Ice (aussi publié sous le titre de Call of Cthulhu: Prisoner of Ice) est un jeu vidéo d''aventure sorti en 1995, basé sur l''univers du Mythe de Cthulhu de l''écrivain H.P. Lovecraft, et plus particulièrement sur le roman Les Montagnes hallucinées. Il fait « suite » au jeu Shadow of the Comet, publié en 1993.

Le jeu fut réédité en 1997, pour Sega Saturn et PlayStation, mais exclusivement au Japon.', 'https://fr.wikipedia.org/wiki/Prisoner_of_Ice'),
  ('Q1143911', 'Dragon Ball Z: Ultimate Battle 22 est un jeu vidéo de combat sur l''univers de Dragon Ball Z. Le jeu est distribué à partir de 1995 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Ultimate_Battle_22'),
  ('Q820527', 'Kuzco, l''empereur mégalo (The Emperor''s New Groove) est un jeu vidéo de plates-formes développé par Argonaut Games et édité par SCEA. Il est sorti en 2000 sur Windows, PlayStation.

Une version Game Boy Color a été développé par Sandbox Interactive et édité par Ubisoft.

Il est adapté du film du même nom.', 'https://fr.wikipedia.org/wiki/Kuzco,_l%27empereur_m%C3%A9galo_(jeu_vid%C3%A9o)'),
  ('Q1141140', 'Little Big Adventure (Relentless: Twinsen''s Adventure pour les éditions Activision), communément abrégé LBA1, est un jeu vidéo développé par le studio français Adeline Software International, sorti en 1994 sur MS-DOS, puis en 1997 sur PlayStation. À partir de 2011, le jeu a été rendu compatible avec les versions modernes de Windows et Mac OS par GOG.com. Le jeu connaît en 2014 un portage accompagné de nouvelles fonctionnalités: cette adaptation est réalisée par DotEmu pour appareils mobiles (Android et iOS) puis pour Windows. En 2022, le jeu est renommé Twinsen''s Little Big Adventure Classic par le studio [2.21] ayant acquis la propriété intellectuelle du jeu.', 'https://fr.wikipedia.org/wiki/Little_Big_Adventure'),
  ('Q1153468', 'Dune 2000 est un jeu vidéo de stratégie en temps réel développé par Westwood Studios, basé sur l''univers de Dune de Frank Herbert. Il est sorti en 1998 sur PC avant d''être porté sur PlayStation par Intelligent Games en 2000.

Il s''agit d''un remake amélioré du jeu Dune II. L''histoire du jeu est similaire à Dune II et se poursuit dans Emperor: Battle for Dune.', 'https://fr.wikipedia.org/wiki/Dune_2000'),
  ('Q1139035', 'Need for Speed II est un jeu vidéo de course sorti en 1997, produit par EA Canada et édité par Electronic Arts. Il fait partie de la série des Need for Speed et est la suite du premier jeu The Need for Speed.', 'https://fr.wikipedia.org/wiki/Need_for_Speed_II'),
  ('Q2055124', 'Galerians est un jeu vidéo de survival horror sorti sur PlayStation en juin 2000.

Une suite: Galerians: Ash est sortie en 2003 sur PlayStation 2.

un anime: Galerians: Rion, qui reprend l''histoire du jeu, est sorti en 2004.', 'https://fr.wikipedia.org/wiki/Galerians'),
  ('Q534497', 'Jonah Lomu Rugby est un jeu vidéo de rugby à XV sorti en 1997 sur PlayStation, PC et Saturn, développé par Rage Software et édité par Codemasters. Au Japon, en 1998, le jeu a été adapté sous le nom de Great Rugby Jikkyō ''98 World Cup Heno Michi et édité par Nexus Interact sur PlayStation. C''est le premier jeu de rugby à XV disponible sur la PlayStation. Il est possible d''y jouer seul ou à plusieurs.', 'https://fr.wikipedia.org/wiki/Jonah_Lomu_Rugby'),
  ('Q387425', 'Jeremy McGrath Supercross 2000 est un jeu vidéo de course sorti en 2000 sur Nintendo 64, Dreamcast, PlayStation, PlayStation 2 et Game Boy Color. Le jeu a été développé et édité par Acclaim.

Le jeu est centré sur le pilote Jeremy McGrath. Il a pour suite Jeremy McGrath Supercross World.', 'https://fr.wikipedia.org/wiki/Jeremy_McGrath_Supercross_2000'),
  ('Q1142893', 'Tekken est un jeu vidéo de combat développé et édité par Namco en 1994 initialement sur borne d''arcade, puis adapté l''année suivante sur PlayStation. Il s''agit du premier épisode de la série Tekken. C''est le premier jeu PlayStation à avoir dépassé la barre du million d''unités vendues. Tekken est la réplique de Namco au premier jeu de combat en 3D sorti en 1993: Virtua Fighter de Sega.', 'https://fr.wikipedia.org/wiki/Tekken_(jeu_vid%C3%A9o)'),
  ('Q1168166', 'G-Darius est un jeu vidéo de type shoot ''em up développé par Taito et sorti en 1997 sur borne d''arcade, PlayStation.', 'https://fr.wikipedia.org/wiki/G-Darius'),
  ('Q514168', 'Die Hard Trilogy 2: Viva Las Vegas est un jeu vidéo action-aventure succédant Die Hard Trilogy, inspiré des films de la franchise médiatique Die Hard, commercialisé en 2000 sur systèmes PlayStation et Microsoft Windows.

Comme pour le précédent opus, le jeu se divise en trois genre: tir en vue à la troisième personne, tir par pistolet optique, et jeu de course. Cependant, contrairement à Die Hard Trilogy, qui s''inspirait du scénario des trois premiers films Die Hard, Die Hard Trilogy 2 ne possède qu''un seul scénario séparé par trois genres de jeux distincts. Le jeu suit les aventures de John McClane tentant de déjouer les plans des terroristes à travers les décors de Las Vegas et dans le désert du Nevada.', 'https://fr.wikipedia.org/wiki/Die_Hard_Trilogy_2:_Viva_Las_Vegas'),
  ('Q530973', 'South Park Rally est un jeu vidéo de course sorti en 2000 sur PlayStation, Nintendo 64, Dreamcast et sous Windows. Le jeu a été développé par Tantalus Interactive et édité par Acclaim. Il est basé sur la série télévisée d''animation South Park.', 'https://fr.wikipedia.org/wiki/South_Park_Rally'),
  ('Q386632', 'Warzone 2100 est un jeu vidéo de stratégie en temps réel développé par Pumpkin Studios et publié par Eidos Interactive le 10 avril 1999. Ce jeu est devenu depuis décembre 2004 un logiciel libre et a continué d''évoluer grâce aux contributions de la nouvelle communauté de développeurs.', 'https://fr.wikipedia.org/wiki/Warzone_2100'),
  ('Q2311536', 'Dark Seed est un jeu vidéo de type point and click de genre « horreur » développé par Cyberdreams sorti en 1992 sur Amiga et PC. Deux mondes existent, un monde normal (la ville de Woodland Hills) et un monde parallèle abritant des extra-terrestres. Ce monde est basé sur les dessins qu''a créé H.R. Giger (connu pour ses artworks repris dans Alien).

Il s''agit d''un des rares jeu de l''époque affichant une haute résolution (640×400) aussi bien sur PC que sur Amiga à la demande de Giger lui-même.

Une suite, Dark Seed II, est sortie en 1995 aux États-Unis.

Le concepteur du jeu Mike Dawson prête ses traits au héros du jeu: Mike Dawson. Sa voix ainsi que son apparence ont été reprises telles quelles.', 'https://fr.wikipedia.org/wiki/Dark_Seed'),
  ('Q1881315', 'MDK (pour Murder, Death Kill ou suivant les versions Max, Doc, Kurt ou encore, d''après le fichier « lisez-moi » fourni avec le jeu Migration De Kiwi) est un jeu de tir à la troisième personne produit par David Perry président de Shiny Entertainment, co-distribué par PIE Playmates Interactive Entertainment et par Interplay Entertainment, sorti en avril 1997 sur PC et en novembre 1998 sur Playstation. En 2001, MDK a été ré-édité par Media Pocket.', 'https://fr.wikipedia.org/wiki/MDK_(jeu_vid%C3%A9o)'),
  ('Q1988471', 'FIFA Football 2005 est un jeu vidéo de football développé et édité par Electronic Arts en 2004.

Le jeu est développé par EA Canada et édité par EA Sports. Il est disponible sur PlayStation, PlayStation 2, Microsoft Windows, Xbox, PlayStation Portable, GameCube, téléphone mobile, Gizmondo, N-Gage et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/FIFA_Football_2005'),
  ('Q1865940', 'International Superstar Soccer 2000, est un jeu vidéo de football sorti en 2000 sur Nintendo 64 et Game Boy Color. Le jeu a été développé et édité par Konami.', 'https://fr.wikipedia.org/wiki/International_Superstar_Soccer_2000'),
  ('Q2297756', 'Micro Maniacs est un jeu vidéo de course développé et édité par Codemasters en 2000 sur PlayStation. Il a ensuite été porté sur Game Boy Color.

Le joueur incarne de minuscules personnages s''affrontant dans une course mouvementée au milieu de décors quotidiens gigantesques.', 'https://fr.wikipedia.org/wiki/Micro_Maniacs'),
  ('Q2294466', 'Blood Omen: Legacy of Kain est un jeu vidéo d''action-aventure développé par Silicon Knights et édité par Crystal Dynamics en 1996 sur PlayStation et Windows. C''est le premier épisode de la série Legacy of Kain.

Le joueur incarne Kain, un noble qui se fait assassiner et renaît sous forme de vampire. Kain part à la recherche de ses meurtriers pour se venger. Le jeu a été reconnu pour son atmosphère oppressante et son scénario.', 'https://fr.wikipedia.org/wiki/Blood_Omen:_Legacy_of_Kain'),
  ('Q1845090', 'ECW Hardcore Revolution est un jeu vidéo de catch professionnel, édité et distribué par la société Acclaim Entertainment. Officiellement annoncé en 1999, il s''agit du tout premier jeu vidéo inspiré de l''univers de la fédération de catch américaine Extreme Championship Wrestling (ECW), et le premier jeu vidéo de catch à être classé « M » par l''organisation Entertainment Software Rating Board. Après l''acquisition de la licence, le jeu est développé dans son intégralité aux studios Acclaim de Salt Lake City. Entretemps, une campagne publicitaire est menée par Acclaim Entertainment et la ECW.

Le jeu est initialement commercialisé le 31 janvier 2000 sur consoles Nintendo 64 et PlayStation en Amérique du Nord, et entre février et mars 2000 en Europe. Il est ensuite adapté sur supports Game Boy Color et Dreamcast, et commercialisé à l''international entre février et mars 2000. Il est suivi plus tard d''un second et dernier jeu de la série ECW intitulé ECW Anarchy Rulz, en août 2000. Il propose au joueur une cinquantaine de personnages - une dizaine seulement dans la version Game Boy Color - à l''effigie des lutteurs, ainsi qu''une variété d''options, de matchs, d''arènes personnalisables, et la possibilité de créer un personnage.', 'https://fr.wikipedia.org/wiki/ECW_Hardcore_Revolution'),
  ('Q1987129', 'The Simpsons Wrestling est un jeu vidéo de catch basé sur l''univers de la série Les Simpson, sorti sur PlayStation. Il est développé par Big Ape Productions et édité par Fox Interactive et Activision. Sa sortie a lieu le 22 mars 2001 en zone PAL — dont l''Europe fait partie — et le 12 avril 2001 en Amérique du Nord.

Dix-huit personnages sont présents dans le jeu, chacun étant doublé par les mêmes acteurs que ceux de la série d''animation. Chaque personnage dispose de ses propres mouvements qu''il peut exécuter sur le ring. Les matchs se tiennent dans différents endroits de la ville de Springfield modélisés en 3D; ils se terminent lorsque l''un des personnages maintient au sol les épaules de son adversaire pendant un compte de trois par l''arbitre.', 'https://fr.wikipedia.org/wiki/The_Simpsons_Wrestling'),
  ('Q1987167', 'KKnD2: Krossfire est un jeu vidéo de stratégie en temps réel post-apocalyptique développé par Beam Software et publié sur PC le 31 octobre 1998. Il fait suite à KKnD, publié en 1997, dans lequel deux factions luttent pour le contrôle des ressources dans un monde post-apocalyptique. Après leur défaite contre les mutants, les survivants humains font face à une nouvelle menace, des robots agricoles reconvertis en machine de guerre. En dehors de l’ajout d’une nouvelle faction, son système de jeu est dans la lignée de celui de son prédécesseur et se focalise sur les combats plutôt que sur la gestion des ressources ou l’utilisation des capacités spéciales des unités. Sa principale originalité réside dans la possibilité de personnaliser certaines unités en leur ajoutant des modules pour modifier leurs caractéristiques. À sa sortie, il fait l’objet de critiques mitigées dans la presse spécialisée qui lui reproche notamment son manque d’originalité et les lacunes de son interface graphique et de son intelligence artificielle, et qui le juge dépassé face à StarCraft ou à Total Annihilation.', 'https://fr.wikipedia.org/wiki/KKND2:_Krossfire'),
  ('Q368286', 'Civilization est un jeu vidéo de stratégie au tour par tour de type 4X conçu par Sid Meier et édité par Microprose. Civilization est le premier jeu de la série homonyme, Civilization, où le joueur incarne le dirigeant d''une civilisation qu''il doit mener de l''âge de pierre à la conquête spatiale.

La première version, baptisée Sid Meier''s Civilization, a été publiée en 1991, pour DOS; elle a ensuite été portée sur Amiga 500 et Atari ST en 1992, et Amiga 1200 et Super Nintendo en 1994; des versions pour les systèmes Mac OS et Microsoft Windows ont aussi vu le jour.

En 1995, une version multijoueur a été éditée sous le nom CivNet (nom complet: Sid Meier''s CivNet); cette refonte permet de jouer via un réseau local (LAN), par modem, par câble reliant les ordinateurs, ou en hotseat; le jeu fonctionne sous Windows 3.1 et Windows 95, et le son et les graphismes ont été améliorés; le système de jeu est en grande partie identique à celui de Civilization.', 'https://fr.wikipedia.org/wiki/Civilization_(jeu_vid%C3%A9o)'),
  ('Q1873945', 'War Gods est un jeu vidéo de combat sorti en 1995 sur arcade puis en 1997 sur Nintendo 64, PlayStation et PC. Le jeu est développé et édité par Midway Manufacturing Company.', 'https://fr.wikipedia.org/wiki/War_Gods'),
  ('Q816451', 'Tomb Raider II (ou Tomb Raider II: Starring Lara Croft en version longue) est un jeu vidéo d''action-aventure sorti en 1997, développé par Core Design et édité par Eidos Interactive (futur Square Enix Europe). Il paraît d’abord sur Windows et PlayStation, puis sur Mac OS en 1998, sur iOS en 2014 et sur Android en 2015. Deuxième opus de la série Tomb Raider, il suit l’archéologue et aventurière Lara Croft à la recherche de la dague de Xian, qu’elle convoite face à une secte italienne. Le système de jeu repose sur l’exploration de niveaux composés de zones et salles interconnectées, et mêle combats, résolution d''énigmes et conduite de véhicules motorisés.', 'https://fr.wikipedia.org/wiki/Tomb_Raider_II'),
  ('Q1988611', 'Pro Evolution Soccer 2 (Winning Eleven 6, abrégé PES 2) est un jeu vidéo de football, sorti en 2002 sur PlayStation et PlayStation 2.

Développé et édité par Konami, ce jeu fait partie de la série des Pro Evolution Soccer adaptée de Winning Eleven 6 (version japonaise du jeu) et de World Soccer Winning Eleven 6 (version américaine).', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_2'),
  ('Q1989010', 'Langrisser IV est un jeu vidéo de rôle tactique, développé par NCS Masaya et publié par NCS Corporation sur Saturn le 1er août 1997 exclusivement au Japon. Le jeu a été ensuite adapté sur PlayStation en 1999. Il fait partie de la série Langrisser.', 'https://fr.wikipedia.org/wiki/Langrisser_IV'),
  ('Q1989017', 'Langrisser V: The End of Legend est un jeu vidéo de rôle tactique, développé par NCS Masaya et publié par NCS Corporation sur Saturn le 18 juin 1998 exclusivement au Japon. Le jeu a été ensuite adapté sur PlayStation en 1999. Il fait partie de la série Langrisser.', 'https://fr.wikipedia.org/wiki/Langrisser_V:_The_End_of_Legend'),
  ('Q1870692', 'Tempest 2000 est un jeu vidéo de Shoot ''em up sorti en 1994 sur Jaguar puis converti en 1996 sur Mac OS, DOS et Saturn. Il s''agit de la suite de Tempest, un jeu sorti en 1981 sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/Tempest_2000'),
  ('Q2298157', 'Harvest Moon: Back to Nature est un jeu vidéo de type simulation de vie / RPG sorti en 1999 sur PlayStation, PlayStation Portable en 2005 et sur PlayStation Network en 2008.', 'https://fr.wikipedia.org/wiki/Harvest_Moon:_Back_to_Nature'),
  ('Q1837699', 'Mega Man 4 (Rockman 4: Aratanaru Yabō!! au Japon) est un jeu d''action-plates-formes développé et édité par Capcom sur NES en 1991, puis porté sur Console virtuelle (Wii, Wii U, Nintendo 3DS), et téléphone mobile (J2ME, iOS). C''est le quatrième jeu de la série principale de Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_4'),
  ('Q1987436', 'Rosco McQueen, sous-titré Firefighter Extreme aux États-Unis, est un jeu vidéo d''action développé par Slippery Snake et édité par Sony Computer Entertainment en 1997 sur PlayStation.

Le joueur incarne un soldat du feu confronté à Sylvester T. Square et sa légion de robots pyromanes.', 'https://fr.wikipedia.org/wiki/Rosco_McQueen'),
  ('Q1891590', 'Ultima Underworld: The Stygian Abyss est un jeu vidéo de type dungeon crawler en vue subjective développé par Blue Sky Productions et publié par Origin Systems en mars 1992. Il se déroule dans le monde médiéval-fantastique de la série Ultima, à l''intérieur du Great Stygian Abyss, une immense caverne souterraine qui abrite les restes d''une ancienne civilisation utopiste. Le joueur incarne l''Avatar — le principal protagoniste de la série — et tente de sauver la fille d''un baron qui a été enlevée. Ultima Underworld est souvent considéré comme le premier jeu vidéo de rôle en vue subjective se déroulant dans un environnement en trois dimensions et il a introduit un certain nombre d''innovations techniques, dont la possibilité de regarder vers le haut et vers le bas. Son système de jeu, qui s''inspire de Wizardry et de Dungeon Master, mélange des éléments de simulation et de jeu de rôle, ce qui lui vaut d''être désigné comme une « simulation de donjon » par ses concepteurs. Le jeu propose ainsi un gameplay émergent dans lequel le joueur progresse de manière non-linéaire.', 'https://fr.wikipedia.org/wiki/Ultima_Underworld'),
  ('Q2294865', 'Dragon Quest VII: La Quête des vestiges du monde est un jeu vidéo de rôle développé par Heartbeat et ArtePiazza pour l''éditeur japonais Enix. Il est sorti sur PlayStation en août 2000 au Japon puis en novembre 2001 en Amérique du Nord.

Un remake sur Nintendo 3DS est sorti le 7 février 2013 au Japon et le 16 septembre 2016 en Amérique du Nord et en Europe. Un deuxième remake intitulé Dragon Quest VII Reimagined est sorti le 5 février 2026 sur Nintendo Switch, Nintendo Switch 2, PlayStation 5, Xbox Series et Microsoft Windows.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_VII_:_La_Qu%C3%AAte_des_vestiges_du_monde'),
  ('Q2293778', 'Driver (ou Driver: You Are the Wheelman en Amérique du Nord) est un jeu vidéo développé par Reflections, sorti le 30 juin 1999 sur PlayStation. Il a été adapté sur Mac OS, Windows et Game Boy Color. C''est un jeu vidéo de course-poursuite dont l''histoire se passe pendant les années 1970.

Le jeu connaît un important succès et marque les débuts de la série Driver, écoulée à plus de 14 millions d''exemplaires en 2006.

Son successeur nommé "Driver 2" suit le même style de jeu que son prédécesseur.', 'https://fr.wikipedia.org/wiki/Driver_(jeu_vid%C3%A9o)'),
  ('Q1860494', 'Jet Rider (Jet Moto en Amérique du Nord) est un jeu vidéo de course développé par SingleTrac et édité par Sony Computer Entertainment, sorti en 1996 sur PlayStation et Windows.

Il est réédité en 2007 sur PlayStation 3 et PlayStation Portable via le PlayStation Network.

Il a pour suite Jet Rider 2 et Jet Moto 3.', 'https://fr.wikipedia.org/wiki/Jet_Rider'),
  ('Q1123794', 'Tomb Raider III: Les Aventures de Lara Croft (Tomb Raider III: Adventures of Lara Croft en version originale) est un jeu vidéo d''action-aventure sorti en novembre 1998. Il est le troisième volet de la série Tomb Raider.

Le jeu reprend en grande partie le gameplay du premier épisode, et du second. De nouveaux mouvements (comme sprinter ou ramper, voire conduire un quad ou un kayak), armes et tenues font leur apparition, et comme à chaque nouvel épisode, des polygones supplémentaires débarquent pour arrondir les textures.

Contrairement aux précédents opus, Tomb Raider 3 est considéré par beaucoup de fans comme l''épisode le plus long et le plus difficile de la saga, notamment en raison de ses niveaux vastes, sombres et labyrinthiques.', 'https://fr.wikipedia.org/wiki/Tomb_Raider_III_:_Les_Aventures_de_Lara_Croft'),
  ('Q1130193', 'South Park: Chef''s Luv Shack est un jeu vidéo de type party game développé par Acclaim Studios Austin et édité par Acclaim, sorti en 1999 sur Dreamcast, Nintendo 64, PlayStation et Windows.

Adapté de la série d''animation américaine South Park, le jeu prend la forme d''un jeu télévisé parodique animé par Chef. Il mélange des questions-réponses inspirées de l''univers de la série et de la culture populaire américaine avec des mini-jeux opposant les personnages principaux.', 'https://fr.wikipedia.org/wiki/South_Park:_Chef%27s_Luv_Shack'),
  ('Q2006613', 'Time Crisis est un jeu vidéo de tir au pistolet (type rail shooter) développé et édité par Namco en 1996 sur borne d''arcade et adapté en 1997 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Time_Crisis_(jeu_vid%C3%A9o)'),
  ('Q1128672', 'Lego Racers est un jeu vidéo de course sorti en 1999 sur Windows, Nintendo 64, PlayStation et Game Boy Color. Le jeu a été développé par High Voltage Software et édité par Lego Media.

Le jeu se déroule dans l''univers des jouets Lego.

Le joueur incarne un nouveau pilote qu''il peut personnaliser grâce à un éditeur de personnage et de voiture. Une fois le pilote créé, le joueur peut se lancer dans un championnat, une course libre, un duel (mode deux joueurs) ou dans les contre la montre. S''il choisit le mode championnat, il devra alors enchaîner les quatre circuits du monde.

L''ultime pilote est Rocket Racer, champion incontesté de l''univers Lego. Une suite à Lego Racers a par ailleurs vu le jour en 2001. On y retrouve Rocket Racer.', 'https://fr.wikipedia.org/wiki/Lego_Racers'),
  ('Q2001340', 'One Piece: Grand Battle! est un jeu vidéo de combat développé par Ganbarion et édité par Bandai le 15 mars 2001 sur PlayStation.', 'https://fr.wikipedia.org/wiki/One_Piece:_Grand_Battle!'),
  ('Q2000432', 'Dynasty Warriors est un jeu vidéo de combat développé par Omega Force et édité par Koei, sorti en 1997 sur PlayStation.

Contrairement à ses nombreuses suites, le jeu met en scène des combats en un contre un et n''adopte pas un gameplay de beat them all.', 'https://fr.wikipedia.org/wiki/Dynasty_Warriors_(jeu_vid%C3%A9o,_1997)'),
  ('Q245006', 'Final Fantasy VIII est un jeu vidéo de rôle développé par Square (devenu depuis Square Enix) sous la direction de Yoshinori Kitase et constituant le huitième opus de la série Final Fantasy. Le jeu sort sur PlayStation en 1999 et sur Windows en 2000. Il est également disponible sur le PlayStation Network depuis le 4 février 2010 et par l''entremise de la plate-forme Steam depuis le 5 décembre 2013.

Comme son prédécesseur, Final Fantasy VIII s''éloigne des mondes fantastiques traditionnels pour présenter un univers inspiré du monde contemporain. L''histoire met en scène un groupe de jeunes mercenaires, entraînés dans un conflit international, qui cherchent à sauver le monde d''une sorcière manipulant la guerre pour arriver à ses fins. En parallèle, le scénario développe une relation amoureuse entre les deux personnages principaux (représentés sur le logo).', 'https://fr.wikipedia.org/wiki/Final_Fantasy_VIII'),
  ('Q1136894', 'Real Bout Fatal Fury est un jeu vidéo de combat en 2D développé et édité par SNK en 1996 sur Neo-Geo MVS, en 1997 sur Neo-Geo AES et Neo-Geo CD (NGM 095). Le jeu est porté sur les années suivantes sur Sega Saturn, PlayStation et plus tard sur PlayStation 2. C''est le cinquième épisode de la série Fatal Fury.', 'https://fr.wikipedia.org/wiki/Real_Bout_Fatal_Fury'),
  ('Q267475', 'ISS Pro Evolution (World Soccer: Jikkyou Winning Eleven 4 au Japon) est un jeu vidéo de football développé par KCET et édité par Konami en 1999 sur PlayStation.', 'https://fr.wikipedia.org/wiki/ISS_Pro_Evolution'),
  ('Q1139007', 'Need for Speed III: Poursuite infernale (titre original en anglais: Need for Speed III: Hot Pursuit) est un jeu vidéo de course sorti en 1998, produit par EA Canada et édité par Electronic Arts. Il s''agit du troisième titre de la série des Need for Speed.', 'https://fr.wikipedia.org/wiki/Need_for_Speed_III_:_Poursuite_infernale'),
  ('Q259804', 'Ghost in the Shell est un jeu vidéo d''action sorti en 1997 sur PlayStation. Le jeu a été développé par Exact puis édité par Sony, il se déroule dans l''univers du manga Ghost in the Shell de Masamune Shirow.', 'https://fr.wikipedia.org/wiki/Ghost_in_the_Shell_(jeu_vid%C3%A9o)'),
  ('Q278771', 'Worms (de l''anglais worm: ver) est un jeu vidéo d''artillerie développé par Team17. Il est édité par Ocean Software en 1995 sur Amiga et PC. Premier épisode à succès d''une longue série, le jeu fut porté sur de nombreux supports.

Joué au tour par tour, en 2 dimensions, il oppose deux équipes de vers de terre armés jusqu''aux dents, selon le principe du jeu d''artillerie. Le concept de jeu a été inventé par Andy Davison.', 'https://fr.wikipedia.org/wiki/Worms_(jeu_vid%C3%A9o)'),
  ('Q1138507', 'Street Fighter EX est un jeu vidéo de combat en un contre un de la franchise Street Fighter, développé par Arika et édité par Capcom en novembre 1996 sur système d''arcade ZN-1. Il est le tout premier jeu Street Fighter en 3D polygonale, là où tous les jeux précédents de la franchise furent en 2D par sprites dessinés et pixellisés (à l''exception de Street Fighter: The Movie, qui lui avait des sprites numérisés obtenus par capture de mouvement).', 'https://fr.wikipedia.org/wiki/Street_Fighter_EX'),
  ('Q1137268', 'Real Bout Fatal Fury Special est un jeu vidéo de combat en 2D développé et édité par SNK en 1997 sur Neo-Geo MVS, Neo-Geo AES, Neo-Geo CD (NGM 233). Le jeu est porté sur Sega Saturn, PlayStation, PlayStation 2, Game Boy et PC (Windows). C''est le sixième épisode de la série Fatal Fury.', 'https://fr.wikipedia.org/wiki/Real_Bout_Fatal_Fury_Special'),
  ('Q1137028', 'Fatal Fury: Wild Ambition est un jeu vidéo de combat en 3D développé et édité par SNK sur Hyper Neo-Geo 64 et PlayStation en 1998. C''est le huitième épisode de la série Fatal Fury.', 'https://fr.wikipedia.org/wiki/Fatal_Fury:_Wild_Ambition'),
  ('Q2034580', 'Side Pocket est un jeu vidéo de billard développé par Data East en 1986 sur borne d''arcade. Le jeu a été adapté sur divers consoles de jeu.', 'https://fr.wikipedia.org/wiki/Side_Pocket'),
  ('Q2037482', 'Rage Racer est un jeu vidéo de course développé et édité par Namco, sorti au Japon le 3 décembre 1996, en Amérique du Nord en 1997 et en Europe en juin 1997 sur PlayStation. C''est le troisième jeu de la série Ridge Racer. Rage Racer est le premier jeu de la série à posséder une introduction en images de synthèse; c''est dans celle-ci qu''apparaît pour la première fois Reiko Nagase, la représentante de la série.', 'https://fr.wikipedia.org/wiki/Rage_Racer'),
  ('Q2020857', 'Pro Evolution Soccer,(eFootball) abrégé sous le sigle PES mais aussi intitulé World Soccer: Winning Eleven 5 dans la version originale japonaise et la version américaine, est un jeu vidéo de simulation de football développé et édité par la branche tokyoïte de Konami, sorti en 2001 sur PlayStation 2, puis adapté sur PlayStation en 2002.

En Europe, il appartient à la franchise Pro Evolution Soccer dont il est le 1er épisode bien qu''il fasse suite à ISS Pro Evolution 2. Tandis qu''au Japon, il est le 5e épisode de la série Winning Eleven.

Cet opus permet au joueur d''incarner 54 équipes nationales et 32 des meilleurs clubs de football au monde.', 'https://fr.wikipedia.org/wiki/Pro_Evolution_Soccer_(jeu_vid%C3%A9o)'),
  ('Q2028799', 'F-1 World Grand Prix est un jeu vidéo de Formule 1 sorti en 1998 sur Nintendo 64, Dreamcast et Game Boy. Le jeu a été développé par Paradigm Entertainment et Video System puis édité par Nintendo et Video System.

Une version PC, adaptée sur PlayStation, développée par Lankhor et éditée par Eidos Interactive en 2000. Cette version n''a rien en commun avec le jeu de Paradigm Entertainment si ce n''est la licence officielle F1 détenue par Video System. Elle est en fait la suite d''Official Formula One Racing adoptant ce nouveau nom pour la cohérence de la marque.

Le jeu a eu une suite, F-1 World Grand Prix II.', 'https://fr.wikipedia.org/wiki/F-1_World_Grand_Prix'),
  ('Q428548', 'NBA Live 97 est un jeu vidéo de basket-ball sorti en 1996 et fonctionne sur PlayStation, Super Nintendo, Mega Drive et PC. Le jeu a été développé par EA Sports, puis édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/NBA_Live_97'),
  ('Q548077', 'Toshinden Subaru est un jeu de combat sur PlayStation. C''est le 4e opus de la série Battle Arena Toshinden.', 'https://fr.wikipedia.org/wiki/Toshinden_Subaru'),
  ('Q427337', 'FIFA 97 (parfois FIFA Soccer 97) est un jeu vidéo de football sorti en 1996 qui fonctionnait sur PlayStation, Windows, Game Boy, Mega Drive, Saturn et Super Nintendo. Le jeu a été développé par XYZ Productions et édité par EA Sports.', 'https://fr.wikipedia.org/wiki/FIFA_97'),
  ('Q474573', 'Final Fantasy IX est un jeu vidéo de rôle développé par Square Co. sous la direction de Hiroyuki Itō constituant le neuvième opus de la série Final Fantasy. Il est publié en juillet 2000 au Japon, en novembre en Amérique du Nord puis en février 2001 en Europe et Australie. Après les épisodes VII et VIII, il s''agit du troisième et dernier jeu de la série à être distribué sur la PlayStation de Sony.

Le jeu met en scène les aventures de jeunes adolescents qui tentent d''arrêter une reine tyrannique et belliqueuse, puis un homme mystérieux qui, tourmenté par ses origines, est pris de folie et tente de détruire le monde. Sous une apparence de simplicité des personnages, le scénariste et producteur Hironobu Sakaguchi essaie de proposer une chronologie complexe, une réflexion sur la mort et le but de la vie, notamment avec le personnage de Bibi, qui fait office de narrateur lors de certaines séquences.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_IX'),
  ('Q544667', 'Heart of Darkness est un jeu vidéo d''action et de plate-forme sorti en 1998 sur PlayStation et Windows.

Développé par une équipe d''un peu plus de douze personnes sous la direction de Éric Chahi, il a demandé six ans de travail et a été l''unique jeu de l''entreprise Amazing Studio. Il était initialement prévu qu''il sorte sur CD32, 3DO, Jaguar et Saturn, mais ces versions ont été annulées, en raison de la non viabilité commerciale de ces plateformes lorsque le jeu fut finalement terminé.

Présenté lors du CES 1994 et de l''E3 1995, lors de sa sortie il s''est fait remarquer par sa jouabilité irréprochable et son ambiance sonore digne d''un film. Il sera ré-édité chez Infogrames en format « best-of », format qui concerne les productions ayant fait de bonnes ventes.', 'https://fr.wikipedia.org/wiki/Heart_of_Darkness_(jeu_vid%C3%A9o)'),
  ('Q544818', 'Les Chevaliers de Baphomet: Les Boucliers de Quetzalcoatl (version originale: Broken Sword II: The Smoking Mirror) est un jeu vidéo d''aventure développé par Revolution Software, sorti sur PC et PlayStation en 1997. Le jeu a été édité par Virgin Interactive pour la version PC et par Sony Computer Entertainment pour la version PlayStation. Une version remasterisée du jeu est sortie en décembre 2010 sur iPhone, iPod Touch et iPad et en décembre 2012 sur Android.

Il s''agit du second épisode de la série Les Chevaliers de Baphomet, sorti un an après le premier volet.', 'https://fr.wikipedia.org/wiki/Les_Chevaliers_de_Baphomet_:_Les_Boucliers_de_Quetzalcoatl'),
  ('Q2080005', 'FIFA Football 2003 est un jeu vidéo de football sorti en 2002 pour les plateformes PlayStation, PlayStation 2, Windows, GameCube et Game Boy Advance. Le jeu a été édité par EA Sports. C''est le onzième volet de la série FIFA Football. Il a pour tête d''affiche le néerlandais Edgar Davids, le brésilien Roberto Carlos et le gallois Ryan Giggs. Dans la version sortie en Amérique du Nord, renommé Fifa Soccer 2003, c''est l''américain Landon Donovan qui est présent sur la jaquette.

On dit de Fifa 2003 qu''il fut le dernier jeu de la « seconde » génération de Fifa, qui laissera place ensuite à Fifa 2004 offrant aux joueurs un jeu différent.', 'https://fr.wikipedia.org/wiki/FIFA_Football_2003'),
  ('Q2081133', 'Street Fighter Alpha: Warriors'' Dreams, connu sous le titre de Street Fighter Zero au Japon, est un jeu vidéo de combat en un contre un développé et édité par Capcom en juin 1995 sur CP System II. Le titre est porté sur PlayStation et Sega Saturn l''année suivante, et sort en Europe le 22 mai 1996, édité par Virgin Interactive.

Cet épisode est un renouveau dans la franchise Street Fighter: pour la première fois depuis Street Fighter II: The World Warrior (sorti en 1991) et malgré les multiples versions du second opus sorties, parait un titre Street Fighter complètement nouveau, et aux graphismes entièrement refaits. Ainsi, les personnages revenant des deux premiers opus comme Ryu, Ken, Chun-Li, Sagat et Bison voient leurs corps et tenues redessinés; et le jeu accueille des nouveautés de gameplay comme l''apparition des furies (combos) à trois niveaux de puissance, de tout nouveaux personnages comme Rose et le retour d''anciens protagonistes du premier Street Fighter pourtant absents du second, parmi lesquels Adon et Birdie.', 'https://fr.wikipedia.org/wiki/Street_Fighter_Alpha:_Warriors%27_Dreams'),
  ('Q429246', 'The Need for Speed (titre anglais, littéralement « Le besoin de vitesse ») est un jeu vidéo de course développé par EA Canada et édité par Electronic Arts en 1994. Il est le premier épisode de la série Need for Speed. De plus, une version nommée Over Drivin'' Skyline Memorial a été vendu en 1997 au Japon sur PlayStation et une Special Edition a été vendue en 1996 pour PC avec du contenu additionnel.

Electronic Arts a travaillé conjointement avec la célèbre revue d''automobile américaine « Road & Track » pour rendre le comportement des véhicules et les bruits de moteurs plus réalistes.', 'https://fr.wikipedia.org/wiki/The_Need_for_Speed'),
  ('Q2090123', 'Front Mission 2 est un jeu vidéo de type tactical RPG développé par G-Craft et édité par Squaresoft, sorti en 1997 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Front_Mission_2'),
  ('Q2104578', 'Porsche Challenge est un jeu vidéo de course automobile développé par Team Soho et édité par Sony Computer Entertainment, sorti en 1997 sur PlayStation. Le jeu met en scène le cabriolet Porsche Boxster.', 'https://fr.wikipedia.org/wiki/Porsche_Challenge'),
  ('Q427198', 'Pandemonium! (ou Magical Hoppers au Japon) est un jeu de plates-formes de Crystal Dynamics sorti en 1996 sur PlayStation, puis en 1997 sur Saturn. Il existe aussi une version PC.', 'https://fr.wikipedia.org/wiki/Pandemonium_(jeu_vid%C3%A9o)'),
  ('Q553054', 'Gimmick! ou Mr. Gimmick, est un jeu vidéo de plates-formes développé et édité par Sunsoft, sorti en 1992 sur NES et en 2002 sur PlayStation dans la compilation « Memorial Series Sunsoft Vol. 6 ».

Le jeu est sorti aussi en Europe en 1993 dans les pays Scandinaves en petites quantités.', 'https://fr.wikipedia.org/wiki/Gimmick!'),
  ('Q2092504', 'Valkyrie Profile est un jeu vidéo sorti sur PlayStation en 1999. Ce jeu de rôle a été développé par tri-Ace et édité par Enix au Japon et SCEA aux États-Unis. Il se situe dans l''univers des légendes scandinaves et germaniques. Le personnage principal est une déesse, Lenneth Valkyrie, qui doit former une troupe de puissants guerriers avant que ne survienne le Ragnarök.

L''éditeur, devenu Square Enix, a sorti en septembre 2007 une suite sur PlayStation 2 (en 2006 au Japon), Valkyrie Profile: Silmeria, et a réédité en avril 2007 (février 2006 pour le Japon) le premier épisode sur PlayStation Portable, sous le nom de Valkyrie Profile: Lenneth.', 'https://fr.wikipedia.org/wiki/Valkyrie_Profile'),
  ('Q2337936', 'Alone in the Dark: The New Nightmare est un jeu vidéo de type survival horror, développé par Darkworks et édité par Infogrames, sorti en Europe en 2001 sur PlayStation, Dreamcast, PlayStation 2, Windows et Game Boy Color.

Puis sur PlayStation 4 et PlayStation 5, via le PlayStation Store, le 16 avril 2024.

C''est le quatrième jeu de la série Alone in the Dark.', 'https://fr.wikipedia.org/wiki/Alone_in_the_Dark:_The_New_Nightmare'),
  ('Q2333654', 'Warm Up! est un jeu vidéo de course de Formule 1 développé par Lankhor et édité par Microïds sur PlayStation et Windows en 2000.', 'https://fr.wikipedia.org/wiki/Warm_Up!'),
  ('Q2333604', 'V-Rally 2 est un jeu vidéo de course de rallye sorti en 1999, développé par Eden Studios et édité par Infogrames. Ce titre qui fait partie de la série des V-Rally se nomme V-Rally 2: Championship Edition.

La version PlayStation américaine s''intitule Need For Speed: V-Rally 2 et la version Dreamcast américaine porte le nom Test Drive: V-Rally 2, bien qu''elles n''aient pas de rapport avec Need for Speed ou Test Drive.', 'https://fr.wikipedia.org/wiki/V-Rally_2'),
  ('Q2326799', 'Test Drive 6 est un jeu vidéo de course urbaine développé par Pitbull Syndicate, sorti à partir de décembre 1999 sur quatre plateformes: PC, PlayStation, Dreamcast et Game Boy Color. Il est le sixième de la série Test Drive, dont la première production est sortie en 1987.', 'https://fr.wikipedia.org/wiki/Test_Drive_6'),
  ('Q388225', 'Command and Conquer: Alerte rouge (Command and Conquer: Red Alert en version originale) est un jeu vidéo de stratégie en temps réel développé par Westwood Studios et publié par Virgin Interactive sur PC et Macintosh le 31 octobre 1996 en Amérique du Nord et le 18 novembre en Europe. Il se déroule chronologiquement avant Command and Conquer: Conflit du Tibérium (1995) dont il reprend le système de jeu et une partie de l''univers et marque le départ d''une nouvelle série dont le scénario est fondé sur une réalité alternative. Bien accueilli par les critiques, le jeu connait un important succès commercial avec 1,5 million de copies vendues en moins d''un mois.', 'https://fr.wikipedia.org/wiki/Command_and_Conquer_:_Alerte_rouge'),
  ('Q1180940', 'Deadly Premonition, titré Red Seeds Profile au Japon, est un jeu vidéo d''horreur psychologique en monde ouvert sorti sur Xbox 360 et PlayStation 3. Le jeu est développé par Access Games et publié par Ignition Entertainment en Amérique du Nord, Marvelous Entertainment au Japon et Rising Star Games en Europe.

Une version Nintendo Switch intitulée Deadly Premonition Origins est sortie en 2019. Sa suite, Deadly Premonition 2: A Blessing in Disguise développée par la même équipe dont Hidetaka « Swery » Suehiro, est sortie en 2020.', 'https://fr.wikipedia.org/wiki/Deadly_Premonition'),
  ('Q2059628', 'Street Racer est un jeu vidéo de course, similaire à Super Mario Kart, développé par le studio anglais Vivid Image et édité par Ubisoft, sorti en 1994 sur Super Nintendo. Le jeu a été adapté sur les consoles Mega Drive, PlayStation, Saturn et Game Boy, et les ordinateurs Amiga et PC.

Il fut l’un d’un premier jeu à utiliser les accessoires pour multiplier le nombre de manettes et fut le premier jeu de course à autoriser 8 joueurs simultanément sur un même écran (dans ce cas, l’écran est splitté).', 'https://fr.wikipedia.org/wiki/Street_Racer_(jeu_vid%C3%A9o)'),
  ('Q1192914', 'R4: Ridge Racer Type 4 est un jeu vidéo de course développé et édité par Namco sorti en 1998 au Japon et en 1999 en Amérique du Nord et en Europe. C''est le quatrième et dernier jeu de la série Ridge Racer sorti sur PlayStation. C''est l''un des premiers jeux à utiliser l''ombrage Gouraud, ce qui donne au jeu une profondeur visuelle. C''est aussi le premier jeu de la série Ridge Racer à intégrer un mode multijoueur à écran partagé sur une machine de Sony.', 'https://fr.wikipedia.org/wiki/R4:_Ridge_Racer_Type_4'),
  ('Q906679', 'Puyo Puyo 2 est un jeu vidéo de puzzle développé et édité par Compile, sorti en 1994 sur borne d''arcade, Mega Drive et Game Gear. Il a été adapté sur divers supports ensuite.

Le jeu fait suite à Puyo Puyo.', 'https://fr.wikipedia.org/wiki/Puyo_Puyo_2'),
  ('Q2347711', 'Tear Ring Saga: Chronicles of War Hero Yutona; ou plus communément Tear Ring Saga; est un jeu vidéo de genre tactical RPG au tour par tour développé par Tirnanog et édité par Enterbrain sorti le 24 mai 2001 sur PlayStation, au Japon exclusivement.

Le titre est principalement connu pour être le premier jeu conçu et scénarisé par Shouzou Kaga, le créateur de la série de jeux de rôle tactiques Fire Emblem, après son départ d’Intelligent Systems en 1999. De fait, Tear Ring Saga présente des similitudes frappantes avec les cinq premiers opus de la série de Nintendo, sur le plan esthétique, narratif, et bien sûr du gameplay.', 'https://fr.wikipedia.org/wiki/Tear_Ring_Saga'),
  ('Q2337997', 'Alone in the Dark 2 est un jeu vidéo de type survival horror développé par Infogrames, publié en Europe en 1993, soit un an après Alone in the Dark, dont il constitue la suite.

En 1995, ce jeu est porté sur 3DO et garde alors le même nom (la version 3DO est la seule version console à proposer une traduction et un doublage en français). En 1996, le jeu est porté sur Sega Saturn et sur PlayStation sous le nom Alone in the Dark: Jack is Back en Europe, et Alone in the Dark: One-Eyed Jack''s Revenge en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Alone_in_the_Dark_2'),
  ('Q868523', 'Command and Conquer, aujourd’hui aussi connu sous le nom de Conflit du Tibérium, est un jeu de stratégie en temps réel développé par Westwood Studios. Les versions MS-DOS et MAC sont publiées par Virgin Interactive en 1995. Une version Windows 95 est ensuite publiée en 1997, le jeu étant également porté sur les consoles PlayStation, Sega Saturn et Nintendo 64.

Dès sa sortie, il connaît un important succès critique et commercial, initiant ainsi le succès de la franchise Command and Conquer qui devient à la fin des années 1990 la principale rivale des séries Warcraft et StarCraft développé par Blizzard Entertainment.', 'https://fr.wikipedia.org/wiki/Command_and_Conquer_:_Conflit_du_Tib%C3%A9rium'),
  ('Q2060111', 'Angelique est un jeu vidéo otome de simulation de drague, sorti en 1994, qui est le premier jeu publié de ce type au monde. Il est suivi de versions améliorées sous-titrées Special, Voice Fantasy, Duet et Retour. C''est aussi le premier jeu de la série Angelique.', 'https://fr.wikipedia.org/wiki/Angelique_(jeu_vid%C3%A9o)'),
  ('Q2345478', 'Genghis Khan II: Clan of the Gray Wolf est un jeu vidéo de stratégie développé et édité par Koei en 1992 sur PC-98. Il a été adapté en 1993 sur DOS, Mega-CD, Mega Drive, NES, PC Engine et Super Nintendo. Il prend pour cadre les conquêtes mongoles du XIIe siècle; le joueur peut entre autres incarner l''empereur Gengis Khan.

Il s''agit de la suite de Genghis Khan.', 'https://fr.wikipedia.org/wiki/Genghis_Khan_II:_Clan_of_the_Gray_Wolf'),
  ('Q1192318', 'Rampage est un jeu vidéo développé et édité par Bally Midway en 1986 sur borne d''arcade. Jouable à trois en simultané, il propose d''incarner des monstres gigantesques tentant de survivre dans une ville contre l''armée.', 'https://fr.wikipedia.org/wiki/Rampage_(jeu_vid%C3%A9o)'),
  ('Q1191816', 'WWE ''12 est un jeu vidéo de catch développé par Yuke''s et publié par THQ sur PlayStation 3, Wii et Xbox 360. WWE ''12 est la quatorzième édition de la série de jeux vidéo WWE et le premier à paraître uniquement sur consoles septième génération. Précédé par WWE SmackDown vs. Raw 2011 (commercialisé en 2010), le jeu est commercialisé le 22 novembre 2011 en Amérique du Nord, et le 25 novembre 2011 en Europe.', 'https://fr.wikipedia.org/wiki/WWE_%2712'),
  ('Q2066662', 'Le Cinquième Élément est un jeu vidéo d''action-aventure qui est basé sur le film du même nom développé par Kalisto Entertainment et sorti sur PlayStation et Windows.', 'https://fr.wikipedia.org/wiki/Le_Cinqui%C3%A8me_%C3%89l%C3%A9ment_(jeu_vid%C3%A9o)'),
  ('Q2059084', 'Wild Arms 2, connu sous le nom de Wild Arms: 2nd Ignition au Japon, est un jeu vidéo de rôle édité par Sony Computer Entertainment et développé par Media.Vision et Contrail. Il est sorti en 1999 au Japon et en 2000 en Amérique du Nord sur PlayStation. Il devient disponible sur PlayStation Portable et PlayStation 3 en téléchargement via le PlayStation Network en 2007 au Japon et en 2009 en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Wild_Arms_2'),
  ('Q391468', 'Une faim de loup (en anglais: Sheep, Dog ''n'' Wolf) est un jeu vidéo de plates-formes-réflexion et d''infiltration, développé, édité et distribué par Infogrames. Il est initialement commercialisé en Europe sur le système Microsoft Windows le 14 septembre 2001, puis sur la console PlayStation le 21 septembre 2001. En Amérique du Nord, la seule version PlayStation est commercialisée le 8 octobre 2001 sous le titre de Looney Tunes: Sheep Raider.

Le jeu met en avant l''univers déjanté des dessins animés Looney Tunes dans lequel le joueur incarne le personnage de Ralph le loup, candidat à une émission de télévision organisée par Daffy Duck, tentant par diverses ruses de tromper la vigilance de Sam le chien de berger et ainsi lui dérober son troupeau de moutons. Une trentaine d''objets en tout genre des industries ACME, incluant gadgets, déguisements et autres accessoires, sont mis à la disposition du joueur, qui doit également traverser maints décors et environnements truffés de pièges pour apercevoir Sam et son troupeau. Le doublage des personnages est assuré par les mêmes voix que celles présentes dans les courts-métrages.', 'https://fr.wikipedia.org/wiki/Une_faim_de_loup_(jeu_vid%C3%A9o)'),
  ('Q2070837', 'Wargames est un jeu vidéo de stratégie en temps réel développé par Interactive Studios et publié par MGM Interactive sur PC en 1998. Le jeu s’inspire en partie du film Wargames de 1983 et retrace un affrontement entre l’humanité et des machines commandées par un ordinateur devenu fou. Le jeu propose deux campagnes, une par camp, composées chacune de quinze missions. Son système économique est basé sur le piratage. Pour obtenir de l’argent, le joueur doit en effet envoyer des hackers pirater un système informatique afin de détourner des fonds. Ces pirates gèrent de plus l’amélioration des unités et peuvent, grâce à leurs ordinateurs, affaiblir les véhicules ennemis.', 'https://fr.wikipedia.org/wiki/Wargames_(jeu_vid%C3%A9o)'),
  ('Q1171293', '1 001 Pattes (anglais: A Bug''s Life) est un jeu vidéo de plates-formes développé Traveller''s Tales, sorti à partir de 1998 sur Windows, Nintendo 64, PlayStation, Sega Pico et Game Boy Color.

Le jeu est adapté du film d''animation du même nom des studios Pixar. Il existe par ailleurs un logiciel ludo-éducatif appelé 1 001 Pattes: Atelier de jeux sorti en 2002 sur PlayStation.', 'https://fr.wikipedia.org/wiki/1_001_Pattes_(jeu_vid%C3%A9o)'),
  ('Q911226', 'Final Fantasy IV est un jeu vidéo de rôle développé par Square sous la direction de Hironobu Sakaguchi, le créateur de la série. Le jeu est édité par Square sur Super Nintendo en juillet 1991 au Japon puis en novembre en Amérique du Nord dans une version épurée nommée Final Fantasy II. Il s''agit du quatrième épisode de la série Final Fantasy et du premier à être produit sur console 16-bits.

L''histoire met en scène la quête de Cecil, chevalier noir essayant de sauver son roi de l''emprise du maléfique Golbez. Cecil est, entre autres, aidé dans sa quête par sa compagne Rosa et par son meilleur ami, le chevalier dragon Kain (représenté sur le logo). Au fur et à mesure de la progression, le groupe tente d''arrêter Golbez qui tente d''anéantir le monde. Le scénario est aujourd''hui considéré comme un classique du jeu de rôle japonais.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_IV'),
  ('Q1172499', 'G-Police: Weapons of Justice est un jeu vidéo de combat spatial développé et édité par Psygnosis, sorti en 1999 sur PlayStation. Il fait suite à G-Police sorti en 1997.', 'https://fr.wikipedia.org/wiki/G-Police:_Weapons_of_Justice'),
  ('Q900305', 'Final Fantasy V est un jeu vidéo de rôle développé par Squaresoft et sorti sur Super Famicom en 1992. Le jeu s''est vendu à près de 2 500 000 exemplaires.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_V'),
  ('Q864026', 'Coupe du monde 98 (ou World Cup 98 en version originale) est un jeu vidéo de football sorti en 1998 sur PlayStation, Windows, Nintendo 64 et Game Boy. Le jeu est développé par Electronic Arts et édité par EA Sports.

Il s''agit du jeu officiel de la Coupe du monde de football 1998. C''est la première fois qu''EA Sport réalise le jeu officiel d''une Coupe du monde de football. EA Sport obtient la licence exclusive de l''épreuve en 1997 auprès de la FIFA. C''est également le premier jeu vidéo d''une Coupe du monde à utiliser un moteur 3D. Dans la version française, les matches sont commentés par Jean-Luc Reichmann, David Ginola et Thierry Gilardi.', 'https://fr.wikipedia.org/wiki/Coupe_du_monde_98_(jeu_vid%C3%A9o)'),
  ('Q2067226', 'Warhammer: Dark Omen est un jeu vidéo de tactique en temps réel développé par Mindscape et publié par Electronic Arts le 31 mars 1998. Dans ce wargame, ayant pour thème l''univers médiéval-fantastique de Warhammer, le joueur est à la tête d''une armée de mercenaires dénommés les Portes-Rancunes dirigée par le capitaine Morgan Bernhart. Le joueur doit affronter des créatures telles que les orques, les gobelins, des squelettes et un roi des temps anciens: le roi de la terreur. Des mages et des pièces d''artilleries (tank à vapeur impérial, canons et mortiers) sont disponibles durant les batailles. La version PC est multijoueurs, ce qui permet aux joueurs de ne pas avoir l''exclusivité de la faction des portes-rancunes.', 'https://fr.wikipedia.org/wiki/Warhammer:_Dark_Omen'),
  ('Q2351501', 'Evil Zone ou Eretzvaju est un jeu de combat sorti sur PlayStation. Il a été développé par YUKE''s Future Media Creators et édité par Titus Software en 1999. Le joueur peut choisir parmi dix personnages pour combattre dans divers modes de jeux dont: un mode histoire, un mode arcade, un mode versus, un mode entraînement et un mode survie.', 'https://fr.wikipedia.org/wiki/Evil_Zone'),
  ('Q861322', 'The Adventures of Alundra, aussi appelé Alundra, est un jeu vidéo de type action-aventure développé par Matrix Software et sorti en 1997 sur PlayStation. Le jeu est inspiré de Landstalker et de Zelda, avec cependant un scénario plus développé (Alundra étant un elfe voyageant dans les rêves).

Alundra sort au Japon le 11 avril 1997 puis en Europe sous le titre de The Adventures of Alundra. En France, le jeu sort le 5 juin 1998 puis le 19 juin 1998 en Allemagne et en Espagne.

Le jeu a été réédité sur PlayStation 3 et PSP via le PlayStation Network en 2007 au Japon.', 'https://fr.wikipedia.org/wiki/The_Adventures_of_Alundra'),
  ('Q866904', 'CT Special Forces: Back to Hell, connu sous le nom de CT Special Forces 2: Back in the Trenches en Amérique du Nord, est un jeu vidéo de type run and gun développé par LSP Games sorti sur Game Boy Advance et PlayStation à partir de 2003.', 'https://fr.wikipedia.org/wiki/CT_Special_Forces:_Back_to_Hell');

insert into import_summary (wikidata_id, summary, source) values
  ('Q2064589', 'Incredible Crisis est un party game composé de plusieurs mini-jeux.

Sorti au Japon sous le nom de Tondemo Crisis, le jeu distille un humour japonisant et burlesque servi par une bande-son ska du groupe Tokyo Ska Paradise Orchestra.

Le joueur dirige les quatre membres d''une famille qui doivent rentrer à l''heure pour l''anniversaire de la grand-mère. Chaque personnage traverse des épreuves délirantes tout au long de la journée.

Le père Taneo va être poursuivi par une boule géante, puis foncer sur le périphérique tokyoite à bord d''un brancard. La mère Etsuko va être pris en otage par des braqueurs. Le fils Tsuyoshi est rapetissé dans les herbes de son école. Enfin, la fille Ririka s''enfuit de son école pour ensuite sauver le monde.', 'https://fr.wikipedia.org/wiki/Incredible_Crisis'),
  ('Q2351652', 'Super Puzzle Fighter II Turbo est un jeu vidéo de puzzle développé et édité par Capcom sur CP System II en mai 1996. Il a été porté sur plusieurs supports (console de salon et console portable et ordinateur personnel).', 'https://fr.wikipedia.org/wiki/Super_Puzzle_Fighter_II_Turbo'),
  ('Q858391', 'Spyro the Dragon est un jeu vidéo de plates-formes développé par Insomniac Games et édité par Sony Computer Entertainment sur PlayStation. Il s''agit du premier opus de la série Spyro the Dragon. Il est sorti le 10 septembre 1998 en Amérique du Nord, le 23 octobre 1998 en Europe et le 1er avril 1999 au Japon. Le jeu est republié le 12 décembre 2012 sur le PlayStation Store.

Le jeu met en scène Spyro, un jeune dragon. Accompagné d''Étincelle la libellule, celui-ci traverse les royaumes des Dragons afin de libérer ses congénères, lesquels ont été transformés en statues de cristal par Gnasty Gnorc; ce dernier a également transformé les joyaux des dragons en soldats. Pour mener à bien sa mission, Spyro dispose de capacités telles que cracher du feu, charger ses ennemis et planer.', 'https://fr.wikipedia.org/wiki/Spyro_the_Dragon_(jeu_vid%C3%A9o)'),
  ('Q2060276', 'MechWarrior 2: 31st Century Combat est un jeu vidéo d''action et de simulation de mecha sorti en 1995 sur PlayStation, Saturn et PC. C''est le deuxième épisode de la série MechWarrior.', 'https://fr.wikipedia.org/wiki/MechWarrior_2:_31st_Century_Combat'),
  ('Q2073940', 'Battle Arena Toshinden 2 est un jeu vidéo de combat développé par Tamsoft pour Takara et édité par Capcom sur système d''arcade ZN-1 en 1995. Il a été porté en 1996 sur plusieurs plates-formes.', 'https://fr.wikipedia.org/wiki/Battle_Arena_Toshinden_2'),
  ('Q2361986', 'Legend of Mana est un jeu vidéo de type action-RPG développé et édité par l''entreprise japonaise Square. Il s''agit du quatrième jeu de la série Seiken Densetsu / Mana à être édité.

Le jeu reste par certains points dans la logique des précédents, aussi bien au niveau scénaristique, comme la présence de l''arbre Mana et des 8 esprits élémentaires, qu''au niveau gameplay: les adversaires sont visibles en dehors des combats. Les possibilités d''évolution sont multiples: il y a onze types d''armes différents à utiliser, 26 compétences de base dont 8 connues au départ, 191 techniques spéciales à découvrir, utilisables seulement avec l''arme qui convient, la possibilité de construire des golems, ainsi que d''élever des monstres qui deviendront des animaux de compagnie.', 'https://fr.wikipedia.org/wiki/Legend_of_Mana'),
  ('Q2360194', 'Mega Man 5 (Rockman 5: Blues no Wana!? au Japon) est un jeu d''action-plate-formes développé et édité par Capcom sur NES en 1992, puis porté sur Console virtuelle (Wii, Wii U, Nintendo 3DS), et téléphone mobile (J2ME, Android, iOS). C''est le cinquième jeu de la série principale de Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_5'),
  ('Q2360218', 'Mega Man 6 (Rockman 6: Shijō Saidai no Tatakai!! au Japon) est un jeu d''action-plate-formes développé et édité par Capcom sur NES en 1993 au Japon et en 1994 Amérique du Nord, puis porté sur Console virtuelle (Wii U, Nintendo 3DS), et téléphone mobile (J2ME, Android, iOS). C''est le sixième jeu de la série principale de Mega Man. Il est sorti pour la première fois dans la région PAL lors de la publication du jeu sur la console virtuelle de la Nintendo 3DS en 2013 puis sur celle de la Wii U en 2014.', 'https://fr.wikipedia.org/wiki/Mega_Man_6'),
  ('Q1209867', 'Samurai Shodown est un jeu vidéo de combat en 2D développé et édité par SNK en 1993 sur Neo-Geo MVS, Neo-Geo AES et en 1994 sur Neo-Geo CD. Porté sur de nombreuses plateformes, le jeu marqua le début d''une longue série.', 'https://fr.wikipedia.org/wiki/Samurai_Shodown_(jeu_vid%C3%A9o,_1993)'),
  ('Q1203511', 'Mega Man X4 (Rockman X4 au Japon), est un action-plates-formes développé et édité par Capcom sur Saturn, PlayStation et PC (Windows). C''est le quatrième volet de la série Mega Man X. Le jeu est par la suite réédité sur téléphone mobile.', 'https://fr.wikipedia.org/wiki/Mega_Man_X4'),
  ('Q579615', 'TOCA Touring Car Championship est un jeu vidéo de course automobile développé par Codemasters sur PlayStation et PC. Il est sorti en Europe en novembre 1997, puis en février 1998 au Japon, et en septembre de la même année en Amérique du Nord, où, édité par The 3DO Company, il est intitulé TOCA Championship Racing. En Europe, le jeu est réédité dans la gamme Platinum en 1998, puis dans la gamme à bas prix Value Series. En novembre 2000, THQ développe un portage avec un système de jeu différent pour la Game Boy Color, développé par le studio Spellbound Software.

Le jeu met en scène les écuries et les circuits du championnat britannique des voitures de tourisme 1997 dans divers modes de jeu, dont le championnat, permettant au joueur d''affronter les pilotes de la saison 1997 ou de s''adonner au multijoueur. TOCA Touring Car Championship inclut notamment des commentaires dits par l''ancien pilote de Formule 1 Tiff Needell pour la version en anglais.', 'https://fr.wikipedia.org/wiki/TOCA_Touring_Car_Championship'),
  ('Q1201015', 'Klonoa: Door to Phantomile est un jeu vidéo de plates-formes développé par Namco, sorti à partir de 1997 sur PlayStation. Il s''agit du premier jeu de la série Klonoa.

Ce jeu fait partie de la compilation namCollection sortie en 2005 au Japon.', 'https://fr.wikipedia.org/wiki/Klonoa:_Door_to_Phantomile'),
  ('Q588710', 'Theme Hospital est un jeu vidéo de gestion développé par Bullfrog Productions et édité par Electronic Arts en 1997 sur MS-DOS et Microsoft Windows. Le joueur y conçoit et dirige un hôpital privé avec pour objectif de soigner des patients atteints de maladies fictives et volontairement loufoques. Le jeu s’inscrit comme le successeur thématique de Theme Park, également produit par Bullfrog, constituant le deuxième volet de la série « Theme ». Il se distingue particulièrement par son humour et par ses nombreuses références à la culture populaire.

Peter Molyneux et James Leach imaginent le concept d’un jeu Theme centré sur un hôpital, mais Molyneux ne participe pas directement au développement, occupé par Dungeon Keeper. À l’origine, les concepteurs envisagent d’intégrer quatre modes de jeu distincts correspondant à différentes périodes historiques, mais cette idée est abandonnée faute de temps. Un mode multijoueur permettant jusqu’à quatre participants est finalement ajouté via un correctif.', 'https://fr.wikipedia.org/wiki/Theme_Hospital'),
  ('Q577926', 'Earthworm Jim 2 est un jeu vidéo de plate-forme qui fait suite à Earthworm Jim et mettant en scène un ver de terre doté d''une combinaison extra-terrestre lui fournissant des super-pouvoirs. Le jeu est sorti sur les plates-formes Mega Drive, Super Nintendo, PlayStation, Sega Saturn, Game Boy Advance et Windows. Dans ce jeu, la présence d''œuvres musicales connues, comme Sonate au clair de lune 1er et 3e mouvements ou Funicula), est à noter.

La version Super Nintendo du jeu est également disponible sur Nintendo Switch avec le Nintendo Switch Online.', 'https://fr.wikipedia.org/wiki/Earthworm_Jim_2'),
  ('Q576673', '007 Racing est un jeu vidéo de combat motorisé mêlant des phases d''action, développé par Eutechnyx Limited et édité par Electronic Arts. Il est sorti sur PlayStation en décembre 2000.

Basé sur la licence James Bond, il permet d''incarner le célèbre agent britannique dans une série de missions à bord de véhicules aperçus dans les films, tels que l''Aston Martin DB5 ou encore la BMW Z3.', 'https://fr.wikipedia.org/wiki/007_Racing'),
  ('Q1200546', 'Descent est un jeu de tir à la première personne développé par Parallax Software et publié par Interplay Entertainment Corp. en 1995. Le jeu se distingue par une liberté de mouvement dans six directions, et de nombreuses extensions. Il fut le premier FPS à être entièrement réalisé en 3D. Il a engendré deux suites: Descent II et Descent 3.', 'https://fr.wikipedia.org/wiki/Descent_(jeu_vid%C3%A9o)'),
  ('Q583360', 'Xenogears est un jeu vidéo de rôle développé par Square Co. sous la direction de Tetsuya Takahashi. Il est édité sur PlayStation par Square Co. en février 1998 au Japon, puis en octobre par Sony CE en Amérique du Nord.

Le jeu propose une trame narrative recherchée, inspirée de plusieurs concepts de la philosophie moderne occidentale et de la psychanalyse, chose presque unique dans le jeu vidéo commercial.

Grâce à ce scénario complexe et abouti, le jeu rencontre le succès et se vend à plus d''1,1 million d''exemplaires, principalement au Japon.', 'https://fr.wikipedia.org/wiki/Xenogears'),
  ('Q1201000', 'Destruction Derby est un jeu vidéo de course de stock-car et de derby de démolition développé par Reflections et édité par Psygnosis en 1995 sur PlayStation, PC et Saturn en 1996. Le joueur dispose de différents modes de jeu dans lesquels il peut détruire les voitures de ses adversaires en les percutant avec la sienne, dans une arène, durant des courses sur circuit, ou seul contre-la-montre. Afin de rendre les résultats des collisions des voitures plus faciles à prévoir, les développeurs implémentent la physique simulée dans le moteur de jeu. Les performances sont conservées en réduisant les détails des modèles 3D et en optimisant les graphismes. Le nombre des collisions est favorisé par la petitesse des pistes.', 'https://fr.wikipedia.org/wiki/Destruction_Derby'),
  ('Q569822', 'Crash Bandicoot 2: Cortex Strikes Back est un jeu vidéo de plates-formes développé par Naughty Dog et édité par Sony Computer Entertainment en 1997 sur PlayStation. Le jeu est réédité pour les gammes Greatest Hits et The Best en 1998 ainsi que pour la gamme Platinum en 1999. Le jeu a été republié en 2007 sur la PlayStation Network mais a été retiré par mesure de précaution lorsque les jeux MediEvil et Spyro 2: Gateway to Glimmer ont eu des problèmes de fonctionnement. Il a ensuite été réédité sur le réseau américain le 10 janvier 2008 et sur le réseau européen le 2 février 2011.

L''histoire du jeu est la suite directe de Crash Bandicoot, l''opus éponyme de la série. Se déroulant sur un archipel d''îles fictives près de l''Australie, Crash Bandicoot 2: Cortex Strikes Back suit les aventures de l''anthropomorphe Crash Bandicoot, enlevé par le Docteur Neo Cortex, qui a apparemment changé de vie et veut désormais sauver le monde. Crash est ensuite envoyé dans plusieurs lieux de l''Île de N. Sanity afin de récupérer des cristaux qui permettront à Cortex de contenir la puissance de l''alignement des planètes et ainsi de protéger la Terre de la destruction. Crash est rejoint par sa sœur, Coco Bandicoot et occasionnellement par le Docteur Nitrus Brio, qui essaie de convaincre Crash de récupérer les gemmes au lieu des cristaux. Le jeu Crash Bandicoot 3: Warped est la suite de cet opus.', 'https://fr.wikipedia.org/wiki/Crash_Bandicoot_2:_Cortex_Strikes_Back'),
  ('Q2361288', 'NBA Live 98 est un jeu vidéo de basket-ball sorti en 1997 et fonctionne sur PlayStation, Saturn et PC. Le jeu a été développé par EA Sports, puis édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/NBA_Live_98'),
  ('Q1195880', 'Demain ne meurt jamais est un jeu vidéo de tir à la troisième personne sorti en novembre 1999 sur PlayStation. Il est édité par Electronic Arts et développé par Black Ops Entertainment.

Le jeu est basé sur le film homonyme de Roger Spottiswoode, sorti en 1997.', 'https://fr.wikipedia.org/wiki/Demain_ne_meurt_jamais_(jeu_vid%C3%A9o)'),
  ('Q1195840', 'One: Kagayaku Kisetsu e est un visual novel eroge japonais développé par la société Tactics, une marque de l''entreprise Nexton, sortie le 26 mai 1998 pour PC sous Windows 95. La plupart des créateurs de ce jeu sont devenus par la suite les fondateurs du studio de développement de visual novels Key. Plus tard, le jeu a été adapté sur PlayStation, puis est sortie une version entièrement vocalisée pour PC. Une suite librement adaptée, One2: Eien no Yakusoku, a été produite par BaseSon, une autre marque de Nexton, pour une sortie en avril 2002.

Deux séries OVA inspirées de One ont été créées. La première, portant le même nom que le jeu, était une série tous publics produite par le studio KSS entre 2001 et 2002, contenant quatre épisodes. La seconde série, nommée One: True Stories, est une série hentai produite par Cherry Lips entre 2003 et 2004, contenant trois épisodes. One: True Stories a été également publiée en anglais sous licence de Media Blasters. D''autres adaptations existent, dont quatre romans, des dramas audio en CD, et des anthologies de manga.', 'https://fr.wikipedia.org/wiki/One:_Kagayaku_Kisetsu_e'),
  ('Q1199765', 'Pooyan est un jeu d''arcade de type shoot them up publié par Konami en 1982.', 'https://fr.wikipedia.org/wiki/Pooyan'),
  ('Q1307981', 'Einhänder est un jeu vidéo de type shoot ''em up développé et édité par Square en 1997 sur PlayStation. Il a été réédité en 2008 sur PlayStation Network.', 'https://fr.wikipedia.org/wiki/Einh%C3%A4nder'),
  ('Q2272080', 'Galaga: Objectif Terre (en version originale Galaga: Destination Earth) est un jeu vidéo de type Shoot ''em up sorti en 2000 sur Game Boy Color, PlayStation et PC.', 'https://fr.wikipedia.org/wiki/Galaga_:_Objectif_Terre'),
  ('Q1300810', 'Mortal Kombat: Special Forces est un jeu vidéo de type beat them all développé et édité par Midway Games, sorti en 2000 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat:_Special_Forces'),
  ('Q2266405', 'Parasite Eve II est un jeu vidéo d''action à la troisième personne développé et édité par Square. Il est sorti sur la console PlayStation le 16 décembre 1999 au Japon, le 12 janvier 2000 en Amérique du Nord et le 25 août 2000 en Europe. Jouable en solo, Parasite Eve II mélange, comme son prédécesseur, des éléments de survival horror et de jeu de rôle.', 'https://fr.wikipedia.org/wiki/Parasite_Eve_II'),
  ('Q1300499', 'Mortal Kombat Trilogy (communément abrégé MKT) est une anthologie de la série Mortal Kombat. Il est considéré comme la dernière mise à jour de Mortal Kombat 3, dont la première est Ultimate Mortal Kombat 3. Ainsi, l''histoire est très similaire.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_Trilogy'),
  ('Q1300673', 'Mortal Kombat Mythologies: Sub-Zero est un jeu vidéo beat them all sorti en 1997 sur Nintendo 64 et PlayStation. Le jeu a été développé par Avalanche Software et édité par Midway.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_Mythologies:_Sub-Zero'),
  ('Q2366720', 'Super Pac-Man est un jeu vidéo sorti sur borne d''arcade en 1982 et développé par Namco.', 'https://fr.wikipedia.org/wiki/Super_Pac-Man'),
  ('Q975529', 'D est un jeu vidéo développé par WARP et édité par Acclaim Entertainment en 1995. Ce jeu est sorti sur compatible PC et sur consoles 3DO, PlayStation et Saturn. Au Japon, une édition spéciale appelée D''s Dinner: Director''s Cut a été rééditée le 1er janvier 1996 pour console 3DO (celle-ci contient entre autres le disque de la bande-son originale).

Pour éviter que D ne soit un tant soit peu censuré, Kenji Eno a reconnu avoir trompé son éditeur en lui envoyant tardivement une version « correcte », puis en substituant les disques « corrects » par ceux qu''il désirait voir commercialisés.

D a inspiré deux autres titres considérés comme ses suites, Enemy Zero et D2, qui n''ont en commun que les traits et le prénom de la jeune héroïne blonde, Laura.', 'https://fr.wikipedia.org/wiki/D_(jeu_vid%C3%A9o)'),
  ('Q980494', 'UEFA Euro 2000 est le jeu vidéo de football officiel du Championnat d''Europe de football 2000. Il existe sur PC et PlayStation.', 'https://fr.wikipedia.org/wiki/UEFA_Euro_2000_(jeu_vid%C3%A9o)'),
  ('Q972627', 'Metal Slug 2 (sous-titré Super Vehicle-001/II) est un jeu vidéo de type run and gun développé et édité par SNK en 1998 sur Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD (NGM 241). C''est le deuxième épisode de la série Metal Slug.', 'https://fr.wikipedia.org/wiki/Metal_Slug_2'),
  ('Q921957', 'Final Fantasy II est un jeu vidéo de rôle, développé par Square Co., Ltd., sorti sur Famicom (NES) en 1988 au Japon.

À ne pas confondre avec le jeu Super Nintendo Final Fantasy II sorti en Amérique du Nord en 1991, qui est une adaptation de Final Fantasy IV version Easy Type, renommée pour faire suite au premier Final Fantasy car les épisodes II et III ne sont finalement jamais sortis sur ce territoire.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_II'),
  ('Q920886', 'Transformers: Beast Wars Transmetals est un jeu vidéo de combat sorti en 1999 sur Nintendo 64 et PlayStation. Le jeu a été développé par Takara puis édité par Takara au Japon et par Bam! Entertainment aux États-Unis.

Le jeu est adapté de série Animutants.', 'https://fr.wikipedia.org/wiki/Transformers:_Beast_Wars_Transmetals'),
  ('Q589359', 'Tekken 2 est un jeu vidéo de combat développé par Namco, initialement sorti en 1995 sur borne d’arcade, puis adapté sur PlayStation et commercialisé en 1996. Il s’agit du deuxième épisode de la série Tekken, après le premier opus. La version originale d''arcade est commercialisée dans le mode Histoire du jeu Tekken 5 sur PlayStation 2, en 2007 sur PlayStation 3 et PlayStation Portable via le PlayStation Store, et en 2009 sur Zeebo via ZeeboNet.', 'https://fr.wikipedia.org/wiki/Tekken_2'),
  ('Q591378', 'Final Fantasy Tactics est un jeu vidéo de rôle tactique, développé par Square (devenu depuis Square Enix), sorti sur PlayStation le 20 juin 1997 au Japon et le 28 janvier 1998 en Amérique du Nord. Ce jeu fait partie de la série Final Fantasy; c''est un épisode « hors série » parce qu''il s''inscrit, à la différence des autres opus, dans la catégorie des jeux de rôle tactique. L''homme responsable du projet et du scénario est Yasumi Matsuno, un ancien membre de la société Quest, qui réalise son premier projet avec Square.

L''histoire du jeu se déroule dans le monde d''Ivalice. Elle est centrée sur un conflit, nommé « la Guerre des Lions », qui s''engage entre deux familles de nobles qui convoitent le trône du royaume. Le scénario suit les aventures de Ramza Beoulve, un jeune apprenti chevalier, souhaitant tout mettre en œuvre pour rétablir la paix sur le continent.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_Tactics'),
  ('Q622115', 'In the Hunt est un jeu vidéo de type shoot ''em up à défilement horizontal développé et édité par Irem sur borne d''arcade en 1993.', 'https://fr.wikipedia.org/wiki/In_the_Hunt'),
  ('Q2164524', 'Wild Arms est un jeu vidéo de rôle développé par Media.Vision et édité par Sony Computer Entertainment. Il est tout d''abord sorti au Japon en 1996, puis en Amérique du Nord en 1997 et en Europe en 1998 sur PlayStation. Il s''agit du premier opus de la série du même nom, en plus d''être parmi l''un des premiers jeux vidéo de rôle à sortir sur PlayStation. De plus, il a la particularité d''être un RPG japonais ayant un thème Western. Le jeu propose des graphismes en deux dimensions durant les phases d''exploration, tandis que les phases de combats sont affichés en trois dimensions.

Le jeu se déroule dans un monde fantastique nommé Filgaia. Le joueur suit les aventures d''un groupe d''aventuriers mécréants appelés les Dream Chasers. Ils parcourent le monde à la recherche de plaisir et de richesse. Le joueur prend le contrôle d''un jeune homme, Rudy, qui a la capacité de faire fonctionner les Ancient Relic Machines, des armes puissantes similaires à des armes à feu.', 'https://fr.wikipedia.org/wiki/Wild_Arms_(jeu_vid%C3%A9o)'),
  ('Q2201095', 'Bloody Roar 2: Bringer of the New Age (sous-titré The New Breed aux États-Unis) est un jeu vidéo de combat développé par Raizing en 1999. Blood Roar 2 est sorti au Japon le 28 janvier 1999, puis en Amérique du Nord le 25 mai 1999 et en France le 25 juin 1999', 'https://fr.wikipedia.org/wiki/Bloody_Roar_2:_Bringer_of_the_New_Age'),
  ('Q2195838', 'Namco Museum est une série de compilations vidéoludiques commercialisées par Namco à partir de 1995. Elle comprend la plupart des classiques du jeu d''arcade du développeur nippon de la fin des années 1970 et des années 1980. Les séries les plus récurrentes sont Pac-Man et Galaga, les deux séries les plus emblématiques de l''époque des années 80 et 90 chez Namco.

Les jeux émulés s''accompagnent généralement du mode museum, lequel propose divers contenus liés (illustrations conceptuelles, carte d''instructions, musiques, flyers...).', 'https://fr.wikipedia.org/wiki/Namco_Museum'),
  ('Q944320', 'Gran Turismo est un jeu vidéo de course automobile développé par Polys Entertainment et édité par Sony Computer Entertainment en 1997 sur PlayStation.

Premier épisode de la série du même nom, le titre a connu un succès international avec près de onze millions d''exemplaires écoulés, ce qui en fait le jeu le plus vendu sur PlayStation. Le jeu de Kazunori Yamauchi a révolutionné le genre en imposant de nouveaux standards en matière de rendu visuel, de physique et de contenu.', 'https://fr.wikipedia.org/wiki/Gran_Turismo_(jeu_vid%C3%A9o)'),
  ('Q1274056', 'Shadow Man est un jeu vidéo d''action-aventure sorti en 1999 sur Windows, Dreamcast, Nintendo 64 et PlayStation. Le jeu a été développé par Iguana Teesside et édité par Acclaim. Il a été conçu par Guy Miller et Simon Phipps et s''inspire librement du comics Shadowman publié par Valiant Comics.

Une suite intitulée Shadow Man: 2econd Coming a été publié exclusivement sur PlayStation 2 en 2002.', 'https://fr.wikipedia.org/wiki/Shadow_Man_(jeu_vid%C3%A9o)'),
  ('Q615921', '3D Lemmings (intitulé Lemmings 3D aux États-Unis) est un jeu vidéo de réflexion développé par Clockwork Games et édité par Psygnosis en 1995 sur DOS, PlayStation et Saturn.

C''est le premier épisode de série Lemmings à gérer des environnements en trois dimensions, ce qui a une incidence sur le gameplay. L''épisode marque également la fin de l''implication des créateurs originaux, DMA Design.', 'https://fr.wikipedia.org/wiki/3D_Lemmings'),
  ('Q617303', 'Akumajō Dracula est un jeu vidéo d''action et de plates-formes développé par Konami Computer Entertainment Tokyo, un studio de Konami. Il est sorti, uniquement au Japon, en 1993 sur X68000.', 'https://fr.wikipedia.org/wiki/Akumaj%C5%8D_Dracula_(jeu_vid%C3%A9o,_1993)'),
  ('Q615211', 'Gex contre Dr. Rez (Gex 3: Deep Cover Gecko en version originale, et sur Nintendo 64), est un jeu vidéo de plates-formes développé par Crystal Dynamics, sorti en 1999 sur PlayStation et Nintendo 64. Le jeu fait partie de la série Gex. Il est édité par Eidos Interactive sur PlayStation, tandis que le portage sur Nintendo 64 est réalisé par Gratuitous Games, et édité par Crave Entertainment. Une adaptation sur Game Boy Color, éditée par Eidos Interactive, paraît également en 1999 sous le nom Gex: Deep Cover Gecko en Europe (et Gex 3: Deep Pocket Gecko en Amérique du Nord).', 'https://fr.wikipedia.org/wiki/Gex_contre_Dr._Rez'),
  ('Q2202049', 'Ubik est un jeu vidéo de stratégie et d''action de science-fiction développé et édité par le studio français Cryo Interactive, sorti en France en 1998 sur PC et en octobre 2000 sur PlayStation. Il se déroule dans l''univers du roman éponyme de l''auteur américain Philip K. Dick.', 'https://fr.wikipedia.org/wiki/Ubik_(jeu_vid%C3%A9o)'),
  ('Q2233550', 'Deathtrap Dungeon est un jeu vidéo d''action-aventure, édité par Eidos Interactive et développé par Asylum Entertainment. Il est sorti en 1998 sur PlayStation et PC.

Le jeu est basé sur le livre dont vous êtes le héros de l''auteur britannique Ian Livingstone intitulé Le Labyrinthe de la mort dans la collection Défis fantastiques.', 'https://fr.wikipedia.org/wiki/Deathtrap_Dungeon'),
  ('Q1261715', 'UFO: Enemy Unknown (X-COM: UFO Defense dans sa version américaine) est un jeu vidéo de tactique au tour par tour développé par Mythos Games et MicroProse. Le jeu est publié par MicroProse sur PC et Amiga en 1994, puis sur la console PlayStation en 1995.

Conçu au départ par Julian Gollop comme une suite de Laser Squad sorti en 1988, le jeu mélange des éléments de gestion et de tactique au tour par tour. Le joueur commande une organisation appelée X-COM (eXtraterrial COMbat unit), dont l’objectif est de défendre la Terre contre les invasions extraterrestres.

Le titre est très bien reçu par les critiques et par les joueurs, ce qui conduit MicroProse à développer plusieurs suites, comme X-COM: Terror from the Deep ou X-COM: Apocalypse, et d''autres développeurs à s''inspirer du concept.', 'https://fr.wikipedia.org/wiki/UFO:_Enemy_Unknown'),
  ('Q606142', 'Duke Nukem: Land of the Babes est un jeu vidéo de tir à la troisième personne sorti en 2000 sur PlayStation. Le jeu a été développé par n-Space puis édité par GT Interactive.', 'https://fr.wikipedia.org/wiki/Duke_Nukem:_Land_of_the_Babes'),
  ('Q1288651', 'Snatcher est un jeu vidéo d''aventure (un roman graphique interactif) conçu et réalisé par Hideo Kojima pour la société Konami. Édité sur plusieurs machines, depuis le PC-8801 et le MSX 2 en 1988 jusqu''aux consoles 32 bits Saturn et PlayStation en 1996, seule la version Mega-CD a été traduite et distribuée en dehors du Japon. Jeu culte pour certains joueurs, ce jeu d''aventure reprend les thèmes de divers œuvres de science-fiction et de cyberpunk comme Blade Runner et Terminator.', 'https://fr.wikipedia.org/wiki/Snatcher'),
  ('Q614287', 'Primal Rage est un jeu de combat développé par Atari Games, sorti en arcade en 1994 et converti ensuite sur de nombreux supports, tels que Atari Jaguar, PlayStation, Saturn, Super Nintendo, Mega Drive et 32X, Amiga et PC.', 'https://fr.wikipedia.org/wiki/Primal_Rage_(jeu_vid%C3%A9o)'),
  ('Q2165750', 'Parasite Eve パラサイト・イヴ est un jeu vidéo d''action-aventure avec des éléments d''horreur, développé et édité par Square Co. en 1998 sur PlayStation. Il est uniquement sorti au Japon et en Amérique du Nord.

L''histoire se déroule à Manhattan, autour de l''inspectrice de police du NYPD Aya Brea, et d''une chanteuse d''opéra, Melissa Pearce, qui s''est transformée en un monstre. La base du scénario tourne autour des mitochondries mutantes présentes dans le corps de Pearce, qui ont atteint un niveau de développement suffisant pour modifier ses cellules, ce qui entraîne chez elle une perte totale du contrôle de son corps et de son esprit. Elle mute alors et possède des attributs non-humains, comme la possibilité de voler. Elle n''est dès cet instant plus Pearce mais Eve. Les mitochondries mutantes s''échappent de son corps afin de contaminer des centaines d''autres êtres, humains et animaux, qui sèment alors la terreur. Une des caractéristiques de ces mitochondries mutantes réside dans le fait qu''elles peuvent produire d''énormes quantités d''énergie, jusqu''à provoquer des combustions humaines spontanées. Pour des raisons révélées plus tard dans le jeu, Aya est immunisée contre les pouvoirs de Eve, elle essaye donc par tous les moyens de combattre cette dernière.', 'https://fr.wikipedia.org/wiki/Parasite_Eve_(jeu_vid%C3%A9o)'),
  ('Q943115', 'Spyro: Year of the Dragon est un jeu vidéo de plates-formes développé par Insomniac Games et édité par Sony Computer Entertainment en 2000 sur PlayStation. Le jeu est réédité pour la gamme Platinum le 12 octobre 2001 et la gamme Greatest Hits en 2002. Il est également disponible sur PlayStation Store depuis le 12 décembre 2012. Troisième et dernier épisode de la série originelle Spyro the Dragon, commencée en 1998, à être développé par Insomniac Games, Spyro: Year of the Dragon est le seul jeu de la trilogie à ne pas être édité au Japon.

Nommé d''après l''animal du zodiaque chinois célébré en 2000, le dragon, ce troisième opus présente les aventures de Spyro dans son périple à travers les Mondes Oubliés, après que cent cinquante œufs de dragons ont été volés par une sorcière. Le joueur parcourt ainsi trente-sept mondes différents afin de les récupérer. Spyro: Year of the Dragon se démarque de ses deux prédécesseurs par la présence de nouveaux personnages jouables ainsi que de nouveaux mini-jeux venant s''ajouter à ceux déjà existants, tout en offrant des graphismes et une bande-son améliorés.', 'https://fr.wikipedia.org/wiki/Spyro:_Year_of_the_Dragon'),
  ('Q1290054', 'Raiden est un jeu vidéo de type shoot ''em up sorti sur borne d''arcade en 1990.', 'https://fr.wikipedia.org/wiki/Raiden_(jeu_vid%C3%A9o)'),
  ('Q914128', 'Discworld Noir est un jeu vidéo d''aventure basé sur l''univers du Disque-monde de Terry Pratchett, et scénarisé par Chris Bateman. Il est sorti en 1999 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/Discworld_Noir'),
  ('Q917503', 'Gyruss est un jeu vidéo de type shoot ''em up développé par Konami et publié par Centuri en 1983 sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/Gyruss'),
  ('Q913223', 'FIFA 98: En route pour la Coupe du monde est un jeu vidéo de football sorti en 1997 et fonctionne sur Nintendo 64, PlayStation, Windows, Game Boy, Super Nintendo, Mega Drive et Saturn. Le jeu a été édité par EA Sports.

Il est aujourd''hui célèbre pour sa bande son, composée notamment de Song 2 de Blur, et de nombreuses chansons de The Crystal Method.

Suivant les pays, le joueur figurant sur la boite du jeu était différent: Andreas Möller pour l''Allemagne, Raúl pour l''Espagne, Roy Lassiter pour les États-Unis, David Ginola pour la France, Paolo Maldini pour l''Italie, David Beckham pour le Royaume-Uni.', 'https://fr.wikipedia.org/wiki/FIFA_98_:_En_route_pour_la_Coupe_du_monde'),
  ('Q1059405', 'Dōkyūsei, ou, pour sa version internationale anglaise Dōkyūsei: Bangin'' Summer, également surnommé « Nanpa 1 », est un jeu vidéo de drague pour adultes développé par la société ELF. C''est le premier jeu de la série Dōkyūsei. Il est sorti à l''origine en 1992 pour DOS/V (en) et pour les micro-ordinateurs de série PC-9800.', 'https://fr.wikipedia.org/wiki/D%C5%8Dky%C5%ABsei_(jeu_vid%C3%A9o)'),
  ('Q945697', 'Assault Rigs est un jeu vidéo d''action développé et édité par Psygnosis en 1996, disponible sur DOS, PlayStation et Saturn.', 'https://fr.wikipedia.org/wiki/Assault_Rigs'),
  ('Q1053648', 'Centipede est un jeu vidéo développé par Atari Inc., sorti en 1981 sur borne d''arcade. C''est le seul jeu de Dona Bailey, qui l''a programmé conjointement avec Ed Logg. Il est considéré comme un des premiers jeux à avoir attiré les femmes dans les salles d''arcade, après Pac-Man.

Il s''agit d''un shoot ''em up fixe. Le joueur incarne un nain qui doit protéger son jardin des insectes (centipede ou littéralement chilopodes). Le principe est d''accumuler le plus de points possible en détruisant les opposants.

Il fut adapté sur multiples consoles de jeux vidéo, comme l’Atari 2600 ou la Game Boy. Ce jeu a connu une suite: Millipede sorti en 1982 sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/Centipede'),
  ('Q1062256', 'Colin McRae Rally est un jeu vidéo de course de rallye automobile développé et édité par Codemasters, sorti sur PlayStation et Windows. Le jeu paraît en Europe en 1998, puis en Amérique du Nord en 2000. Réalisé avec le soutien du champion du monde des rallyes écossais Colin McRae, Colin McRae Rally est considéré à sa sortie comme la référence des simulations de rallye. Plusieurs suites voient le jour. Une adaptation Game Boy Color développée par Spellbound Entertainment et distribuée par THQ est publiée en Europe en 2001.', 'https://fr.wikipedia.org/wiki/Colin_McRae_Rally_(jeu_vid%C3%A9o,_1998)'),
  ('Q1228607', 'Discworld est un jeu d''aventure graphique basé sur l''univers du Disque-monde sorti sur PC en 1995. Il a été développé par Perfect Entertainment.

Il a pour suite Discworld II: Mortellement vôtre !. Par ailleurs, un autre jeu d''aventure basé sur l''univers du Disque-monde est sorti, Discworld Noir, mais cette fois-ci sans Rincevent dans le rôle principal.', 'https://fr.wikipedia.org/wiki/Discworld_(jeu_vid%C3%A9o)'),
  ('Q1228604', 'Discworld II: Mortellement vôtre ! (Discworld II: Missing Presumed...!? en VO) est un jeu vidéo d''aventure développé par Perfect Entertainment et édité par Psygnosis en 1996, sous DOS et Windows.

Il a été adapté en 1997 sur PlayStation et Saturn. C''est la seconde adaptation en jeu vidéo d''aventure en point-and-click basée sur l''univers du Disque-monde de Terry Pratchett.', 'https://fr.wikipedia.org/wiki/Discworld_II_:_Mortellement_v%C3%B4tre_!'),
  ('Q1248594', 'Resident Evil (ou Bio Hazard au Japon) est un jeu vidéo du genre survival horror développé et édité par Capcom, sorti le 22 mars 1996 sur PlayStation, puis en 1997 sur Saturn et Windows. En 1997, Capcom édite également Resident Evil: Director''s Cut, une version non-censurée destinée à la PlayStation qui se différencie notamment par plusieurs modifications des scènes de jeu.', 'https://fr.wikipedia.org/wiki/Resident_Evil_(jeu_vid%C3%A9o,_1996)'),
  ('Q944463', 'MediEvil II est un jeu vidéo d''action-aventure et de plates-formes développé par SCE Studio Cambridge et édité par Sony Computer Entertainment en 2000 sur PlayStation.

Il s''agit de la suite de MediEvil. L''action se situe dans l''Angleterre du XIXe siècle où un homme retrouve le grimoire de Zarok. Sir Daniel Fortesque, le héros, est de nouveau ressuscité mais sa tombe a été transportée dans un musée. Il parcourt une vingtaine de niveaux où il doit combattre un squelette de dinosaure, un trio d''éléphants mécanique, un boxeur zombie, un seigneur vampire, Jack l''Éventreur, un démon ainsi que les deux acolytes ennemis qui ont respectivement l''allure d''un chien et d''un lézard.', 'https://fr.wikipedia.org/wiki/MediEvil_II'),
  ('Q1224677', 'Digimon World 2003 est un jeu vidéo de rôle, d''action et d''aventure, basé sur la franchise médiatique japonaise Digimon, développé par Bandai et édité par Atari Inc. sur console PlayStation. Partie intégrante de la série des jeux vidéo Digimon et troisième opus initial du jeu Digimon World, il a été commercialisé le 5 juin 2002 en Amérique du Nord puis le 4 juillet au Japon et le 29 novembre de la même année en Europe.

Le joueur incarne un enfant nommé Junior, accompagné au début du jeu par ses deux amis, Teddy et Ivy, voyageant dans un MMORPG de réalité virtuelle en ligne nommé Digimon Online, comptant plus de 200 000 joueurs et contrôlé par la corporation MAGAMI. Cependant, tous les joueurs, dont Junior, se retrouvent piégés dans le système interne du jeu à la suite d''une attaque terroriste sur Internet et Junior doit tenter de rétablir l''ordre à l''aide de ses trois partenaires digimon.', 'https://fr.wikipedia.org/wiki/Digimon_World_2003'),
  ('Q1045002', 'Warriors of Fate (Tenchi Wo Kurau II: Sekiheki no Tatakai au Japon, Sangokushi II en Asie) est un jeu vidéo à défilement horizontal de type beat them all développé et édité par Capcom sur borne d''arcade en octobre 1992. C''est la suite de Dynasty Wars, basée sur le manga japonais Tenchi wo Kurau, également réalisé sur CP System en 1989.', 'https://fr.wikipedia.org/wiki/Warriors_of_Fate'),
  ('Q1061937', 'Shin Megami Tensei est un jeu vidéo de rôle sorti en 1992 et fonctionne sur Mega-CD, Super Nintendo, Game Boy Advance, PC-Engine CD et PlayStation. Le jeu a été développé et édité par Atlus.

Ce jeu est la suite de la série de RPG Megami Tensei sortie sur NES en 1987. Ces jeux étaient inspirés des livres de science-fiction Digital Devil Story Megami Tensei écrits par Aya Nishitani; Shin Megami Tensei y fait de nombreuses références, mais son spin-off Shin Megami Tensei: Digital Devil Saga n''a aucun lien avec ces histoires.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei'),
  ('Q1042365', 'Agarest: Generations of War, ou Agarest Senki au Japon, ou bien Record of Agarest War en Amérique du Nord, est un jeu vidéo de rôle tactique sur PlayStation 3. Le jeu provient d''une collaboration entre Idea Factory, Red Entertainment et Compile Heart. Une adaptation Xbox 360 est sorti au Japon le 27 novembre 2008.', 'https://fr.wikipedia.org/wiki/Agarest:_Generations_of_War'),
  ('Q1062106', 'Tekken 3 est un jeu vidéo de combat, développé et édité par Namco sur borne d''arcade en 1997 puis adapté sur PlayStation en 1998. Il est le troisième épisode de la série Tekken.', 'https://fr.wikipedia.org/wiki/Tekken_3'),
  ('Q953890', 'Alien Trilogy est un jeu vidéo de tir à la première personne, développé par Probe Entertainment Limited et distribué par Acclaim Entertainment, publié en 1996 sur PC (DOS et Windows) et consoles Saturn et PlayStation. Le jeu se déroule dans l''univers des trois premiers films de la tétralogie Alien.', 'https://fr.wikipedia.org/wiki/Alien_Trilogy'),
  ('Q950846', 'Crusader: No Remorse est un jeu vidéo d''action développé par Origin Systems et édité par Electronic Arts, sorti en 1995 sur PC fonctionnant sous MS-DOS et en 1997 sur Saturn et PlayStation. Il est ensuite adapté en 2011 par GOG.com pour être compatible avec les versions les plus modernes de Windows et Mac OS X.

Il a pour suite Crusader: No Regret.', 'https://fr.wikipedia.org/wiki/Crusader:_No_Remorse'),
  ('Q953511', 'Clock Tower est un jeu vidéo de type point-and-click développé par la société japonaise Human Entertainment, édité uniquement au Japon sur Super Nintendo en 1995, sur PC et PlayStation en 1997, rebaptisé pour cette dernière Clock Tower ~The First Fear~ et sur WonderSwan en 1999. Le jeu est en général perçu comme un des jeux les plus terrifiants de la Super Nintendo.

L''histoire se déroule en Norvège, en 1995. Quatre orphelines, Jennifer, Lotte, Anne et Laura, sont adoptées par Mrs. Mary Barrows, qui vit dans son manoir coupé du monde (surnommé Clock Tower à cause de son imposant clocher) avec son mari. Après avoir conduit les filles dans le hall principal, Mrs. Barrows part chercher son mari. Mais au bout de quelques minutes, inquiète de ne voir personne revenir, Jennifer se lance à sa recherche. Après avoir quitté le hall, elle entend un cri et, en revenant sur ses pas, trouve la salle vide et est maintenant poursuivie par un enfant défiguré portant une paire de cisailles à haie, le Scissorman. L''objectif de Jennifer sera maintenant de fuir le manoir, si possible avec ses amies.', 'https://fr.wikipedia.org/wiki/Clock_Tower_(jeu_vid%C3%A9o)'),
  ('Q2137362', 'Jackie Chan Adventures est un jeu vidéo d''action mettant en vedette Jackie Chan. Ce jeu a été édité par Sony Computer Entertainment et développé par Atomic Planet. Il est sorti sur console PlayStation le 6 octobre 2004. Le jeu est basé sur la sérié télévisée d''animation Jackie Chan. Il regroupe l''histoire des 2 premières saisons.', 'https://fr.wikipedia.org/wiki/Jackie_Chan_Adventures'),
  ('Q2164073', 'Um Jammer Lammy est un jeu vidéo de rythme développé par NanaOn-Sha et édité par Sony Computer Entertainment, sorti en 1999 sur PlayStation.

La version PlayStation a été rééditée en téléchargement sur PlayStation 3 et PlayStation Portable via le PlayStation Network en 2007.', 'https://fr.wikipedia.org/wiki/Um_Jammer_Lammy'),
  ('Q2132221', 'L''Île Lego 2: La Revanche de Casbrick (Lego Island 2: The Brickster''s Revenge) est un jeu vidéo d''action-aventure sorti en 2001, basé sur la licence Lego, un jeu de construction en briques de plastique. Suite du jeu Aventures sur l''île Lego, sorti en 1997, il présente les aventures de Pepper, chargé dans cet opus de récupérer les Pages de la Constructopédia volée par Casbric, et d''arrêter celui-ci.

Le jeu se présente sous forme de mini-jeux et d''exploration de quatre univers (île Lego, île Castle, île des Adventurers et monde d''Ogel).', 'https://fr.wikipedia.org/wiki/L%27%C3%8Ele_Lego_2_:_La_Revanche_de_Casbrick'),
  ('Q2137570', 'OverBlood est un jeu vidéo de science-fiction développé par Riverhillsoft et édité par Electronic Arts pour la PlayStation. Le jeu est sorti sur le PSN japonais le 23 février 2011.

Il est considéré comme l''un des tout premiers survival horror utilisant des décors et un environnement en trois dimensions[réf. nécessaire].', 'https://fr.wikipedia.org/wiki/OverBlood'),
  ('Q1070478', 'Populous: À l''aube de la création (titre original: Populous: The Beginning) est un jeu vidéo de type simulation divine (god game) et stratégie en temps réel. Il fut développé par Bullfrog Productions et publié par Electronic Arts le 15 septembre 1998 en Europe, puis le 30 novembre 1998 en Amérique du Nord. Le jeu a également été porté sur PlayStation en 1999 et est disponible sur le PlayStation Network depuis 2007. C''est le troisième épisode de la série Populous, faisant suite à Populous et Populous 2: Trials of the Olympian Gods, publiés respectivement en 1989 et 1991. Contrairement aux précédents titres de la série, dans lesquels le joueur incarne un dieu influençant ses adeptes, ce troisième opus met le joueur dans la peau d’une chamane contrôlant directement sa tribu. Au cours des vingt-cinq missions de la campagne solo du jeu, le joueur mène sa tribu à la conquête d’un système solaire où il affronte d’autres tribus pour le contrôle de la magie devant lui permettre de devenir un dieu.', 'https://fr.wikipedia.org/wiki/Populous_:_%C3%80_l%27aube_de_la_cr%C3%A9ation'),
  ('Q597808', 'Crash Bash est un jeu vidéo de type party game développé par Eurocom et édité par Sony Computer Entertainment en 2000 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Crash_Bash'),
  ('Q605180', 'Street Fighter: The Movie est un jeu vidéo combat développé par Capcom et édité en août 1995 par Capcom au japon et Acclaim dans le reste du monde. Le jeu est sorti sur PlayStation et Saturn. Il est basé sur le film Street Fighter, lui-même basé sur la série de jeux vidéo Street Fighter.', 'https://fr.wikipedia.org/wiki/Street_Fighter:_The_Movie_(jeu_vid%C3%A9o)'),
  ('Q598160', 'NBA Showtime: NBA on NBC est un jeu vidéo de basket-ball sorti en 1999 et fonctionne sur arcade, Dreamcast, Nintendo 64, Game Boy Color et PlayStation. Le jeu a été développé par Eurocom puis édité par Midway.', 'https://fr.wikipedia.org/wiki/NBA_Showtime:_NBA_on_NBC'),
  ('Q1065861', 'Re-Volt est un jeu vidéo de course de voitures radiocommandées, conçu par Paul Phippen et Simon Harrison, développé par Acclaim Studios London et édité par Acclaim Entertainment. Il est sorti sur Microsoft Windows, Nintendo 64, PlayStation et Dreamcast en 1999. En 2006, Throwback Entertainment (en) acquiert la licence et les droits de publications de Re-Volt. En 2012, le jeu est porté sur iOS, sous l''appellation Re-Volt Classic.

Il a pour suite RC Revenge.', 'https://fr.wikipedia.org/wiki/Re-Volt'),
  ('Q602617', 'Resident Evil: Survivor, connu sous le nom de Biohazard: Gun Survivor au Japon, est un jeu vidéo de tir au pistolet développé par Capcom et édité par Eidos Interactive en 2000 sur PlayStation. Le jeu fait partie de la série Resident Evil et c''est le premier de la série dit des « Gun Survivor ».', 'https://fr.wikipedia.org/wiki/Resident_Evil:_Survivor'),
  ('Q1068778', 'Tom Clancy''s Rainbow Six est un jeu vidéo de tir à la première personne et d''infiltration (FPS tactique) inspiré du roman Rainbow Six de Tom Clancy, développé et édité par Red Storm Entertainment, sorti en 1998 sur PC. Il a ensuite été porté à partir de 1999 sur Dreamcast, Nintendo 64, PlayStation, Game Boy Color et téléphone mobile.

Le concept du jeu a été imaginé par Tom Clancy.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Rainbow_Six_(jeu_vid%C3%A9o)'),
  ('Q1069537', 'Medal of Honor est un jeu vidéo de tir à la première personne développé par DreamWorks Interactive et édité par Electronic Arts en novembre 1999 en Amérique du Nord, puis en décembre en Europe. C''est le premier opus de la série de jeux vidéo Medal of Honor. Le jeu est réédité en juin 2009 sur le PlayStation Network.

Le joueur incarne un soldat de l''Office of Strategic Services durant la Seconde Guerre mondiale. Le scénariste est Steven Spielberg et le compositeur Michael Giacchino.', 'https://fr.wikipedia.org/wiki/Medal_of_Honor_(jeu_vid%C3%A9o,_1999)'),
  ('Q604864', 'Batman et Robin est un jeu vidéo d''action développé par Probe Entertainment et édité par Acclaim Entertainment en 1998 sur PlayStation et aussi sur Game.com (développé et édité par Tiger Electronics) en 1997. Ce jeu a reçu de très mauvaises critiques.', 'https://fr.wikipedia.org/wiki/Batman_et_Robin_(jeu_vid%C3%A9o)'),
  ('Q593769', 'Star Ocean: The Second Story est un jeu vidéo de type Action RPG développé par tri-Ace et édité par Enix. Il est sorti sur PlayStation en 1998. Il constitue le deuxième épisode de la série Star Ocean.

Une version remastérisée, titrée Star Ocean: The Second Evolution, est sortie sur PlayStation Portable en 2008 au Japon, puis en 2009 en Amérique du Nord et en Europe.

Un remake titré Star Ocean: The Second Story R est sorti le 2 novembre 2023 sur Windows, Playstation 4, Playstation 5 et Nintendo Switch.

L''histoire se déroule vingt ans après le premier opus, Star Ocean. Le jeu est traduit en français dans sa version européenne dans le jeu d''origine et dans le remake mais uniquement en anglais dans sa version PSP.', 'https://fr.wikipedia.org/wiki/Star_Ocean:_The_Second_Story'),
  ('Q927730', 'NHL 2001 est un jeu vidéo de hockey sur glace sorti en 2001 sur PSX, PS2 et PC. Il est la création des studios d’Electronic Arts et reprend toutes les données de la saison 2001 de hockey (joueurs, équipes…). Owen Nolan des Sharks de San Jose figure sur la couverture du jeu.', 'https://fr.wikipedia.org/wiki/NHL_2001'),
  ('Q1383776', 'Exhumed (connu également sous le nom Powerslave aux États-Unis et Seireki 1999: Pharaoh no Fukkatsu au Japon) est un jeu d''action en vue subjective réalisé par Lobotomy Software en 1996.

Le joueur affronte de nombreux monstres et ennemis dans des niveaux sur le thème de l''Égypte.

Utilisant le même moteur graphique que Duke Nukem 3D, Exhumed transpose l''histoire dans l''Égypte ancienne.

Une version remasterisée et développée par Nightdive Studios, dénommée Powerslave: Exhumed, est prévue pour le 10 février 2022 sur PC.', 'https://fr.wikipedia.org/wiki/Exhumed'),
  ('Q942390', 'MediEvil est un jeu vidéo d''action-aventure et de plates-formes développé par SCE Studio Cambridge et édité par Sony Computer Entertainment en 1998 sur PlayStation.

Fort de son succès commercial, MediEvil sort en gamme Platinum sur PlayStation avant d''avoir sa suite, MediEvil 2, et d''être réédité sur PSP et PlayStation 3 en 2006 et 2007. Un remake 4K développé par Other Ocean Interactive est annoncé sur Playstation 4 lors de la Playstation Experience en décembre 2017 et sort le 25 octobre 2019.

MediEvil innove à l''époque sur PlayStation par des graphismes et une bande-son de qualité mais aussi par son univers médiéval décalé et teinté d''humour noir reprenant les thèmes d''Halloween chers au réalisateur Tim Burton, l''une des particularités marquantes étant que le joueur incarne un squelette en armures, dépossédé de sa mâchoire inférieure et de son œil gauche.', 'https://fr.wikipedia.org/wiki/MediEvil'),
  ('Q960854', 'Team Buddies est un jeu vidéo développé par le studio Osiris Studios de Psygnosis. Il est sorti le 13 septembre 2000 en France métropolitaine. Team Buddies met en scène des équipes de buddies, petites pilules colorées en plastique, se livrant bataille.

Les buddies vivaient paisiblement jusqu''à ce qu''un cube géant ne vienne semer la discorde en parachutant chez eux des caisses remplies d''armes. Ils sont alors regroupés par équipes de même couleur, ont commencé à se battre pour obtenir des armes, et dominer les autres équipes.

Le but d''une partie dans le jeu est de développer son armée (limitée a 4 buddies) et de détruire ensuite les autres équipes. Pour cela, le joueur dispose des caisses précédemment larguées pour fabriquer des armes, des buddies, ou des tanks.', 'https://fr.wikipedia.org/wiki/Team_Buddies'),
  ('Q1408596', 'Final Fantasy Anthology est une compilation regroupant deux jeux de rôle développés à l''origine par Square pour la console Super Nintendo, spécialement retravaillés et améliorés pour la console PlayStation de Sony. On distingue deux versions de cette compilation: la version nord-américaine contient les jeux Final Fantasy V et Final Fantasy VI, alors que la version européenne, intitulée Final Fantasy Anthology Édition Européenne, inclut les jeux Final Fantasy IV et Final Fantasy V. De plus, la version nord-américaine contient un disque audio bonus nommé Music from FFV and FFVI, non présent dans la version européenne. Au Japon, les trois jeux ont été distribués individuellement puis regroupés au sein d''une compilation en édition limitée intitulée Final Fantasy Collection, sortie le 11 mars 1999.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_Anthology'),
  ('Q939837', 'Syphon Filter est un jeu vidéo de tir à la troisième personne et d''infiltration développé par Eidetic et édité par Sony Computer Entertainment en 1999 sur PlayStation.

Le jeu est le premier épisode de la série Syphon Filter.', 'https://fr.wikipedia.org/wiki/Syphon_Filter_(jeu_vid%C3%A9o)'),
  ('Q937383', 'Fear Effect est un jeu vidéo d''action-aventure développé par Kronos Digital Entertainment (en) et édité par Eidos Interactive en 2000 sur PlayStation. Le joueur incarne trois mercenaires: Hana, Deke et Glas. Ce jeu arbore un style graphique particulier pour l''époque, typé manga — style qui n''est pas à proprement parler du cel-shading puisque la palette de couleurs réduite utilisée pour le jeu est liée aux textures (fixes) et non à l''éclairage dynamique. Il comporte de nombreuses phases d''action et de réflexion, qui s''enchaînent dans une ambiance cinématographique.

Un an après sa sortie, Fear Effect sera suivi d''un deuxième épisode Fear Effect 2: Retro Helix, racontant le passé des trois héros.', 'https://fr.wikipedia.org/wiki/Fear_Effect'),
  ('Q1399967', 'Theme Park World (également commercialisé sous le nom de Sim Theme Park) est un jeu de gestion de parc à thèmes. Il s''agit du second opus de la série Theme Park, créée par Peter Molyneux. Le jeu fut développé par la société Bullfrog Productions et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Theme_Park_World'),
  ('Q925253', 'Mortal Kombat 3 (communément abrégé MK3) est un jeu vidéo de combat, développé par la société américaine Midway, et troisième titre de la série Mortal Kombat, sorti sur borne d''arcade en 1995. Mortal Kombat 3 suit Mortal Kombat II, et précède Ultimate Mortal Kombat 3, puis Mortal Kombat Trilogy, ces deux derniers étant plus ou moins des mises à jour de MK3.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_3'),
  ('Q1370988', 'Salamander, renommé Life Force en Amérique du Nord et pour sa réédition sur borne d''arcade au Japon, est un shoot ''em up développé et édité par Konami, sorti en 1986 sur borne d''arcade. Il a été adapté sur Amstrad CPC, Commodore 64, MSX, Nintendo Entertainment System, PC-Engine, X68000 et ZX Spectrum.

C''est un jeu dérivé de la série Gradius qui a connu une suite, Salamander 2, sorti en 1996.', 'https://fr.wikipedia.org/wiki/Salamander_(jeu_vid%C3%A9o)'),
  ('Q953922', 'Worms Armageddon est un jeu vidéo de stratégie au tour par tour, dit jeu d''artillerie ou Worms-like développé par Team17 et sorti en 1999.', 'https://fr.wikipedia.org/wiki/Worms_Armageddon'),
  ('Q1341049', 'Need for Speed: Porsche 2000 est un jeu vidéo de course sorti en 2000, développé en collaboration par Eden Studios avec EA Canada et édité par Electronic Arts. Ce titre qui fait partie de la série des Need for Speed se nomme Need for Speed: Porsche Unleashed en Amérique du Nord, Need for Speed: Porsche 2000 en Europe excepté en Allemagne où il est connu sous le nom de Need for Speed: Porsche comme en Amérique latine.

Ce sont des courses automobiles où les véhicules sont exclusivement des Porsche, il y a exactement 74 modèles différents couvrant la période de 1948 à 2000.', 'https://fr.wikipedia.org/wiki/Need_for_Speed:_Porsche_2000'),
  ('Q1037613', 'Harukanaru toki no naka de est un jeu vidéo de type otome game développé par iNiS et édité par Koei sorti au Japon sur PlayStation en avril 2000. Il a été adapté en shōjo manga de 17 tomes par Tooko Mizuno publié entre les numéros de juillet 2000 et janvier 2010.

Ses personnages principaux sont de style bishōnen, mais Harukanaru comporte aussi beaucoup d''action, de drame, de contexte historique et de magie. Beaucoup le comparent à Fushigi Yūgi et à Les 12 royaumes (Juuni Kokki).

Une adaptation en série télévisée d''animation réalisée par Aki Tsunaki est sortie sous le titre Harukanaru toki no naka de ～Hachiyō Shō～). Elle a été distribuée dans les pays francophones par Anima sous le titre Haruka - La légende des huit guerriers. Des OAV et un film d''animation ont ensuite vu le jour. Finalement, un remake du jeu d''origine est sorti sur PlayStation 2 en avril 2005.', 'https://fr.wikipedia.org/wiki/Harukanaru_toki_no_naka_de'),
  ('Q925269', 'Mortal Kombat 4 (communément abrégé MK4) est un jeu vidéo de combat, quatrième titre de la série Mortal Kombat. C''est le dernier à être sorti sur arcade, en 1997, mais le premier à être en 3D, bien qu''il conserva un gameplay 2D. Il a connu une mise à jour, Mortal Kombat Gold, dont l''histoire remplace celle de MK4.', 'https://fr.wikipedia.org/wiki/Mortal_Kombat_4'),
  ('Q980535', 'Gran Turismo 2 est un jeu vidéo de course automobile développé par Polyphony Digital et édité par Sony Computer Entertainment en 1999 sur PlayStation.

Deuxième épisode de la série Gran Turismo, cet opus se démarque par sa très grande variété de voitures et par l''apparition de constructeurs du monde entier. Le jeu s''est vendu à plus de 9 millions d''exemplaires à travers le monde.', 'https://fr.wikipedia.org/wiki/Gran_Turismo_2'),
  ('Q960773', 'Ape Escape est un jeu vidéo de plates-formes développé par SCE Japan Studio et édité par Sony Computer Entertainment sur PlayStation. C''était le premier jeu à requérir obligatoirement une manette DualShock, ses contrôles étant spécifiquement pensés pour en tirer parti.

Ape Escape a d''abord été publié en Amérique du Nord le 31 mai 1999, et peu de temps après au Japon sous le nom Saru! Get You! le 24 juin 1999. Il est par la suite réédité dans la gamme Platinum.

Ape Escape est le premier épisode de la série de jeux vidéo Ape Escape.', 'https://fr.wikipedia.org/wiki/Ape_Escape_(jeu_vid%C3%A9o)'),
  ('Q942896', 'Spyro 2: Gateway to Glimmer (traduction de l''anglais: passerelle vers Lueur) est un jeu vidéo de plates-formes développé par Insomniac Games et édité par Sony Computer Entertainment sur PlayStation. Il est sorti en Europe en novembre 1999, tout comme en Amérique du Nord, où il est intitulé Spyro 2: Ripto''s Rage!, puis au Japon en mars 2000, sous le nom Spyro X Sparx: Tondemo Tours. Le jeu est republié en 2007 sur le PlayStation Network mais est retiré rapidement de la vente en raison de problèmes audio. Il est ensuite réédité sur les réseaux japonais et américain, en avril 2008 et en mai 2009 respectivement, ainsi que sur le réseau européen en décembre 2012.', 'https://fr.wikipedia.org/wiki/Spyro_2:_Gateway_to_Glimmer'),
  ('Q942008', 'Nazo Makaimura: Incredible Toons est un jeu vidéo de puzzle sorti en 1996 sur Saturn et PlayStation, uniquement au Japon. C''est essentiellement un portage du jeu vidéo de Dynamix connu sous le nom de Sid and Al''s Incredible Toons dans l''univers de Ghosts ''n Goblins.', 'https://fr.wikipedia.org/wiki/Nazo_Makaimura:_Incredible_Toons'),
  ('Q2595747', 'Bushido Blade est un jeu vidéo de combat sorti en 1997 sur PlayStation. Le jeu a été développé par Light Weight et édité par Squaresoft.', 'https://fr.wikipedia.org/wiki/Bushido_Blade'),
  ('Q1064350', 'Oddworld: L''Odyssée d''Abe (Abe''s Oddysee en version originale) est un jeu vidéo sorti le 19 septembre 1997 sur PlayStation et le 31 octobre de la même année sur DOS et Windows. Développé par Oddworld Inhabitants et édité par GT Interactive, c''est le premier jeu de la « pentalogie » Oddworld, qui inclut également L''Exode d''Abe, L''Odyssée de Munch et La Fureur de l''étranger. Ce jeu a reçu plusieurs récompenses. Au Japon, le jeu est sorti sous le nom Abe a GoGo, édité par SoftBank sur PlayStation, le 11 décembre 1997, avant une version PC sortie le 23 février 2001. Le 20 décembre 2010 sort sous le nom de « The Oddboxx » une compilation contenant les deux premiers jeux Oddworld sortis sur PlayStation et PC, ainsi qu''une version pour PC des jeux L''Odyssée de Munch et La Fureur de l''étranger disponible uniquement via la plate-forme de téléchargement Steam.', 'https://fr.wikipedia.org/wiki/Oddworld_:_L%27Odyss%C3%A9e_d%27Abe'),
  ('Q1071378', 'The King of Fighters ''97 est un jeu vidéo de combat développé et édité par SNK sur Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD en 1997 (NGM 232). Il fut porté l''année suivante sur PlayStation et Saturn.

Il s''agit du quatrième épisode de la série The King of Fighters.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_%2797'),
  ('Q1071919', 'The King of Fighters ''99: Millennium Battle est un jeu vidéo de combat développé et édité par SNK sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES et Neo-Geo CD en 1999 (NGM 251).

Il s''agit du sixième épisode de la série The King of Fighters.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_%2799:_Millennium_Battle'),
  ('Q1070953', 'Kurushi (titre original, I.Q.: Intelligent Qube) est un jeu vidéo de réflexion développé par le studio G-Artists et édité par Sony Computer Entertainment en 1997 sur PlayStation.

Le joueur contrôle un personnage sur un plateau composé de cubes, son objectif est de détruire le mur de cubes qui avance vers lui en roulant avec sa capacité de laisser des marques au sol qui détruisent les cubes lors de leur désactivation.', 'https://fr.wikipedia.org/wiki/Kurushi'),
  ('Q2400423', 'ISS Pro Evolution 2 (World Soccer: Jikkyō Winning Eleven 2000 - U23 Medal Heno Chōsen au Japon) est un jeu vidéo de football développé par KCET et édité par Konami en 2000 sur PlayStation.', 'https://fr.wikipedia.org/wiki/ISS_Pro_Evolution_2'),
  ('Q1071034', 'The King of Fighters ''96 est un jeu vidéo de combat développé et édité par SNK sur Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD en 1996 (NGM 214). Il fut réédité sur Saturn, PlayStation, Game Boy, PlayStation 2, PlayStation 3 et PlayStation Portable.

Il s''agit du troisième épisode de la série The King of Fighters.', 'https://fr.wikipedia.org/wiki/The_King_of_Fighters_%2796'),
  ('Q634293', 'Magic Carpet est un jeu de tir à la première personne développé par l''entreprise britannique Bullfrog et sorti sur MS-DOS en 1994.', 'https://fr.wikipedia.org/wiki/Magic_Carpet_(jeu_vid%C3%A9o)'),
  ('Q2386012', 'Oddworld: L''Exode d''Abe (Oddworld: Abe''s Exoddus en version originale) est un jeu vidéo sorti en 1998 sur PlayStation et PC. Développé par Oddworld Inhabitants et édité par GT Interactive, c''est le 2e jeu de la série Oddworld et la suite directe de l''Odyssée d''Abe.

Au Japon, il est sorti sous le nom Abe''99, édité comme son prédécesseur par SoftBank. Un pack contenant les deux premiers jeux Oddworld sortis sur PlayStation et PC, ainsi qu''une version pour PC des jeux L''Odyssée de Munch et La Fureur de l''étranger devrait sortir en 2010 et sera disponible via la plate-forme de téléchargement Steam.', 'https://fr.wikipedia.org/wiki/Oddworld_:_L%27Exode_d%27Abe'),
  ('Q633461', 'FIFA Soccer 96 est un jeu vidéo de football sorti en 1995 sur PlayStation, 32X, DOS, Game Boy, Game Gear, Mega Drive, Saturn et Super Nintendo. Le jeu a été développé par Extended Play Productions et édité par EA Sports.', 'https://fr.wikipedia.org/wiki/FIFA_Soccer_96'),
  ('Q1114989', 'Hi-Octane est un jeu vidéo de course et de combat motorisé développé par Bullfrog Productions et publié par Electronic Arts sur PC en 1995 avant d''être porté sur PlayStation et Sega Saturn sous le nom Hi-Octane: The Track Fights Back!. Le jeu se déroule dans un univers de science-fiction dans lequel le joueur participe à des courses d''aéroglisseur. Il peut pour cela choisir entre six véhicules dotés de caractéristiques différentes en matière de solidité, de vitesse et de puissance de feu. Avec son aéroglisseur, il participe à des courses qui l''oppose à des pilotes contrôlés par l''ordinateur ou par d''autres joueurs. Six circuits, représentés en trois dimensions, sont disponibles dans le jeu. Ils sont parsemés d''armes et de bonus qui permettent au joueur d''améliorer les performances de son véhicule ou d''attaquer ses adversaires pour leur faire perdre du temps. Chaque circuit est également équipé de stands qui permettent de faire le plein de carburant ou de munition et d''effectuer des réparations.', 'https://fr.wikipedia.org/wiki/Hi-Octane'),
  ('Q635706', 'V-Rally est un jeu vidéo de course de rallye développé et publié par Infogrames, sorti en 1997 sur PlayStation. Il s''agit du premier jeu de la série V-Rally.

Le jeu prend pour cadre les saisons du championnat du monde des rallyes 1997. Les joueurs pilotent des voitures de rallye à travers une série de spéciales réparties dans huit pays différents, avec des surfaces diverses telles que le gravier, l''asphalte, la terre et la neige. Plusieurs modes de jeu — Arcade, Championnat, et Contre-la-montre — sont proposés.

Le jeu est développé durant une période de deux ans, à partir de 1995. V-Rally étant un jeu de simulation, il met l''accent sur la reproduction fidèle des comportements physiques des voitures et est plus réaliste que les jeux vidéo d''arcade. L''ancien champion du monde de rallye Ari Vatanen œuvre en tant que consultant technique, conseillant les développeurs quant à la manière dont les voitures doivent réagir aux collisions et aux dérapages.', 'https://fr.wikipedia.org/wiki/V-Rally'),
  ('Q2603276', 'Bugs Bunny: Voyage à travers le temps (en anglais: Bugs Bunny: Lost in Time) est un jeu vidéo de plates-formes, développé par Behaviour Interactive, et édité et distribué par Infogrames. Il est d''abord commercialisé en Europe sur PlayStation en mai 1999, puis en Amérique du Nord le 1er juillet 1999. Le jeu est ensuite publié sur le système Microsoft Windows en Amérique du Nord le 19 octobre 1999, puis le 5 novembre de la même année en Europe.

Le jeu se déroule dans l''univers des Looney Tunes dans lequel le joueur incarne le personnage de Bugs Bunny, qui, en se rendant à Pismo Beach, se trompe d''itinéraire et se retrouve plongé dans un voyage dans le temps en voulant utiliser ce qu''il pensait être un distributeur de jus de carotte. Sur les conseils du sorcier Merlin Munroe, il se met à la recherche de réveils qui vont lui permettre de retourner dans le présent. Dans son périple, Bugs Bunny traverse plusieurs périodes historiques, entre l''âge de pierre, le Moyen Âge, le temps des pirates, les années 1930 et la dimension X, où il rencontre plusieurs autres personnages des Looney Tunes.', 'https://fr.wikipedia.org/wiki/Bugs_Bunny_:_Voyage_%C3%A0_travers_le_temps'),
  ('Q2396172', 'Klonoa Beach Volleyball est un jeu vidéo de sport développé et édité par Namco, sorti en 2002 sur PlayStation. S''il s''agit chronologiquement du quatrième jeu de la série Klonoa, Klonoa Beach Volleyball est en fait un spin-off de celle-ci. L''univers est ici utilisé pour un jeu de beach volley et non pour le genre habituel de la série: le jeu de plates-formes.', 'https://fr.wikipedia.org/wiki/Klonoa_Beach_Volleyball'),
  ('Q2604312', 'Air Combat est un simulateur de vol de combat développé et publié par Namco en 1993 sur borne d''arcade. Il a été adapté en 1994 sur PlayStation. Il est dénommé Ace Combat (エースコンバット (Ēsu Konbatto)) au Japon.

C''est le premier épisode de ce qui devient la série Ace Combat.', 'https://fr.wikipedia.org/wiki/Air_Combat'),
  ('Q622336', 'Resident Evil — ou Bio Hazard au Japon — est un jeu vidéo du genre survival horror développé et édité par Capcom, sorti initialement sur GameCube le 22 mars 2002 au Japon.

Il s''agit d''un remake intégral du premier Resident Evil sorti sur PlayStation en 1996. L’intrigue se déroule en juillet 1998 près de Raccoon City, une ville fictive du Midwest américain, où une série de meurtres étranges a eu lieu. Le joueur incarne au choix Chris Redfield ou Jill Valentine, agents de l’unité d''élite S.T.A.R.S., piégés dans un manoir en pleine forêt après avoir été envoyés par la ville et la police de Raccoon pour enquêter sur ces meurtres.', 'https://fr.wikipedia.org/wiki/Resident_Evil_(jeu_vid%C3%A9o,_2002)'),
  ('Q1065193', 'Salamander 2 est un jeu vidéo de type shoot ''em up développé et édité par la société japonaise Konami en 1996 sur borne d''arcade Konami GX, uniquement au Japon. Le jeu est une suite directe de Salamander, dérivé de la série Gradius.

Le jeu vient de la série Gradius où il intègre des éléments graphiques en trois dimensions dans son univers en 2D. Il conserve tous les éléments caractéristiques de son prédécesseur: possibilité de jouer à deux simultanément, ennemis et boss similaire, et l''inclusion de niveaux à défilement verticaux.', 'https://fr.wikipedia.org/wiki/Salamander_2'),
  ('Q1309459', 'Need for Speed: Conduite en état de liberté est un jeu vidéo de course sorti en 1999, développé par EA Canada et édité par Electronic Arts. Il s''agit du quatrième opus de la série des Need for Speed. La version originale disponible en Amérique du Nord est appelé Need for Speed: High Stakes, au Royaume-Uni elle se nomme Need for Speed: Road Challenge.', 'https://fr.wikipedia.org/wiki/Need_for_Speed_:_Conduite_en_%C3%A9tat_de_libert%C3%A9'),
  ('Q1088780', 'Final Doom est un jeu vidéo du type jeu de tir à la première personne qui utilise le moteur du jeu, les objets et les personnages de Doom II. Il est constitué de deux MegaWads (fichiers de niveaux.wad) contenant 32 niveaux, TNT: Evilution principalement par la Team TNT (en), et The Plutonia Experiment par les frères Milo et Dario Casali. Final Doom est sorti en 1996 et distribué en tant que produit officiel d''id Software. En complément des versions PC et Macintosh, Final Doom est également sorti sur PlayStation; cette version inclut une sélection de niveaux de Final Doom et des Master Levels for Doom II combinés en un seul jeu.', 'https://fr.wikipedia.org/wiki/Final_Doom'),
  ('Q1064176', 'Medal of Honor: Résistance (Medal of Honor: Underground) est un jeu vidéo développé par DreamWorks Interactive et édité par Electronic Arts. Il s’agit d’un jeu de tir à la première personne sorti en 2000 sur PlayStation. Suite de Medal of Honor, il est le second opus de la série Medal of Honor.

En 2003 est sortie une adaptation Game Boy Advance de la version PlayStation, développée par Rebellion et éditée par Destination Software.', 'https://fr.wikipedia.org/wiki/Medal_of_Honor_:_R%C3%A9sistance'),
  ('Q2414280', 'Fighter Maker est un jeu vidéo pour PlayStation et Microsoft Windows, développé par ASCII Corporation et édité par Agetec. Il dispose d''un solide système de création de personnages, allant jusqu''à laisser les joueurs créer des animations. Il existe deux versions de ce jeu, Fighter Maker (série FM) et 2D Fighter Maker (série 2DFM).', 'https://fr.wikipedia.org/wiki/Fighter_Maker'),
  ('Q1088142', 'Chrono Cross est un jeu vidéo de rôle, développé par Square Co., Ltd. (aujourd''hui Square Enix Co., Ltd.), sorti sur PlayStation le 18 novembre 1999 au Japon et le 15 août 2000 en Amérique du Nord.

Une version remastérisée intitulée Chrono Cross: The Radical Dreamers Edition est sortie le 7 avril 2022 sur Microsoft Windows, Nintendo Switch, PlayStation 4 et Xbox One.', 'https://fr.wikipedia.org/wiki/Chrono_Cross'),
  ('Q1072820', 'Metal Slug X (sous-titré Super Vehicle-001) est un jeu vidéo de type run and gun développé et édité par SNK en 1999 sur Neo-Geo MVS, Neo-Geo AES (NGM 250). C''est le troisième épisode de la série Metal Slug.', 'https://fr.wikipedia.org/wiki/Metal_Slug_X'),
  ('Q2397143', 'Loaded est un jeu vidéo de type shoot ''em up pour PlayStation et Saturn. Il est sorti en décembre 1995 en Amérique du Nord et en février 1996 en Europe. Au Japon, le jeu est sorti en mars 1996 et se nomme Blood Factory, traduisible en français par « L''usine de sang ».

Le jeu se déroule dans une prison au fond de l''univers. Le joueur doit choisir un protagoniste parmi six. Il doit exterminer tous les ennemis sur son chemin afin de tuer le directeur, un monstre mutant appelé le FUB.', 'https://fr.wikipedia.org/wiki/Loaded_(jeu_vid%C3%A9o)'),
  ('Q2596087', 'Tobal 2 est un jeu de combat sorti sur PlayStation en 1997. Il fait suite à Tobal n°1 et n''est sorti qu''au Japon. C''est un des rares jeux PlayStation à être en haute résolution.', 'https://fr.wikipedia.org/wiki/Tobal_2'),
  ('Q1111080', 'Colony Wars: Vengeance est un jeu vidéo de combat spatial développé et édité par Psygnosis, sorti en 1998 sur PlayStation. Il fait suite à Colony Wars (1996).', 'https://fr.wikipedia.org/wiki/Colony_Wars:_Vengeance'),
  ('Q635989', 'Dragon Ball Z: The Legend, ou Dragon Ball Z: La Grande Légende des boules de cristal apparaissant sur l''écran titre, est un jeu vidéo de combat par Bandai sur l''univers de Dragon Ball Z. Il est distribué à partir de 1996 uniquement au Japon sur PlayStation, et la même année sur Saturn au Japon mais aussi en France et en Espagne.

Le jeu est publié sur Sega Saturn et sur PlayStation au Japon le 31 mai 1996. Le jeu est également publié en France et en Espagne sous le titre de Dragon Ball Z: The Legend avec des textes traduits en français. L''écran titre de la version française du jeu est traduit en Dragon Ball Z: La Grande légende des boules de cristal.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_The_Legend'),
  ('Q692715', 'X-Men: Children of the Atom est un jeu vidéo de combat développé et édité par Capcom sur CP System II en décembre 1994. Il a été porté sur console et sur ordinateur à partir de 1995. Le jeu a été produit sous licence Marvel Entertainment Group.', 'https://fr.wikipedia.org/wiki/X-Men:_Children_of_the_Atom'),
  ('Q2367032', 'Twisted Metal 2 (sous-titré World Tour en Europe) est un jeu vidéo de combat motorisé développé par le studio SingleTrac et publié par Sony en 1996 sur PlayStation et sur PC. Il fait suite à Twisted Metal.

La version PC de Twisted Metal 2 possède des graphismes légèrement inférieurs à ceux de la version PlayStation (certains détails des décors n''apparaissent pas), mais en contrepartie, elle ne nécessite pas de carte graphique 3D, et peut donc tourner sur des ordinateurs peu puissants. Elle permet également de jouer en ligne si l''ordinateur dispose d''une connexion Internet.

Deux ans après sa sortie, Twisted Metal 2 a été réédité sur PlayStation dans la série Greatest Hits. Depuis le 1er novembre 2007, il est disponible en téléchargement en Amérique du Nord via le PlayStation Network.', 'https://fr.wikipedia.org/wiki/Twisted_Metal_2'),
  ('Q966207', 'XCOM: Terror from the Deep, souvent abrégé TFTD, est un jeu vidéo de tactique au tour par tour développé par MicroProse, qui publie ensuite le titre sur PC en 1995, puis sur console PlayStation en 1996.

Cette suite de UFO: Enemy Unknown (aussi dénommé X-COM: UFO Defense) reprend le gameplay de son prédécesseur, pour n''en différer que par l''habillage et la difficulté; toujours aux commandes de l''organisation X-COM (eXtraterrestrial COMbat unit), le joueur doit désormais défendre la Terre contre des extraterrestres qui émergent des océans où ils avaient été cryogénisés.', 'https://fr.wikipedia.org/wiki/X-COM:_Terror_from_the_Deep'),
  ('Q1421439', 'Bust a Groove est un mélange entre un jeu de rythme et un jeu de combat développé par Metro Corporation et édité par Enix, désormais connu sous le nom de Square Enix. Il sort au Japon en 1998 sur PlayStation, est distribué par 989 Studios aux États-Unis et SCEE en Europe. Il est désormais disponible sur le PlayStation Store.

Le jeu est plus connu au Japon sous le nom de Bust a Move: Dance & Rhythm Action mais il est renommé par 989 Studios Bust-a-Groove car une série de puzzle games japonaise, Puzzle Bobble était déjà connu sous le nom de Bust a Move en Amérique.

Le jeu a eu une suite, Bust a Groove 2, qui ne fut jamais distribué en Europe. La série est actuellement terminée avec le jeu Dance Summit 2001: Bust a Groove, sur PlayStation 2, édité uniquement pour les japonais.', 'https://fr.wikipedia.org/wiki/Bust_a_Groove'),
  ('Q2382341', '3×3 Eyes: Kyuusei Koushu est un jeu vidéo d''action-aventure sorti en 1995 sous Windows, sur PlayStation et Saturn.', 'https://fr.wikipedia.org/wiki/3%C3%973_Eyes:_Ky%C5%ABsei_K%C5%8Dshu'),
  ('Q680816', 'Worms World Party est un jeu vidéo d''artillerie appartenant à la série Worms. Il se joue en tour par tour et son univers est réalisé en 2 dimensions. Il est édité par Team17.', 'https://fr.wikipedia.org/wiki/Worms_World_Party'),
  ('Q668568', 'Tomb Raider: La Révélation finale (Tomb Raider: The Last Revelation) est un jeu vidéo d''action-aventure développé par Core Design et édité par Eidos Interactive en 1999 sur PlayStation et Windows, et en 2000 sur Dreamcast. C''est le 4e épisode de la série Tomb Raider.

En raison de la tension du développement de titres Tomb Raider sans arrêt depuis la sortie du premier jeu en 1996, et de la fatigue générale avec le personnage de Lara Croft, le personnel de Core Design a écrit le récit pour se terminer par la mort de Lara. Mais malgré la mort du personnage, l’éditeur Eidos Interactive et Jeremy Heath-Smith a quand même poussera Core Design à développer deux autres jeux: Tomb Raider Chronicles (sous forme de flashbacks) et Tomb Raider: L''Ange des ténèbres (pour la PS2).', 'https://fr.wikipedia.org/wiki/Tomb_Raider_:_La_R%C3%A9v%C3%A9lation_finale'),
  ('Q2374347', 'Legend of Legaia est un jeu vidéo de rôle développé par Contrail et édité par Sony Computer Entertainment sur PlayStation. Il est sorti en 1998 au Japon, en 1999 aux États-Unis et en 2000 en Europe. Il a connu une suite en 2002 sur PlayStation 2 portant le nom Legaia 2: Duel Saga.', 'https://fr.wikipedia.org/wiki/Legend_of_Legaia'),
  ('Q970101', 'Soccer Kid est un jeu vidéo de plate-forme développé par Krisalis Software et sorti sur Amiga 500, Amiga 1200 et Super Nintendo en 1993. Le jeu a été porté sur 3DO, Amiga CD32, DOS et Jaguar.', 'https://fr.wikipedia.org/wiki/Soccer_Kid'),
  ('Q964295', 'Sexy Parodius est un jeu vidéo de type shoot ''em up développé et édité par Konami en 1996 sur borne d''arcade Konami GX. C''est le cinquième volet de la série Parodius. Comme le reste de la série, il s’agit d’une parodie de la série Gradius et d’autres jeux Konami.', 'https://fr.wikipedia.org/wiki/Sexy_Parodius'),
  ('Q963231', 'Nobunaga no Yabō: Bushō Fūunroku, aussi appelé Nobunaga''s Ambition 3: The Rising of Sun, est un jeu vidéo de grande stratégie développé et édité par Koei, sorti en 1990 sur PC-98. Il a été adapté sur DOS, FM Towns, Mega Drive, MSX2, NES, PC-88, PC Engine, PlayStation, Super Nintendo et X68000.

Le jeu fait partie de la série Nobunaga''s Ambition.', 'https://fr.wikipedia.org/wiki/Nobunaga_no_Yab%C5%8D:_Bush%C5%8D_F%C5%ABunroku'),
  ('Q964374', 'WWF SmackDown! 2: Know Your Role (Exciting Pro Wrestling 2 au Japon) est un jeu vidéo de catch professionnel de la WWE développé par THQ et par YUKE''s Future Media Creators. Ce jeu fait partie de la série des WWF SmackDown!. Il est commercialisé sur PlayStation le 21 novembre 2000 aux États-Unis et le 1er janvier 2001 en Europe.', 'https://fr.wikipedia.org/wiki/WWF_SmackDown!_2:_Know_Your_Role'),
  ('Q639840', 'Beast Wars: Transformers est un jeu vidéo de tir à la troisième personne développé par SCE Cambridge Studio et édité par Hasbro Interactive, sorti en 1997 sur Windows, Mac et PlayStation.

Il est basé sur la série animée Animutants.', 'https://fr.wikipedia.org/wiki/Beast_Wars:_Transformers_(jeu_vid%C3%A9o)'),
  ('Q692320', 'Syphon Filter 3 est un jeu vidéo de Tir à la troisième personne et d''infiltration développé par SCE Bend Studio et édité par Sony Computer Entertainment en 2001 sur la console PlayStation de Sony. Syphon Filter 3 est le troisième épisode de la série du même nom.', 'https://fr.wikipedia.org/wiki/Syphon_Filter_3'),
  ('Q1418354', 'Soul Edge, également appelé Soul Blade (le nom fut transformé en Soul Blade en Occident lors du portage sur PlayStation), est un jeu vidéo de combat développé et édité par Namco en 1995 sur borne d''arcade. Une version améliorée appelée Soul Edge Ver. II est sortie en 1996 et adaptée sur PlayStation.

Soul Edge est le premier épisode de la série Soul, qui prendra le nom SoulCalibur à partir du deuxième épisode en 1998.

Il s''agit du second jeu de combat en 3D — après Battle Arena Toshinden — à proposer des affrontements à l''arme blanche. Si l''utilisation de ce type d''arme dans un jeu de combat n''était pas une nouveauté (voir la série 2D Samurai Shodown), le gameplay de Soul Edge offre un large éventail de style de combats.', 'https://fr.wikipedia.org/wiki/Soul_Edge'),
  ('Q2424706', 'Kitty the Kool est un jeu développé et édité par Imagineer, sorti le 26 novembre 1998 sur PlayStation et qui reprend le principe de PaRappa the Rapper (comme de nombreux jeux de musique).', 'https://fr.wikipedia.org/wiki/Kitty_the_Kool'),
  ('Q1413485', 'Tactics Ogre: Let Us Cling Together est un tactical RPG développé par Quest et sorti en 1995 sur Super Nintendo puis porté sur PlayStation, Saturn et console virtuelle de la Wii. Il est aujourd''hui reconnu comme le 7e jeu vidéo préféré des lecteurs du célèbre magazine de jeux vidéo Famitsu en 2006.

En 2010, Square Enix réédite le jeu sur la PlayStation Portable de Sony, en introduisant de nombreuses nouveautés.

Comme sur le premier volet du jeu (ogre battle) le nom est tiré d''une chanson de Queen présente sur le 5ème album, A Day At The Races', 'https://fr.wikipedia.org/wiki/Tactics_Ogre:_Let_Us_Cling_Together'),
  ('Q1411913', 'Fighting Force (Fighting Force 64 sur Nintendo 64) est un jeu vidéo beat ''em up sorti en 1997 sur Windows, PlayStation et en 1999 sur Nintendo 64. Le jeu a été développé par Core Design puis édité par Eidos Interactive.

Il a également été adapté sur borne d''arcade.

Le jeu a eu une suite, Fighting Force 2, sorti sur PlayStation et Dreamcast.', 'https://fr.wikipedia.org/wiki/Fighting_Force'),
  ('Q2420170', 'FIFA Football 2001 est un jeu vidéo de football sorti en 2000 pour les plateformes PlayStation, PlayStation 2 et Windows. Le jeu a été édité par EA Sports.

Ce jeu avait comme thème principal « Bodyrock » de Moby. Fifa 2001 a fait partie des jeux officiels aux World Cyber Games 2001, qui a accueilli 3 joueurs de la délégation française de Fifa. Le jeu comporte 50 équipes et 17 ligues de football. Le joueur français Thierry Henry figure sur la jaquette française du jeu.', 'https://fr.wikipedia.org/wiki/FIFA_Football_2001'),
  ('Q661880', 'Colony Wars est un jeu vidéo de combat spatial développé et édité par Psygnosis en novembre 1997 sur PlayStation. Le but du jeu est de remplir des missions variées aux commandes d''un vaisseau spatial. Colony Wars fut, à sa sortie, mis en concurrence avec G-Police (bien que les deux jeux soient du même éditeur). Ce dernier bénéficiant de moins bonnes critiques, il se vendit malgré tout mieux que Colony Wars.', 'https://fr.wikipedia.org/wiki/Colony_Wars_(jeu_vid%C3%A9o)'),
  ('Q651591', 'Transport Tycoon est un jeu vidéo de simulation créé par Chris Sawyer et édité par Microprose en 1994.

Le jeu propose de prendre la direction d''une société de transport devant concurrencer les sociétés rivales pour faire autant de bénéfices que possible, en livrant diverses marchandises par transports ferroviaire, routier, maritime et aérien.

Une mise à jour, Transport Tycoon Deluxe, est sortie en 1995, puis TTDPatch, développé indépendamment, est paru à partir de 1999, qui ont encore amélioré le jeu. Depuis, une autre version est apparue: OpenTTD pour Open Transport Tycoon Deluxe, une version open source reprenant les meilleures fonctions de TTD et en y ajoutant constamment des nouveautés.', 'https://fr.wikipedia.org/wiki/Transport_Tycoon'),
  ('Q2420155', 'FIFA 99 est un jeu vidéo de football sorti le 20 novembre 1998 sur PlayStation, Windows et Nintendo 64. Le jeu a été développé par Software Creations et édité par EA Sports.

Le jeu fait partie de la série FIFA Football.', 'https://fr.wikipedia.org/wiki/FIFA_99'),
  ('Q2420183', 'FIFA Football 2002 est un jeu vidéo de football sorti en 2001 pour les plateformes PlayStation, PlayStation 2, Windows et GameCube. Le jeu a été édité par EA Sports.

Thierry Henry figure sur les jaquettes des éditions américaine, anglaise et française du jeu. Il apparaît sur la jaquette française pour la deuxième année consécutive.', 'https://fr.wikipedia.org/wiki/FIFA_Football_2002'),
  ('Q642359', 'Tomb Raider: Sur les traces de Lara Croft (Tomb Raider Chronicles) est un jeu vidéo d''action-aventure développé par Core Design et édité par Eidos Interactive en 2000. Il constitue le 5e volet de la série vidéoludique Tomb Raider. Il s''agit d''un épisode hiatus sous forme de flashbacks entre le quatrième et le sixième opus de la série. À noter que chaque chronique rappelle un épisode précédent de la série.

Malgré la mort prévue de Lara Croft dans La Révélation finale, Eidos a dit à Core Design de continuer la série; alors qu''une nouvelle équipe a commencé à travailler sur L''Ange des ténèbres pour la PlayStation 2, une équipe de vétérans a développé le cinquième jeu basés sur des concepts tirés du précédent opus. Ce devait être le dernier Tomb Raider construit sur le moteur original, l''équipe ayant peu d''enthousiasme pour le projet.', 'https://fr.wikipedia.org/wiki/Tomb_Raider_:_Sur_les_traces_de_Lara_Croft'),
  ('Q2426211', 'Brave Fencer Musashi est un jeu vidéo de rôle orienté action développé et édité par Squaresoft. Il est distribué en 1998 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Brave_Fencer_Musashi'),
  ('Q649422', 'Caesars Palace est un jeu vidéo arcade de combat sorti en 1993 et fonctionne sur PC, PlayStation Networld, Dream Gear, SNES, Sega Mega Drive, Super Nintendo Entertainment System Arcade et Super Nintendo. Le jeu a été édité par Virgine Games Arcade.', 'https://fr.wikipedia.org/wiki/Caesars_Palace_(jeu_vid%C3%A9o)'),
  ('Q660034', 'Carmageddon II: Carpocalypse Now est un jeu vidéo de combat motorisé développé par Stainless Games et édité par Sales Curve Interactive, sorti en 1998 sur Windows et Mac OS. La musique utilise des chansons de heavy metal d''Iron Maiden et Sentience.', 'https://fr.wikipedia.org/wiki/Carmageddon_II:_Carpocalypse_Now'),
  ('Q2422795', 'Street Fighter Alpha 2, connu au Japon sous le nom Street Fighter Zero 2, est un jeu vidéo de combat en un contre un développé et édité par Capcom sur CP System II en mars 1996. Il s''agit de la suite de Street Fighter Alpha: Warriors'' Dreams, suite qui inclut de nouveaux personnages et un nouveau système de combos dénommé Custom Combos. Le jeu a été adapté sur plusieurs supports console (parmi lesquelles la Super Nintendo) et ordinateur. Une réédition du jeu nommée Street Fighter Alpha 2 Gold fut publiée sur arcade mais aussi sur Playstation, Saturn et Playstation 2 la même année.', 'https://fr.wikipedia.org/wiki/Street_Fighter_Alpha_2'),
  ('Q665393', 'Langrisser II est un jeu vidéo de type tactical RPG sorti en 1994 sur Mega Drive. Le jeu a été développé par Masaya et édité par NCS.', 'https://fr.wikipedia.org/wiki/Langrisser_II'),
  ('Q1318068', 'WWF Wrestlemania: The Arcade Game (simplement nommé WWF WrestleMania pour les versions consoles) est un jeu vidéo de catch professionnel, développé par Midway Games et édité par Acclaim Entertainment, basé sur l''univers de la World Wrestling Federation (WWF). Il est initialement commercialisé en 1995 sur borne d''arcade puis adapté sur de nombreux autres supports.

Huit personnages sont jouables et les graphismes du jeu ont été inspirés de la série des jeux vidéo Mortal Kombat développée par Midway. Les commentaires sont de Vince McMahon et de Jerry Lawler, qui apparaissent à la table des commentateurs à droite du ring.', 'https://fr.wikipedia.org/wiki/WWF_WrestleMania:_The_Arcade_Game'),
  ('Q1314509', 'To Heart est un jeu vidéo de type visual novel pour adultes développé par Leaf et édité par Aquaplus, sorti en 1997 sur Windows. To Heart est le troisième volume de la série Leaf Visual Novel Series. Un portage contenant quelques bonus par rapport à la version d''origine a vu le jour sur PlayStation en 1999. Toutes les scènes au contenu érotique ont été supprimées. Une seconde version Windows, basée sur le portage PlayStation a ensuite été commercialisée. De nombreux produits dérivés ont vu le jour, notamment un manga, un anime et un Drama CD.

Il est doté d''une suite nommée To Heart 2.', 'https://fr.wikipedia.org/wiki/To_Heart'),
  ('Q2425269', 'Libero Grande est un jeu vidéo de football développé et édité par Namco, sorti en arcade en 1997, puis sur PlayStation en 1998. Dans ce jeu, contrairement à la plupart des autres titres du genre, on ne dirige qu''un seul joueur pendant le match.', 'https://fr.wikipedia.org/wiki/Libero_Grande'),
  ('Q1313999', 'FIFA Football 2004 est un jeu vidéo de football sorti en 2003 pour les plateformes PlayStation, PlayStation 2, Xbox, Windows, GameCube, Game Boy Advance et N-Gage.

Le jeu a été édité par EA Sports. C''est le douzième volet de la série FIFA Football.

L''italien Alessandro Del Piero, le français Thierry Henry et le brésilien Ronaldinho sont apparus dans la jaquette du jeu.', 'https://fr.wikipedia.org/wiki/FIFA_Football_2004'),
  ('Q2418753', 'Formula 1, également appelé Formula One, est un jeu vidéo de course de Formule 1 développé par Bizarre Creations et édité par Psygnosis sur PlayStation et Windows. Premier opus de la série Formula One, il est sorti sur console de salon en septembre 1996 en Europe et en Amérique du Nord, et en décembre 1996 au Japon, avant d''être réédité en 1997 en Europe dans la gamme Platinum, puis en 1998 aux États-Unis dans la gamme Greatest Hits. Le jeu est sorti sur PC en juin 1997.

Le jeu met en scène les écuries et les circuits du championnat du monde de Formule 1 1995 dans divers modes de jeu, dont l''arcade et le championnat, permettant au joueur d''affronter les pilotes de la saison 1995 ou de s''adonner au multijoueur, sur PlayStation seulement, en utilisant un câble link. Formula 1 inclut des commentaires dits par Philippe Alliot pour la version en français, Murray Walker pour la version en anglais et des morceaux tirés du répertoire des guitaristes américains Joe Satriani et Steve Vai.', 'https://fr.wikipedia.org/wiki/Formula_1_(jeu_vid%C3%A9o)'),
  ('Q1340462', 'PaRappa the Rapper est un jeu de rythme développé par NanaOn-Sha et édité par Sony Computer Entertainment en 1996 sur PlayStation. Il a été adapté sur PSP en 2006, puis en 2017 sur PlayStation 4, dans une version remastérisée.', 'https://fr.wikipedia.org/wiki/PaRappa_the_Rapper'),
  ('Q645418', 'Donald Duck Couak Attack, stylisé Donald Duck: Cou@k Att@ck ?*!, également intitulé Donald Duck: Goin'' Qu@ckers en Amérique du Nord, est un jeu vidéo de plates-formes développé par Ubisoft Montréal et Disney Interactive, publié par Ubi Soft Entertainment, originellement publié en 2000 sur PC ainsi que sur consoles Dreamcast, Nintendo 64, PlayStation, et Game Boy. Le jeu est réédité et publié en 2002 sur consoles PlayStation 2 et GameCube.', 'https://fr.wikipedia.org/wiki/Donald_Duck_Couak_Attack'),
  ('Q1415970', 'Final Fantasy est un jeu vidéo de rôle développé et publié par Square Co., Ltd. pour la Nintendo Entertainment System (NES) en 1987. Il est le jeu inaugural de la série principale de Square: Final Fantasy.

Final Fantasy a été plus tard réédité sur plusieurs consoles de jeu vidéo, y compris les ordinateurs MSX 2, la PlayStation et les consoles portables Wonderswan Color, Game Boy Advance et PSP. Deux versions produites pour les téléphones mobiles japonais ont aussi vu le jour sur les modèles NTT DoCoMo FOMA 900i (sous le nom Final Fantasy i ou FFI) et CDMA 1X WIN-compatible W21x de KDDI Corporation (sous le nom Final Fantasy EZ) dans les années 2000. Le jeu a été fréquemment compilé avec sa suite, Final Fantasy II. Pour de plus amples informations à propos des compilations PlayStation et Game Boy Advance, voir respectivement Final Fantasy Origins et Final Fantasy I and II: Dawn of Souls.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_(jeu_vid%C3%A9o)'),
  ('Q21116758', 'Gallop Racer 3 est un jeu vidéo de sport développé et édité par Tecmo sur borne d''arcade en 1999. Il est porté sur PlayStation.', 'https://fr.wikipedia.org/wiki/Gallop_Racer_3'),
  ('Q2636173', 'South Park (intitulé South Park: Deeply Impacted durant son développement) est un jeu vidéo de tir à la première personne édité et distribué par Acclaim, initialement commercialisé aux États-Unis sur console Nintendo 64 le 21 décembre 1998 puis adapté et commercialisé sur systèmes Microsoft Windows le 9 mars 1999 et sur PlayStation le 30 septembre 1999. Une adaptation sur Game Boy Color est en phase de développement dès 1998 mais par la suite annulé par les créateurs de la série Matt Stone et Trey Parker car ils considéraient que le jeu ne pourrait être idéalement retranscrit sur cette console portable.', 'https://fr.wikipedia.org/wiki/South_Park_(jeu_vid%C3%A9o)'),
  ('Q2264782', 'Tony Hawk''s Skateboarding (Tony Hawk''s Pro Skater aux États-Unis, parfois abrégé THPS) est un jeu vidéo de simulation de skateboard développé par Neversoft et édité par Activision à partir de septembre 1999 sur PlayStation. Le jeu est porté l''année suivante sur Nintendo 64, Game Boy Color, Dreamcast, puis en 2003 sur N-Gage.

Tony Hawk''s Skateboarding permet au joueur de jouer au skateboard dans un univers urbain recréé en 3D et une ambiance rock et hip-hop. Le joueur incarne divers skaters célèbres et doit réaliser des figures de skate (slide, grab) ou des missions comme des collectes d''objets. Le jeu propose plusieurs modes de jeu dont un mode carrière, un mode libre, un mode de session simple, un mode multijoueur. Le mode carrière permet de faire évoluer les capacités des personnages ou leur matériel. Chaque niveau propose différents objectifs à effectuer comme la réalisation de défis, de figures de skate particulières, l''obtention du meilleur score, ou la collecte d''items disséminés dans les niveaux. Les niveaux peuvent être urbains ou de type compétition dans des skateparks. Le mode multijoueur permet plusieurs jeux comme le Graffiti, le Trick Attack ou le Horse. Les portages sont globalement très fidèles, sauf la version Game Boy Color qui propose deux types de gameplay sensiblement différents.', 'https://fr.wikipedia.org/wiki/Tony_Hawk%27s_Skateboarding'),
  ('Q2236540', 'Tecmo Bowl est une série de jeux vidéo de football américain éditée par Tecmo entre 1987 et 1995. La série, qui comprend quatre épisodes, bénéficie de la licence officielle de la National Football League.

L''épisode original, Tecmo Bowl, est sorti en 1987 sur borne d''arcade et a été adapté sur Nintendo Entertainment System (1989) et Game Boy (1991). Le second opus, Tecmo Super Bowl, est sorti en 1991 sur NES et en 1993 sur Mega Drive et Super Nintendo dans une version remise à jour. Le troisième et le quatrième opus, Tecmo Super Bowl II: Special Edition et Tecmo Super Bowl III: Final Edition, sont sortis en 1994 et 1995 sur Mega Drive et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Tecmo_Bowl'),
  ('Q20732394', 'Echo Night 2: The Lord of Nightmares est un jeu vidéo d''aventure à la première personne développé et édité par FromSoftware, sorti en 1999 sur PlayStation, uniquement au Japon. Bien qu''il s''agisse du deuxième épisode de sa série et qu''il partage certains éléments avec son prédécesseur, il se déroule dans son propre univers.

Il est rendu disponible sur le PlayStation Network en 2007. Une fan-traduction en anglais existe également depuis 2015.', 'https://fr.wikipedia.org/wiki/Echo_Night_2:_The_Lord_of_Nightmares'),
  ('Q2608244', 'X-Men vs. Street Fighter est un jeu de combat développé et édité par Capcom en septembre 1996 sur CP System II. Il s''agit du troisième jeu de Capcom à présenter des personnages provenant de l''univers Marvel Comics, juste après X-Men: Children of the Atom et Marvel Super Heroes. Le titre est d''abord publié sur borne d''arcade via le système CP System II en 1996, puis porté en 1997 sur Sega Saturn et en 1998 sur PlayStation.', 'https://fr.wikipedia.org/wiki/X-Men_vs._Street_Fighter'),
  ('Q2265002', 'Riven (ou Riven, la suite de Myst en version longue, Riven: the sequel to Myst en version originale) est un jeu vidéo d''aventure de point & click à la première personne sorti le 29 octobre 1997 sur Macintosh et PC, développé par Cyan Worlds, Inc. et publié par Ubisoft. Par la suite, il a connu des portages sur PlayStation (1997-1998), Saturn (1998), Pocket PC (2005) et iOS (2010) et est édité par Red Orb Entertainment, Acclaim Entertainment, Sega ou Mean Hamster Software. Il s''agit de la suite du célèbre jeu vidéo Myst créé par Rand et Robyn Miller.

L''histoire de Riven prend place directement après les évènements de Myst. Atrus, le personnage central de la série, demande de l''aide à l’Étranger, le mystérieux personnage incarné par le joueur, pour libérer Catherine, sa femme, des mains de Gehn, son père rendu fou par l''avidité et le pouvoir. Atrus envoie donc l’Étranger dans le monde de Riven, un des multiples « Âges » créés par la civilisation D''ni. Comme pour son prédécesseur, le jeu comporte plusieurs fins en fonction des choix et des actes du joueur, mais contrairement à Myst, où l''aventure se déroulait dans plusieurs âges, Riven se déroule presque totalement dans le même monde.', 'https://fr.wikipedia.org/wiki/Riven'),
  ('Q20963376', 'Street Skater 2 (Street Sk8er 2) est un jeu vidéo de simulation de skateboard, développé par Atelier Double et édité par Electronic Arts, sorti en 2000 sur PlayStation, PC (Windows), PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Street_Skater_2'),
  ('Q21535234', 'Lone Soldier est un jeu de tir à la troisième personne sorti en 1995 sur PlayStation.

Le jeu est sorti en janvier 1996 en Europe et le 4 octobre 1996 au Japon.

Le jeu présente un seul personnage principal jouable, un soldat solitaire armé de diverses armes, dans le but de tuer les forces ennemies pour progresser, pour finalement vaincre les chefs terroristes et une armée extraterrestre intergalactique. Le jeu a une vue à la troisième personne, le joueur se battant dans des décors de guerre traditionnels tels que la jungle, le canyon et la ville, ainsi que dans un environnement spatial plus futuriste.', 'https://fr.wikipedia.org/wiki/Lone_Soldier'),
  ('Q1444699', 'Descent II est un jeu vidéo de tir à la première personne développé par Parallax Software et édité par Interplay Productions sorti en 1996 sur MS-DOS, PlayStation et Mac OS.', 'https://fr.wikipedia.org/wiki/Descent_II'),
  ('Q719176', 'Crash Bandicoot est un jeu vidéo de plates-formes développé par Naughty Dog et édité par Sony Computer Entertainment en 1996 sur PlayStation. Il constitue le premier épisode de la série Crash Bandicoot.

Crash Bandicoot relate la création de l''anthropomorphe Crash Bandicoot, le héros éponyme du jeu, par le Docteur Neo Cortex et le Docteur Nitrus Brio, les deux antagonistes principaux du jeu. L''histoire suit ensuite les aventures de Crash qui a pour missions d''arrêter ses deux créateurs dans leur quête de domination du monde, de nettoyer toute la pollution qu''ils ont causée et de sauver sa petite amie, Tawna, une femelle bandicoot également créée par les Docteurs Cortex et Nitrus Brio.', 'https://fr.wikipedia.org/wiki/Crash_Bandicoot_(jeu_vid%C3%A9o)'),
  ('Q2243689', 'Jikkyō Oshaberi Parodius est un jeu vidéo de type shoot ''em up développé et édité par Konami en 1995 sur Super Famicom. Il s''agit d''une transposition du concept de Gradius et d''autres jeux de tir dans un univers décalé et parodique.', 'https://fr.wikipedia.org/wiki/Jikky%C5%8D_Oshaberi_Parodius'),
  ('Q2626555', 'Guilty Gear est un jeu vidéo de combat développé par Arc System Works, édité par Arc System Works et sorti le 14 mai 1998 au Japon. Il est le premier épisode de la série des Guilty Gear.', 'https://fr.wikipedia.org/wiki/Guilty_Gear_(jeu_vid%C3%A9o)'),
  ('Q2660493', 'SaGa Frontier 2 est un jeu vidéo de rôle sur PlayStation développé par Square. Il fait partie de la série de jeux nommée SaGa. D''abord sorti au Japon en avril 1999, une version anglaise est rendue disponible en Amérique du Nord en janvier 2000; les autres versions (européennes, australiennes, etc.) suivent en mars de la même année.', 'https://fr.wikipedia.org/wiki/SaGa_Frontier_2'),
  ('Q2660498', 'SaGa Frontier est un jeu vidéo de rôle sur PlayStation développé par Square sorti au Japon en juillet 1997 et aux États-Unis en mars 1998. Il est le septième épisode de la série de jeux SaGa, le premier sur Playstation, et remporte lui aussi un grand succès, se vendant à 1,08 million d''exemplaires au Japon.', 'https://fr.wikipedia.org/wiki/SaGa_Frontier'),
  ('Q2642660', 'Aladdin: La Revanche de Nasira, originellement intitulé Disney''s Aladdin in Nasira''s Revenge, est un jeu vidéo d''action, publié en 2000 sur console PlayStation, en Amérique du Nord, par Disney Interactive, Inc.. Le jeu est distribué le 13 décembre 2000 en France. Le jeu est réédité en version platinum le 14 mars 2001.', 'https://fr.wikipedia.org/wiki/Aladdin_:_La_Revanche_de_Nasira'),
  ('Q2655866', 'WWF SmackDown! (Exciting Pro Wrestling au Japon) est un jeu vidéo de catch sorti sur PlayStation par THQ et développé par YUKE''s Future Media Creators. Il fait partie de la série des WWF SmackDown! basé sur la fédération de la World Wrestling Federation (WWF). Ce jeu était suivi par WWF SmackDown! 2: Know Your Role.

SmackDown! était le premier jeu de la WWF sur PlayStation à être publié par THQ, qui prenait la place de l''ancien éditeur Acclaim.', 'https://fr.wikipedia.org/wiki/WWF_SmackDown!'),
  ('Q2632560', 'Policenauts est un jeu vidéo d''aventure conçu par Hideo Kojima, développé et édité par Konami, sorti en 1994 sur NEC PC-98. Le jeu est adapté sur 3DO en 1995 et sur PlayStation et Saturn en 1996.', 'https://fr.wikipedia.org/wiki/Policenauts'),
  ('Q1442177', 'Rainbow Six: Rogue Spear est le deuxième jeu de la série Rainbow Six basé sur l''œuvre de Tom Clancy. Le jeu a été développé et édité par Red Storm Entertainment. Il est sorti sous plate-forme Windows le 15 septembre 1999, puis sous Mac OS et Dreamcast en 2000, ainsi que sur PlayStation en 2001 et Game Boy Advance en 2002. Un port sur la PlayStation 2 fut annoncé puis annulé.

Ce jeu est basé sur le même moteur que le Rainbow Six original, avec un gameplay et une présentation similaire. On retrouve l''unité antiterroriste Rainbow dans un environnement qui privilégie le réalisme, la mise en place de plans d''action, la stratégie et le travail en équipe.', 'https://fr.wikipedia.org/wiki/Tom_Clancy%27s_Rainbow_Six:_Rogue_Spear'),
  ('Q2630066', 'Colin McRae Rally 2.0 est un jeu vidéo de rallye automobile développé et édité par Codemasters, sorti en 2000 sur PlayStation et Windows. Une version Game Boy Advance adaptée est sortie en 2002. C''est la suite de Colin McRae Rally (1998).

Colin McRae Rally 2.0 est aussi le nom du portage du jeu sur Game Boy Advance. Il est issu d''une collaboration entre Ubisoft et Codemasters et est sorti en 2002.

Une version Dreamcast a été en développement mais fut annulé à cause de ventes décevantes du jeu.', 'https://fr.wikipedia.org/wiki/Colin_McRae_Rally_2.0'),
  ('Q1446951', 'Test Drive 4 est un jeu vidéo de course automobile développé par Pitbull Syndicate et édité par Accolade en 1997. Le jeu est sorti sur PC et PlayStation. Il est le quatrième jeu de la série Test Drive, dont la première production est sortie en 1987.', 'https://fr.wikipedia.org/wiki/Test_Drive_4'),
  ('Q2625274', 'Dracula: Résurrection est un jeu d''aventure développé par Index+ et édité par DreamCatcher Interactive pour PC et Mac en 1999. En 2001, le jeu est remasterisé pour Playstation. En 2011, il est réadapté sous la forme d’une trilogie à destination des supports iOS par Tetraedge Games et Microïds. Dans Dracula: Résurrection, le joueur contrôle Jonathan Harker, parti à la recherche de Mina en Transylvanie, sur les traces du comte Dracula. Le jeu se présente sous la forme d''un point and click en vue à la première personne, et est classé Tous publics (+12 lors de la sortie du collector Dracula 1 & 2).', 'https://fr.wikipedia.org/wiki/Dracula_:_R%C3%A9surrection'),
  ('Q1440402', 'Urban Chaos est un jeu d''action-aventure développé par Mucky Foot et édité par Eidos Interactive. Sorti le 3 décembre 1999, c''est un jeu de tir à la troisième personne (ou third person shooter).', 'https://fr.wikipedia.org/wiki/Urban_Chaos'),
  ('Q719960', 'Harry Potter à l''école des sorciers est un jeu vidéo sorti sur plusieurs plateformes entre 2001 et 2003: GameCube, PlayStation, PlayStation 2, Game Boy Advance, Game Boy Color, Xbox et Windows. Le jeu est basé sur l''intrigue du premier roman de la série Harry Potter écrite par J. K. Rowling: Harry Potter à l''école des sorciers, et suit la trame du film adapté de ce roman.', 'https://fr.wikipedia.org/wiki/Harry_Potter_%C3%A0_l%27%C3%A9cole_des_sorciers_(jeu_vid%C3%A9o)'),
  ('Q716452', 'International Track and Field est une mise à jour 3D de la série de jeux vidéo Track and Field de Konami, dans laquelle jusqu''à quatre joueurs s''affrontent dans onze épreuves olympiques différentes. Le jeu a été publié pour la PlayStation et les arcades en 1996. La version arcade est sorti uniquement au Japon sous le nom de Hyper Athlete. En 2008, le jeu est sorti sur le PlayStation Network.', 'https://fr.wikipedia.org/wiki/International_Track_and_Field'),
  ('Q1463730', 'Tony Hawk''s Pro Skater 3 (également Tony Hawk''s 3 ou THPS3) est un jeu vidéo de skateboard développé par Neversoft et édité par Activision sur PlayStation 2 en 2001 et porté entre 2001 et 2002 sur GameCube, Game Boy Color, PlayStation, Nintendo 64, Xbox, PC et Game Boy Advance. C''est le troisième jeu de la série Tony Hawk''s. C''est le dernier jeu produit pour la Nintendo 64 en Amérique du Nord. C''est le premier jeu qui supportait une connexion Internet pour le jeu en ligne sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_3'),
  ('Q2415700', 'Marvel Super Heroes vs. Street Fighter est un jeu de combat, un crossover développé et édité par Capcom. Il s''agit de la suite de X-Men vs. Street Fighter et du deuxième épisode de la série Marvel vs. Capcom. Le jeu est d''abord sorti sur borne d''arcade en 1997 puis est porté sur Sega Saturn en 1998 et sur PlayStation en 1999.

Le gameplay et l''esthétique de Marvel Super Heroes vs Street Fighter restent similaires à X-Men vs Street Fighter. Chaque joueur sélectionne deux personnages pour participer à un combat individuel en équipe, en essayant de vaincre l''équipe adverse. Le jeu remplace la plupart des personnages X-Men de l''épisode précédent par des personnages d''autres propriétés de Marvel. Ce deuxième opus intègre un nouveau mécanisme de jeu connu sous le nom de « Variable Assist », qui sera utilisé dans les futurs titres Marvel vs. Capcom.', 'https://fr.wikipedia.org/wiki/Marvel_Super_Heroes_vs._Street_Fighter'),
  ('Q2663381', 'Alundra 2: Une Légende est née, ou simplement Alundra 2, est un jeu vidéo de type action-RPG développé par Matrix Software et Contrail, deux studios japonais, et sorti en 2000 sur PlayStation. Suite du très apprécié Alundra, ce volet n''a aucun rapport avec le premier opus, si ce n''est bien sûr le nom du jeu, leur police de caractères, leur compositeur (leurs musiques hypnotiques), leurs éléments graphiques, deux couples de jeunes héros et bien sûr leurs énigmes corsées, avec même, dans le dernier donjon de chaque jeu, une énigme demandant de sauter sur des parallélépipèdes disparaissant en une seconde, afin d''enclencher un interrupteur permettant de terminer l''aventure.', 'https://fr.wikipedia.org/wiki/Alundra_2_:_Une_L%C3%A9gende_est_n%C3%A9e'),
  ('Q2415823', 'Marvel vs. Capcom: Clash of Super Heroes est jeu vidéo de combat développé et édité par Capcom en janvier 1998 sur borne d''arcade. C''est le troisième épisode de la série Marvel vs. Capcom. Il a été adapté sur console de jeux vidéo en 1999 et 2000.', 'https://fr.wikipedia.org/wiki/Marvel_vs._Capcom:_Clash_of_Super_Heroes'),
  ('Q20922384', 'Lucky Luke: La Fièvre de l''Ouest est un jeu vidéo de tir à la troisième personne développé par Kalisto Entertainment, et édité par Infogrames, en partenariat avec Lucky Comics, sorti le 31 octobre 2001 en Europe sur Windows et PlayStation. Il est le deuxième jeu vidéo en trois dimensions de la franchise Lucky Luke, sixième opus du nom, succédant à Sur la piste des Dalton sorti en 1998, et précédant Lucky Luke: Outlaws sorti en 2006.

Le jeu est accueilli de manière mitigée par la presse spécialisée.', 'https://fr.wikipedia.org/wiki/Lucky_Luke_:_La_Fi%C3%A8vre_de_l%27Ouest');

insert into import_summary (wikidata_id, summary, source) values
  ('Q2639760', 'Rollcage est un jeu vidéo de course sorti en 1999 sur PlayStation et sous Windows. Il a été développé par Attention to Detail et édité par Psygnosis. Une suite est sortie l''année suivante, portant le nom de Rollcage Stage II.', 'https://fr.wikipedia.org/wiki/Rollcage'),
  ('Q2633628', 'Street Fighter Alpha 3, connu au Japon sous le nom Street Fighter Zero 3, est un jeu vidéo de combat en un contre un développé et édité par Capcom sur CP System II en juin 1998. C''est le troisième épisode de la série Street Fighter Alpha et il fait suite à Street Fighter Alpha 2, incluant de nouveaux personnages et des améliorations au niveau du système de jeu comme la possibilité d''effectuer des juggles. Le jeu est par la suite converti sur plusieurs consoles de salon ou portables.

Street Fighter Alpha 3 sort sur borne d''arcade, simultanément au Japon et en Amérique du Nord, le 29 juin 1998, puis le 4 septembre 1998 en Europe. C''est le 29e titre à exploiter le CP System II. Street Fighter Alpha 3 est porté et édité sur PlayStation au Japon le 23 décembre 1998 et en mai 1999 pour l''Amérique du Nord. Le titre est publié ensuite, toujours au Japon, en juillet 1999 sur Dreamcast. Street Fighter Alpha 3 connaît également une sortie européenne sur Dreamcast en septembre 2000. Une version légèrement améliorée intitulée Street Fighter Zero 3 Upper sort en 2001 sur borne d''arcade, puis est adaptée sur Game Boy Advance sous le nom Street Fighter Alpha 3 Upper. Le portage sur PlayStation Portable est quant à lui intitulé Street Fighter Alpha 3 Max.', 'https://fr.wikipedia.org/wiki/Street_Fighter_Alpha_3'),
  ('Q2634792', 'The Misadventures of Tron Bonne (Tron ni Kobun au Japon) est un jeu d''action-plates-formes développé et édité par Capcom en 2000 sur PlayStation. Il fait partie de la franchise Mega Man et est le deuxième de la série dérivée Mega Man Legends.', 'https://fr.wikipedia.org/wiki/The_Misadventures_of_Tron_Bonne'),
  ('Q1451169', 'Nicktoons Racing est un jeu vidéo de course développé par Software Creations et sorti à partir de 1999 sur borne d''arcade, Windows, PlayStation, Game Boy Color et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Nicktoons_Racing'),
  ('Q2239766', 'Ace Combat 2 est un jeu vidéo d''arcade et de simulation de combat aérien développé et édité par Namco en 1997 sur PlayStation.

Il fait partie de la série Ace Combat.', 'https://fr.wikipedia.org/wiki/Ace_Combat_2'),
  ('Q2617070', 'Warpath: Jurassic Park est un jeu vidéo de combat développé par DreamWorks Interactive et Black Ops Entertainment, puis édité par Electronic Arts sur PlayStation, qui s''inspire des deux premiers films de la saga Jurassic Park. Il est sorti en 1999 en Europe et le 31 octobre 1999 en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Warpath:_Jurassic_Park'),
  ('Q2609711', 'Koudelka est un jeu vidéo de rôle se déroulant dans un univers fantastique. Il a été développé par Sacnoth (en) et édité par SNK au Japon, et Infogrames en Europe et en Amérique du Nord.

Il fonctionne sur PlayStation et est sorti le 16 décembre 1999 au Japon, le 29 juin 2000 en Amérique du Nord et le 27 septembre 2000 en Europe.

Il existe un manga tiré du jeu, écrit par Yūji Iwahara.

Il précède de façon indirecte le premier épisode de la série Shadow Hearts.', 'https://fr.wikipedia.org/wiki/Koudelka_(jeu_vid%C3%A9o)'),
  ('Q2666099', 'Duke Nukem: Time to Kill est un jeu vidéo de tir à la troisième personne sorti le 3 novembre 1998 en Europe et le 30 septembre 1998 aux États-Unis. Il fonctionne sur PlayStation. Le jeu a été développé par n-Space puis édité par GT Interactive et 3D Realms.

Il a pour suite Duke Nukem: Land of the Babes.', 'https://fr.wikipedia.org/wiki/Duke_Nukem:_Time_to_Kill'),
  ('Q1423930', 'Hexen, aussi connu sous le nom de Hexen: Beyond Heretic, est un jeu de tir à la première personne développé par Raven Software, publié par id Software, distribué par GT Interactive et sorti le 30 octobre 1995.', 'https://fr.wikipedia.org/wiki/Hexen'),
  ('Q2631370', 'Rival Schools: United by Fate est un jeu vidéo de combat développé et édité par Capcom en novembre 1997 sur système d''arcade ZN-2. Rival Schools: United by Fate est porté sur PlayStation le 30 juillet 1998 au Japon, le 26 octobre 1998 en Amérique du Nord et le 20 novembre 1998 en Europe.', 'https://fr.wikipedia.org/wiki/Rival_Schools:_United_by_Fate'),
  ('Q2262840', 'DonPachi est un jeu vidéo développé par Cave. Il s’agit d’un shoot ''em up à défilement vertical de type manic shooter. Il est publié en 1995 sur borne d''arcade, puis porté sur Saturn et PlayStation en 1996. C''est le tout premier jeu de la société Cave. Il connaît une suite en 1996, DoDonPachi.', 'https://fr.wikipedia.org/wiki/DonPachi'),
  ('Q2465338', 'Clock Tower II: The Struggle Within, sorti au Japon sous le nom Clock Tower Ghost Head, est un jeu vidéo de types point-and-click et survival horror développé par la société japonaise Human Entertainment, édité sur PlayStation au Japon en 1998, et aux États-Unis en 1999. Il s''agit d''un spin-off de la franchise Clock Tower.', 'https://fr.wikipedia.org/wiki/Clock_Tower_II:_The_Struggle_Within'),
  ('Q2668497', 'Final Fantasy Chronicles est une compilation publiée par Square en 2001 sur PlayStation, regroupant des versions remastérises de Final Fantasy IV et de Chrono Trigger, deux jeu vidéo de rôle, sortis à l''origine sur Super Nintendo respectivement en 1991 et 1995.', 'https://fr.wikipedia.org/wiki/Final_Fantasy_Chronicles'),
  ('Q2669580', '10-Yard Fight est un jeu vidéo de football américain développé et publié par Irem, sorti en 1983 sur borne d’arcade. En 1985, il fait l’objet d’un portage sur Nintendo Entertainment System où il figure parmi les dix-sept jeux au lancement de la console aux États-Unis. Il est également publié sur MSX en 1986. La version arcade est commercialisée le 2 mai 2018 sur le Nintendo eShop au sein de la collection Arcade Archives, produite par Hamster.', 'https://fr.wikipedia.org/wiki/10-Yard_Fight'),
  ('Q1512956', 'Tony Hawk''s Pro Skater 4 (THPS4), est le quatrième opus de la série des Tony Hawk''s Pro Skater. Développé par Neversoft et édité par Activision sur GameCube, Game Boy, PlayStation, PlayStation 2, Xbox, et PC.', 'https://fr.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_4'),
  ('Q2692639', 'Crusaders of Might and Magic est un jeu vidéo de type action-RPG développé et édité par The 3DO Company, sorti en 1999 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/Crusaders_of_Might_and_Magic'),
  ('Q1523264', 'Nagano Winter Olympics ''98 (aussi appelé Hyper Olympic in Nagano) est un jeu vidéo de sport sorti en 1997 sur Nintendo 64 et PlayStation. Le jeu a été développé et édité par Konami.', 'https://fr.wikipedia.org/wiki/Nagano_Winter_Olympics_%2798'),
  ('Q1464617', '24 Heures du Mans est un jeu vidéo tiré de l''événement éponyme. En version originale, le jeu se nomme Test Drive: Le Mans. Ce jeu fait partie de la saga Test Drive même si le nom a été tronqué pour la version française. Le jeu propose, malgré son titre, des courses différentes.', 'https://fr.wikipedia.org/wiki/24_Heures_du_Mans_(jeu_vid%C3%A9o)'),
  ('Q2736827', 'Samurai Shodown II connu au Japon sous le titre de True Samurai Spirits: Haohmaru Hell Change, est un jeu vidéo de combat développé et édité en 1994 par SNK sur système d''arcade Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD (NGM 063).', 'https://fr.wikipedia.org/wiki/Samurai_Shodown_II'),
  ('Q2734496', 'Hidden and Dangerous est un jeu vidéo d''action, d''infiltration et de stratégie développé Illusion Softworks et édité par Take Two Interactive en 1999 sur PC.

Le jeu bénéficie de portages sur Dreamcast en 2000 et sur PlayStation en 2001.

En 2003, à l''occasion de la sortie de Hidden and Dangerous 2, la version sur PC de Hidden and Dangerous, est proposée en libre téléchargement par l''éditeur.', 'https://fr.wikipedia.org/wiki/Hidden_and_Dangerous'),
  ('Q2458858', 'Twisted Metal: Small Brawl est un jeu de combat motorisé sorti en 2001 sur PlayStation. C''est le sixième jeu de la série Twisted Metal. Quoique destiné à un public plus jeune que les autres épisodes, Small Brawl garde en partie l''humour violent caractéristique de la série.', 'https://fr.wikipedia.org/wiki/Twisted_Metal:_Small_Brawl'),
  ('Q2707840', 'Kula World (Kula Quest au Japon, Roll Away aux États-Unis) est un jeu vidéo de réflexion développé par Game Design Sweden et édité par Sony Computer Entertainment en 1998 sur PlayStation. Le jeu a été réédité sur PlayStation 3 et PlayStation Portable en 2007.', 'https://fr.wikipedia.org/wiki/Kula_World'),
  ('Q24039612', 'Shérif, fais-moi peur 2 (connu aux États-Unis sous le nom The Dukes of Hazzard 2: Daisy Dukes It Out) est un jeu vidéo de course basé sur la série télévisée éponyme.', 'https://fr.wikipedia.org/wiki/Sh%C3%A9rif,_fais-moi_peur_2'),
  ('Q2446941', 'Baldies est un jeu vidéo de stratégie en temps réel sorti en 1995 sur Jaguar CD, puis porté en 1996 sur DOS, PlayStation et Windows. Le jeu a été développé par Creative Edge Software puis édité par Atari.', 'https://fr.wikipedia.org/wiki/Baldies'),
  ('Q2699066', 'Dream Story: Les Aventures de Tim et Lola (40 Winks: Conquer Your Dreams) est un jeu vidéo de plates-formes sorti en 1999 sur PlayStation. Le jeu a été développé par Eurocom et édité par GT Interactive.

Une version Nintendo 64 devait voir le jour en septembre 1999 mais a été annulée après un premier report. Une version en développement a été retrouvée et la ROM du jeu jouable sur émulateur est disponible sur Internet. En 2017, la société Piko Interactive a acquis les droits d''édition du jeu et compte sortir en 2018 une version cartouche en distribution limitée (250 à 300 exemplaires et vendu uniquement sur Internet) après une campagne de financement participative réussie. Cette version sort également sur Windows.', 'https://fr.wikipedia.org/wiki/Dream_Story_:_Les_Aventures_de_Tim_et_Lola'),
  ('Q2713289', 'Monstres et Cie: L''Île de l''épouvante (Monsters, Inc. Scream Team) est un jeu vidéo de plates-formes et d''aventure sorti en 2001 et 2002 sur PlayStation, PlayStation 2 et Windows. Le jeu a été développé par Behaviour Interactive, anciennement Artificial Mind & Movement (A2M)

Édité par Sony Computer Entertainment, il est basé sur le film d''animation Monstres et Cie de Pixar.', 'https://fr.wikipedia.org/wiki/Monstres_et_Cie_:_L%27%C3%8Ele_de_l%27%C3%A9pouvante'),
  ('Q2713506', 'Tombi! (Tomba! aux États-Unis et Ore! Tomba au Japon) est un jeu de plates-formes à défilement horizontal développé par Whoopee Camp, sorti en 1998 sur PlayStation. Une suite fut développée par la suite sous le nom de Tombi! 2: The Evil Swine Return.', 'https://fr.wikipedia.org/wiki/Tombi!'),
  ('Q2450661', 'Armored Core est un jeu vidéo de tir en vue à la troisième personne où l''on contrôle un mecha, un robot de combat. Il est développé par From Software et édité par Sony Computer Entertainment en 1997 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Armored_Core_(jeu_vid%C3%A9o)'),
  ('Q2710113', 'Vandal Hearts est un jeu vidéo de rôle tactique japonais développé par Konami Computer Entertainment Tokyo et édité par Konami en 1997, sorti sur PlayStation et également sur Saturn au Japon. Une version Windows a également été développée spécifiquement pour la Corée du Sud.', 'https://fr.wikipedia.org/wiki/Vandal_Hearts'),
  ('Q1484061', 'G-Police est un jeu vidéo de combat spatial développé et édité par Psygnosis, sorti en 1997 sur PlayStation et Windows. Il a eu une suite en 1999, G-Police: Weapons of Justice.', 'https://fr.wikipedia.org/wiki/G-Police'),
  ('Q2443162', 'X-Men: Mutant Academy est un jeu vidéo de combat développé par Paradox Development et publié par Activision en 2000. Le jeu utilise comme univers le comics américain X-Men. Le jeu a une suite, appelée X-Men: Mutant Academy 2.', 'https://fr.wikipedia.org/wiki/X-Men:_Mutant_Academy'),
  ('Q2450676', 'Armored Core: Project Phantasma est un jeu de simulation de mecha sorti en 1997 sur la console PlayStation de Sony. C''est une suite du premier opus de la saga Armored Core.', 'https://fr.wikipedia.org/wiki/Armored_Core:_Project_Phantasma'),
  ('Q2444091', 'Akuji the Heartless (Litt.: « Akuji le Sans-cœur ») est un jeu vidéo d''action-aventure développé par Crystal Dynamics et édité par Eidos Interactive, sorti en janvier 1999 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Akuji_the_Heartless'),
  ('Q2733462', 'Mega Man X6 (Rockman X6 au Japon) est un jeu d''action-plates-formes développé par Capcom Production Studio 3 et édité par Capcom sur PlayStation et PC (Windows). C''est le sixième volet de la série dérivée Mega Man X. Il est réédité en 2015 au Japon sur le PlayStation Network, jouable sur PlayStation 3, PlayStation Portable et PlayStation Vita. Il est également inclut dans la compilation Mega Man X Collection sortie en 2006.', 'https://fr.wikipedia.org/wiki/Mega_Man_X6'),
  ('Q2451182', 'Armored Core: Master of Arena est un jeu vidéo sorti en 1999 sur la console PlayStation. C''est l''une des deux extensions de Armored Core premier opus de la saga Armored Core. Master of Arena est le dernier Armored Core sorti sur la console PlayStation première génération.', 'https://fr.wikipedia.org/wiki/Armored_Core:_Master_of_Arena'),
  ('Q1477100', 'Jade Cocoon: La Légende de Tamamayu est un jeu vidéo de rôle sorti sur PlayStation le 3 décembre 1998 au Japon.

Le jeu est développé par Genki en collaboration avec Katsuya Kondō, character designer du Studio Ghibli, ayant notamment œuvré sur les films d''animations Kiki la petite sorcière et Je peux entendre l''océan.

Une suite, titrée Jade Cocoon 2, sort en 2001 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Jade_Cocoon_:_La_L%C3%A9gende_de_Tamamayu'),
  ('Q22019773', 'Absolute Football, aussi connu sous Viva Soccer en Amérique du Nord, Viva Football au Royaume-Uni, et 20 Reiki Striker Retsuden au Japon, est un jeu vidéo de football associatif, publié en 1998, sur console PlayStation et PC développé par Crimson Studio et publié par Virgin Interactive.', 'https://fr.wikipedia.org/wiki/Absolute_Football'),
  ('Q2698346', 'Ridge Racer Revolution (RRR) est un jeu vidéo de course développé et édité par Namco, sorti en 1995 au Japon et en 1996 en Europe et en Amérique du Nord sur PlayStation. Il fait partie de la série Ridge Racer.', 'https://fr.wikipedia.org/wiki/Ridge_Racer_Revolution'),
  ('Q2447854', 'Toy Story Racer est un jeu vidéo de course sorti en 2001 sur Game Boy Color et PlayStation. Le jeu a été développé par Traveller''s Tales sur PlayStation et par Tiertex Design sur Game Boy Color; dans les deux cas, il a été édité par Activision.

Le jeu est basé sur l''univers de Toy Story.', 'https://fr.wikipedia.org/wiki/Toy_Story_Racer'),
  ('Q1467263', 'Dino Crisis 2 est un jeu vidéo d''action de type survival horror développé par Capcom Production Studio 4 et édité par Capcom en 2000 sur PlayStation. Il est sorti sur PlayStation et PC en 2000. Dino Crisis 2 a été créé par Shinji Mikami, le créateur de la série Resident Evil. C''est la suite du jeu Dino Crisis.', 'https://fr.wikipedia.org/wiki/Dino_Crisis_2'),
  ('Q2734372', 'Ogre Battle: The March of the Black Queen est un tactical RPG développé par Quest et édité en 1993 par Enix sur Super Famicom. Le jeu a été réédité en 1996 sur PlayStation et Saturn. Il est le premier jeu de la série Ogre Battle.

Les principaux attraits de ce jeu de rôle au tour par tour résident dans son système de recrutement et d''évolution des personnages.

Le titre du jeu est tiré des deux chansons du groupe de rock Queen, Ogre Battle et The March of the Black Queen, tous deux sortis en 1974 dans l''album Queen II[réf. nécessaire].', 'https://fr.wikipedia.org/wiki/Ogre_Battle:_The_March_of_the_Black_Queen'),
  ('Q2735515', 'Batman: Gotham City Racer est un jeu vidéo sur le super-héros Batman, l''homme chauve-souris. Il s''agit d''un jeu de course sorti en mai 2001 sur la console PlayStation. Le jeu été développé et édité par Ubisoft et il est basé sur la série télévisée d''animation Batman (The New Batman Adventures).', 'https://fr.wikipedia.org/wiki/Batman:_Gotham_City_Racer'),
  ('Q1470332', 'Les Cochons de guerre (anglais: Hogs of War) est un jeu vidéo

de stratégie au tour par tour dit « jeu d''artillerie », développé par Infogrames Sheffield House, sorti sur PlayStation et sous Windows en 2000. Le jeu reprend le concept d''un Worms mais en trois dimensions, servi par un doublage sonore remarqué puisque tirant parti des voix de l''équipe les Guignols de l''info.', 'https://fr.wikipedia.org/wiki/Les_Cochons_de_guerre'),
  ('Q2734554', 'Skullmonkeys est un jeu vidéo de plates-formes développé par The Neverhood, Inc. et édité par Electronic Arts, sorti en 1998 sur PlayStation.

Il fait suite à The Neverhood dont il reprend partiellement la direction artistique: le jeu est agrémenté de scénettes filmées avec des personnages en Pâte à modeler.', 'https://fr.wikipedia.org/wiki/Skullmonkeys'),
  ('Q2709135', 'Toy Story 2: Buzz l''Éclair à la rescousse ! (Toy Story 2: Buzz Lightyear to the Rescue !) est un jeu vidéo de plates-formes sorti en 1999 sur Windows, Nintendo 64, PlayStation et Dreamcast. Le jeu a été développé par Traveller''s Tales et édité par Activision et Disney Interactive. Une version Game Boy Color est sortie sous le nom Toy Story 2 et a été développée par Tiertex Design Studios.

Le jeu est basé sur le film d''animation Toy Story 2 de Pixar. Les voix des personnages sont les mêmes que dans le film.', 'https://fr.wikipedia.org/wiki/Toy_Story_2_:_Buzz_l%27%C3%89clair_%C3%A0_la_rescousse_!'),
  ('Q24890553', 'Boku wa Kōkū Kanseikan est un jeu vidéo de simulation développé par Graphic Research et édité par Tam Inc., sorti en 2001 sur Game Boy Advance. Il est paru uniquement au Japon et était disponible au lancement de la console.', 'https://fr.wikipedia.org/wiki/Boku_wa_K%C5%8Dk%C5%AB_Kanseikan'),
  ('Q1543280', 'Theme Park est un jeu vidéo de gestion conçu par Peter Molyneux et Demis Hassabis, développé par Bullfrog Productions et édité par Electronic Arts en 1994 sur Amiga et DOS. Le jeu a été porté sur consoles de jeu en 1995. L''objectif du joueur est de gérer le développement d''un parc d''attractions.

Le nom du jeu est un clin d''œil à la série des Sim de Maxis. En effet, en anglais la prononciation de Theme et Sim est relativement proche.', 'https://fr.wikipedia.org/wiki/Theme_Park'),
  ('Q1538485', 'Tony Hawk''s Pro Skater 2 (également appelé THPS2) est un jeu vidéo de simulation de skateboard, développé par Neversoft et édité par Activision. C''est le deuxième jeu de la série Tony Hawk''s sorti en 2000 sur PlayStation, puis porté sur PC, Game Boy Color, Dreamcast, puis en 2001 sur Mac, Game Boy Advance, Nintendo 64, Xbox. Le jeu a été tardivement porté sur téléphone mobile en 2006 sur Windows Mobile, Windows Phone et en 2010 sur iOS.', 'https://fr.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_2'),
  ('Q737103', 'Quake II est un jeu vidéo de tir à la première personne (FPS) développé par id Software et publié par Activision le 30 novembre 1997. Le jeu s’inscrit dans la lignée du précédent titre d’id Software - Quake - dont il reprend le moteur de jeu id Tech 2 et le système de jeu. Son scénario ne s''inscrit en revanche pas dans la trame du premier opus de la série, le joueur incarnant un soldat lors d''un débarquement massif contre une planète d''extra-terrestres hostiles, les Stroggs.', 'https://fr.wikipedia.org/wiki/Quake_II'),
  ('Q1565343', 'Q*bert est un jeu vidéo d''action/réflexion édité sur borne d''arcade par Gottlieb en 1982. Conçu par Warren Davis et Jeff Lee, Q*bert est devenu un classique du jeu d''arcade et a été porté sur de nombreux micro-ordinateurs personnels.', 'https://fr.wikipedia.org/wiki/Q*bert'),
  ('Q731266', 'Brain Dead 13 ou BrainDead 13 est un film interactif produit par ReadySoft sorti pour DOS en 1995 et plus tard porté sur consoles en 1996.', 'https://fr.wikipedia.org/wiki/Brain_Dead_13'),
  ('Q1536626', 'Vagrant Story est un jeu vidéo de rôle développé et publié par Square pour la PlayStation le 10 février 2000 au Japon, le 15 mai 2000 en Amérique du Nord et le 21 juin 2000 dans la région PAL. Le jeu a été réalisé en grande partie par l''équipe de Yasumi Matsuno, responsable de Final Fantasy Tactics, et est l''un des rares titres à avoir obtenu la note maximale dans le magazine japonais Famitsu, 40 sur 40.

L''intrigue du jeu tourne autour d''Ashley Riot, un agent d''élite envoyé dans la cité de LéaMundis pour enquêter sur le lien que le chef d''une secte entretient avec un membre du Parlement, le Duc Bardora. Ashley a été accusé du meurtre du Duc, et le jeu raconte les événements qui se sont déroulés une semaine avant l''assassinat.', 'https://fr.wikipedia.org/wiki/Vagrant_Story'),
  ('Q733992', 'Resident Evil 2, sorti au Japon sous le nom Biohazard 2, est un jeu vidéo d''action-aventure de type shooter développé et édité par Capcom en 1998 sur PlayStation. Il est ensuite porté sur PC, Nintendo 64, Dreamcast, GameCube, puis vendu sur la plateforme de téléchargement PlayStation Network.

Deuxième épisode de la série à succès Resident Evil, cette fois-ci, les forces spéciales des STARS cèdent la place à deux héros bien plus modestes: Claire Redfield, simple civile et sœur de Chris Redfield un des personnages du premier opus, ainsi que Leon Scott Kennedy, nouvelle recrue dans la police en route vers Raccoon City pour son premier jour.', 'https://fr.wikipedia.org/wiki/Resident_Evil_2'),
  ('Q739312', 'Creature Shock est un jeu vidéo de tir futuriste sorti en 1994 sur PC et 3DO, développé par Argonaut Games et édité par Virgin Interactive. Le jeu a été plus tard porté sur Philips CD-i, Saturn et PlayStation.

Atari avait prévu de faire un portage sur Atari Jaguar, mais le projet a été annulé[réf. nécessaire].

Le titre a été l’un des premiers jeux sur CD-ROM à utiliser des cinématiques[réf. nécessaire]. Par conséquent, le jeu pèse plus d''un gigaoctet et tient sur deux CD.', 'https://fr.wikipedia.org/wiki/Creature_Shock'),
  ('Q739591', 'Shin Megami Tensei: Devil Summoner - Soul Hackers est un jeu vidéo de rôle développé et édité par Atlus, sorti en 1997 sur Saturn, PlayStation et en 2013 sur Nintendo 3DS.

Vingt-cinq ans plus tard, Atlus sort en août 2022 une suite nommée Soul Hackers 2 sur PlayStation 4, PlayStation 5, Xbox One, Xbox Series et Windows.', 'https://fr.wikipedia.org/wiki/Shin_Megami_Tensei:_Devil_Summoner_-_Soul_Hackers'),
  ('Q2472816', 'Alfred Chicken est un jeu vidéo de plates-formes développé par Twilight et édité par Mindscape, sorti en 1993 sur Amiga, Amiga CD32, NES, Super Nintendo et Game Boy.', 'https://fr.wikipedia.org/wiki/Alfred_Chicken'),
  ('Q1636069', 'Wing Commander III: Cœur de tigre (Wing Commander III: Heart of Tiger) est un jeu vidéo mêlant aventure et combat spatial développé et édité par Origin Systems sur PC, 3DO et PlayStation.

Le développement du jeu a coûté environ 4 millions de dollars[réf. nécessaire], il propose des séquences en full motion video ou de synthèse après chaque mission ou moment clé.', 'https://fr.wikipedia.org/wiki/Wing_Commander_III_:_C%C5%93ur_de_tigre'),
  ('Q1636092', 'Wing Commander IV: Le Prix de la liberté (Wing Commander IV: The Price of Freedom) est un jeu vidéo de combat spatial développé par les studios d''Origin Systems, sorti en 1995 sur PC puis réédité en 1997 sur PlayStation. On en parle souvent sous la dénomination WC4 dans les écrits qui le concernent. Il bénéficia d''un budget d''environ dix millions de dollars. Cet opus est le quatrième volet de la série Wing Commander. Il mêle séquences de shoot spatial et d''aventure, via des déplacements dans un vaisseau-mère. Ceux-ci disposent de nombreuses cinématiques filmées qui l''apparentent au film interactif. Ces dernières ont été tournées dans les Ren-Mar Studios à Hollywood en 35 mm.', 'https://fr.wikipedia.org/wiki/Wing_Commander_IV_:_Le_Prix_de_la_libert%C3%A9'),
  ('Q2744116', 'Mega Man X3, ou Rockman X3 au Japon, est un jeu d''action-plates-formes édité par Capcom sur Super Nintendo, Saturn, PlayStation et PC (Windows). C''est le troisième volet de la série Mega Man X. Il est par la suite réédité sur téléphone mobile et les consoles virtuelles de la Wii U) et de la New Nintendo 3DS). Comme pour Mega Man X2, le jeu bénéficie de la puce Cx4, qui permet des visuels semi-transparents et certains effets en 3D.', 'https://fr.wikipedia.org/wiki/Mega_Man_X3'),
  ('Q2749076', 'Kensei: Sacred Fist, connu au Japon sous le nom de Bugi, est un jeu de combat sorti en 1998, développé et édité par Konami.

Les combats sont un duel entre deux combattants, de nationalité et de style de combat divers. Le système de combat est proche de Virtua Fighter ou de Tekken. Il propose de choisir parmi 9 personnages, jouables dès le début, et 14 autres peuvent être débloqués.', 'https://fr.wikipedia.org/wiki/Kensei:_Sacred_Fist'),
  ('Q2736832', 'Lethal Enforcers est un jeu vidéo de tir au pistolet développé et édité par Konami, sorti en 1992 sur borne d''arcade. Il a été adapté sur Mega Drive et Mega-CD en 1993 et sur Super Nintendo en 1994. Il a aussi été porté sur PlayStation en 1997 dans une compilation regroupant Lethal Enforcers et sa suite, Lethal Enforcers II: Gunfighters. Une autre suite a été réalisée bien qu''elle soit très différentes des deux premiers opus, il s''agit de Lethal Enforcers 3. L''action se déroule dans la ville de Chicago aux États-Unis.', 'https://fr.wikipedia.org/wiki/Lethal_Enforcers'),
  ('Q1633977', 'Forsaken (Forsaken 64 sur Nintendo 64) est un jeu vidéo de tir à la première personne sorti en 1998 sur PlayStation, Windows et Nintendo 64. Le jeu est développé par Probe Software et édité par Acclaim.', 'https://fr.wikipedia.org/wiki/Forsaken_(jeu_vid%C3%A9o)'),
  ('Q2467868', 'Mega Man X5 (Rockman X5 au Japon), est un jeu d''action-plates-formes développé par Capcom Production Studio 3 et édité par Capcom sur PlayStation et PC (Windows). C''est le cinquième volet de la série Mega Man X. Il est réédité en 2014 sur le PlayStation Network, jouable sur PlayStation 3, PlayStation Portable et PlayStation Vita. Il est également inclut dans la compilation Mega Man X Collection sortie en 2006.', 'https://fr.wikipedia.org/wiki/Mega_Man_X5'),
  ('Q2748100', 'Olympic Summer Games: Atlanta 1996 est un jeu vidéo de sport et fonctionne sur Mega Drive, Super Nintendo, 3DO, PlayStation, Game Boy et Windows.', 'https://fr.wikipedia.org/wiki/Olympic_Summer_Games:_Atlanta_1996'),
  ('Q1629190', 'Tail Concerto est un jeu vidéo développé par CyberConnect2 et édité par Bandai en 1998 sur PlayStation. C''est un jeu d''action-aventure où le joueur incarne Waffle Ryebread, un chien-policier chargé d''enquêter sur une affaire sans précédent dans son pays, Prairie.

Il s''agit du premier jeu de CyberConnect2, bien avant le succès de séries à licence comme.hack ou Naruto: Ultimate Ninja. Le character design a été confié à Nobuteru Yūki (Les Chroniques de la guerre de Lodoss, Vision d''Escaflowne (Tenkū no Esukafurōne), Chrono Cross... ). Le jeu possède des séquences animées doublées en japonais et sous-titrées en français, un fait rare pour l''époque.', 'https://fr.wikipedia.org/wiki/Tail_Concerto'),
  ('Q1567658', 'Lomax (connu sous le nom The Adventures of Lomax en Amérique du Nord) est un jeu vidéo de plates-formes développé et édité par Psygnosis en 1996 sur PlayStation et Windows. Le jeu est un spin-off tiré de la série Lemmings. Il met en scène Lomax, un lemming qui doit sauver ses congénères à travers de nombreux niveaux de plates-formes en scrolling horizontal.

Le jeu a été conçu par Erwin Kloibhofer et Henk Nieborg, les créateurs de Lionheart (1993) et The Misadventures of Flink (1994).', 'https://fr.wikipedia.org/wiki/Lomax_(jeu_vid%C3%A9o)'),
  ('Q2466962', 'Twisted Metal 4 est le quatrième épisode de la série de jeux de combat motorisé Twisted Metal, sorti en 1999. C''est le deuxième et dernier épisode de la série développé par les studios de Sony, 989 Studios.

Comme les épisodes précédents, Twisted Metal 4 a été réédité dans la collection « Greatest Hits » de Sony.', 'https://fr.wikipedia.org/wiki/Twisted_Metal_4'),
  ('Q720190', 'Contra: Legacy of War est un jeu vidéo de tir à la troisième personne développé par Appaloosa Interactive et édité par Konami of America, sorti en 1996 sur Saturn et PlayStation.', 'https://fr.wikipedia.org/wiki/Contra:_Legacy_of_War'),
  ('Q2742912', 'Puzzle Bobble 4 est un jeu vidéo de puzzle développé et édité par Taito en 1998 sur borne d''arcade. Le jeu a été adapté sur Dreamcast, PlayStation, Game Boy Color et Windows sous le titre Bust-a-Move 4.

C''est le 4e épisode de la série Puzzle Bobble.', 'https://fr.wikipedia.org/wiki/Puzzle_Bobble_4'),
  ('Q1632978', 'Demolition Racer est un jeu vidéo de course et de combat motorisé, développé par Pitbull Syndicate (en) et édité par Infogrames. Le jeu est initialement commercialisé sur PlayStation et Windows, respectivement le 31 août 1999 et le 12 septembre 2000. Le système de jeu est similaire à celui de la célèbre série de jeux vidéo Destruction Derby.

Le jeu est réédité pour la Dreamcast, sous le nom Demolition Racer: No Exit, il propose de nouveaux circuits, de nouvelles voitures, des mini-jeux à débloquer, et un mode supplémentaire appelé « No Exit », un mode de jeu similaire au « Last Man Standing » (le dernier homme debout) présent dans d''autres jeux.', 'https://fr.wikipedia.org/wiki/Demolition_Racer'),
  ('Q726167', 'Harry Potter et la Chambre des secrets est un jeu vidéo d''action-aventure publié par Electronic Arts inspiré du roman Harry Potter et la Chambre des secrets de J.K. Rowling, et du film homonyme. Il est publié en 2002 sur consoles PlayStation 2, Xbox, GameCube et Game Boy Advance. Il est en parallèle développé par Amaze Entertainment sur les supports Windows et Game Boy Color. Une version originale est également créée sur PlayStation par Argonaut Games. Il s''agit également du dernier jeu vidéo Harry Potter publié sur PlayStation.', 'https://fr.wikipedia.org/wiki/Harry_Potter_et_la_Chambre_des_secrets_(jeu_vid%C3%A9o)'),
  ('Q1571727', 'International Track and Field: Summer Games (International Track and Field 2000 aux États-Unis, Ganbare! Nippon! Olympics 2000 au Japon, International Track and Field 2 en Europe sur PlayStation) est un jeu vidéo de sport sorti en 2000 et fonctionne sur Nintendo 64, PlayStation et Game Boy Color. Le jeu a été développé et édité par Konami.', 'https://fr.wikipedia.org/wiki/International_Track_and_Field:_Summer_Games'),
  ('Q728061', 'Duke Nukem 3D est un jeu de tir à la première personne développé par 3D Realms et initialement commercialisé en 1996 sur PC. Troisième opus proposant d''incarner le personnage musclé et machiste Duke Nukem, le jeu oriente l''initiale série de jeu de plates-formes vers le jeu de tir, tout en apportant un ton résolument adulte et très second degré. Duke Nukem 3D obtint un grand succès, faisant de son personnage principal une figure célèbre du jeu vidéo.', 'https://fr.wikipedia.org/wiki/Duke_Nukem_3D'),
  ('Q1632918', 'San Francisco Rush: Extreme Racing est un jeu vidéo de course sorti en 1997 et fonctionne sur arcade, Nintendo 64 et PlayStation. Le jeu a été développé par Atari Games puis édité par Midway.

Le jeu fait partie de la série Rush.', 'https://fr.wikipedia.org/wiki/San_Francisco_Rush:_Extreme_Racing'),
  ('Q2738032', 'The Last Blade est un jeu vidéo de combat en 2D développé et édité par SNK en 1997 sur borne d''arcade Neo-Geo MVS et en 1998 sur console Neo-Geo AES et Neo-Geo CD (NGM 234). La version coréenne du jeu est appelée The Last Soldier.', 'https://fr.wikipedia.org/wiki/The_Last_Blade'),
  ('Q2476557', 'WCW vs. The World (connu au Japon sous le titre Virtual Pro-Wrestling) est un jeu vidéo de catch professionnel commercialisé en 1997 sur console PlayStation. Il s''agit du premier jeu développé par The Man Breeze (devenu par la suite AKI Corporation) à être commercialisé hors des frontières japonaises et le deuxième du genre commercialisé sur PlayStation, suivi de Power Move Pro Wrestling. WCW vs. the World marque le premier titre de la série japonaise des Virtual Pro Wrestling.', 'https://fr.wikipedia.org/wiki/WCW_vs._The_World'),
  ('Q29974103', 'Infestation est un jeu vidéo de combat motorisé développé par Frontier Developments et édité par Ubisoft, sorti en 2000 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/Infestation_(jeu_vid%C3%A9o,_2000)'),
  ('Q2755961', 'Arkanoid Returns est un jeu vidéo de casse-briques de la série Arkanoid, sorti en 1997 sur borne d''arcade, puis la même année sur PlayStation. Le jeu a été développé et édité par Taito.', 'https://fr.wikipedia.org/wiki/Arkanoid_Returns'),
  ('Q2749298', 'Baroque est un jeu vidéo de rôle développé par Sting Entertainment et édité par Atlus en 1998 sur Saturn. Il a été adapté sur PlayStation en 1999. Un remake du jeu a vu le jour en 2007 sur PlayStation 2. Il a été adapté sur Wii en 2008.', 'https://fr.wikipedia.org/wiki/Baroque_(jeu_vid%C3%A9o)'),
  ('Q2475051', 'Herc''s Adventures est un jeu vidéo d''aventure édité par LucasArts sur PlayStation et Saturn en 1997.', 'https://fr.wikipedia.org/wiki/Herc%27s_Adventures'),
  ('Q2483445', 'Vigilante 8: Second Offense est un jeu vidéo de combat motorisé paru en 1999 sur PlayStation, Nintendo 64 et Dreamcast. Il s''agit de la suite de Vigilante 8.', 'https://fr.wikipedia.org/wiki/Vigilante_8:_Second_Offense'),
  ('Q2757037', 'JoJo''s Bizarre Adventure: Heritage for the Future est un jeu de combat développé et édité par Capcom sur CP System III en 1999. Il est basé sur le manga JoJo''s Bizarre Adventure et plus précisément la troisième histoire. Il est porté sur PlayStation et Dreamcast en 1999.', 'https://fr.wikipedia.org/wiki/JoJo%27s_Bizarre_Adventure:_Heritage_for_the_Future'),
  ('Q2758716', 'Driver 2 est un jeu vidéo développé par Reflections sorti le 22 juin 2000 sur PlayStation sous le nom Driver 2: The Wheelman is Back (en Europe, Driver 2: Back on the Streets). Il est la suite du premier opus homonyme, Driver. Développé par Reflections et édité par Infogrames, il est le premier jeu grand public en 3D à combiner des phases à pied et en voiture. Deux ans plus tard, une version modifiée sort sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Driver_2'),
  ('Q2778488', 'The Italian Job est un jeu vidéo de course sorti en 2001 sur PlayStation, et qui fut développé par Rockstar Games. Il est fondé sur L''or se barre, film de 1969 réalisé par Peter Collinson.', 'https://fr.wikipedia.org/wiki/The_Italian_Job_(jeu_vid%C3%A9o,_2001)'),
  ('Q29888287', 'MTV Sports: Skateboarding - Featuring Andy Macdonald est un jeu vidéo de simulation de skateboard, développé par Darkblack et édité par THQ, sorti en 2000 sur PlayStation, PC (Windows), Game Boy Color, Dreamcast. Il tire son nom du skateur Andy MacDonald.', 'https://fr.wikipedia.org/wiki/MTV_Sports:_Skateboarding_-_Featuring_Andy_Macdonald'),
  ('Q29877635', 'Druid: Daemons of the Mind est un jeu vidéo de rôle et d’action développé par Synthetic Dimensions et publié par Sir-Tech en 1995. Le jeu se déroule dans un univers médiéval-fantastique, baptisé Navan, régit par quatre druides chargés de faire respecter les principes de la nature. L’équilibre du monde se trouve cependant bouleversé lorsque l’un d’eux vient à disparaitre.', 'https://fr.wikipedia.org/wiki/Druid:_Daemons_of_the_Mind'),
  ('Q28496887', 'V.I.P. est un jeu vidéo d''action développé par Ubisoft Shanghai et Planet Interactive, édité par Ubisoft, sorti en 2002 sur PlayStation, PlayStation 2, Windows, Game Boy Color et Game Boy Advance. Il est adapté de la série V.I.P..', 'https://fr.wikipedia.org/wiki/V.I.P._(jeu_vid%C3%A9o)'),
  ('Q2484999', 'WWF War Zone est un jeu vidéo de catch professionnel développé par Acclaim Studios Salt Lake et commercialisé par Acclaim Entertainment en 1998 sur consoles PlayStation, Nintendo 64 et Game Boy. Le jeu met en scène les catcheurs de la World Wrestling Federation (WWF). Contrairement aux précédents jeux WWF de chez Acclaim, WWF in Your House (1996), War Zone représente ses catcheurs en 3D ainsi qu''un nouveau système de mouvements.', 'https://fr.wikipedia.org/wiki/WWF_War_Zone'),
  ('Q739784', 'Resident Evil 3: Nemesis, sorti au Japon sous le nom Biohazard 3: Last Escape, est un jeu vidéo de type survival horror développé et édité par Capcom. Il est distribué dès fin 1999 sur PlayStation. Il est ensuite porté sur Windows et Dreamcast courant 2000, puis sur GameCube en 2003.

Le jeu marque une évolution dans la série avec une mise en avant du côté action. Il se déroule au même moment que Resident Evil 2 et met en scène un membre des STARS contre la société pharmaceutique Umbrella, et plus particulièrement contre l''une des armes biologiquement modifiées les plus redoutables de la série: Nemesis.', 'https://fr.wikipedia.org/wiki/Resident_Evil_3:_Nemesis'),
  ('Q28452535', 'Fox Hunt est un jeu vidéo de type film interactif développé par 3Vision Gamers et édité par Capcom, sorti en 1996 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/Fox_Hunt'),
  ('Q28127102', 'Lilo et Stitch: Ouragan sur Hawaï (Lilo & Stitch: Trouble in Paradise) est un jeu vidéo de plates-formes développé par Blitz Games et édité par Sony Computer Entertainment, sorti en 2002 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/Lilo_et_Stitch_:_Ouragan_sur_Hawa%C3%AF'),
  ('Q28126809', 'Blam! Machinehead (Machine Head en Amérique du Nord) est un jeu vidéo de tir à la première personne développé par Core Design et édité par Eidos Interactive, sorti en 1996 sur Windows, Saturn et PlayStation.', 'https://fr.wikipedia.org/wiki/Blam!_Machinehead'),
  ('Q740986', 'L''Amerzone: Le Testament de l''explorateur est un jeu vidéo d''aventure édité par Microids, sorti sur PC, Macintosh et PlayStation en 1999, puis porté sur iOS en 2011 et sur Android en 2014. Il s''agit du premier jeu vidéo conçu par Benoît Sokal, qui s''était jusqu''alors uniquement illustré dans le domaine de la bande dessinée en inventant notamment les aventures de l''inspecteur Canardo. Pour L''Amerzone, Sokal a réutilisé l''univers du cinquième opus des aventures de Canardo, bande dessinée parue en 1986, intitulée L''Amerzone. Le scénario du jeu diffère cependant de celui de la bande dessinée.

Le joueur incarne un journaliste à l''identité inconnue. Voulant réaliser l''interview d''un vieil explorateur du nom d''Alexandre Valembois, le journaliste se rend dans le phare où réside le vieil homme. Celui-ci, mourant après un long monologue destiné au jeune reporter, lui livre une tâche qui ne va pas sans sa part de mystère: aller en Amerzone pour y ramener « l''œuf des Oiseaux Blancs ». Le journaliste se lance alors à l''aventure pour tenter de réaliser le dernier souhait de l''explorateur.', 'https://fr.wikipedia.org/wiki/L%27Amerzone_:_Le_Testament_de_l%27explorateur'),
  ('Q2478310', 'Time Crisis: Project Titan est un jeu vidéo développé par Namco et édité par Sony Computer Entertainment. il s''agit d''un jeu de tir au pistolet publié le 4 avril 2001 sur PlayStation. Il fait partie de la série des Time Crisis', 'https://fr.wikipedia.org/wiki/Time_Crisis:_Project_Titan'),
  ('Q739782', 'Syphon Filter 2 est jeu vidéo de tir en vue objective et d''infiltration développé par 989 Studios et édité par Sony Computer Entertainment en 2000 sur PlayStation.

C''est le deuxième épisode de la série Syphon Filter. L''histoire reprend immédiatement là où elle s''était arrêtée dans le premier épisode.', 'https://fr.wikipedia.org/wiki/Syphon_Filter_2'),
  ('Q2479889', 'Time Commando est un jeu vidéo de beat them all sorti en 1996 sur PC et PlayStation. Le jeu a été développé par Adeline Software International puis édité par Activision.

Il est porté sur Saturn par Virtual Studio et publié sur la console de Sega par Acclaim Japan le 12 mars 1998, uniquement au Japon.

Les personnages sont en 3D et les décors en 3D précalculée.', 'https://fr.wikipedia.org/wiki/Time_Commando'),
  ('Q29854446', 'Yannick Noah 2000 (All Star Tennis 2000) est un jeu vidéo de sport (tennis) développé par Aqua Pacific et édité par Ubi Soft, sorti en 1999 sur Windows, PlayStation et Game Boy Color. Il s''agit de la suite de Yannick Noah All Star Tennis ''99

Il tient son nom de l''ancien joueur de tennis français Yannick Noah.', 'https://fr.wikipedia.org/wiki/Yannick_Noah_2000'),
  ('Q2494597', 'Warriors of Might and Magic est un jeu vidéo de type action-RPG développé et édité par The 3DO Company, sorti en 2000 sur PlayStation, PlayStation 2 et Game Boy Color.', 'https://fr.wikipedia.org/wiki/Warriors_of_Might_and_Magic'),
  ('Q48703015', 'Stuart Little 2 est un jeu vidéo de plates-formes développé par Magenta Software et édité par Activision, sorti en 2002 sur Windows, PlayStation et Game Boy Advance. Il est adapté du film du même nom.', 'https://fr.wikipedia.org/wiki/Stuart_Little_2_(jeu_vid%C3%A9o)'),
  ('Q2806610', '100% Star (Popstar Maker aux États-Unis) est un jeu vidéo de gestion sorti en 2001 sur PlayStation. Le jeu a été développé par Teque Software et édité par Eidos Interactive.', 'https://fr.wikipedia.org/wiki/100%25_Star'),
  ('Q2517411', 'Star Trek: Voyager - Elite Force est un jeu de tir à la première personne développé par Raven Software, publié par Activision le 18 septembre 2000 sur PC et basé sur l''univers de Star Trek.

Elite Force est basé sur le moteur de Quake 3 et résulte de la collaboration entre Raven Software et id Software, collaboration établie à travers de très nombreux jeux comme Heretic, Hexen, Take No Prisoners ou encore Soldier of Fortune et MageSlayer. Le moteur id Tech 3 prend en charge les cartes accélératrices 3D via OpenGL. Au niveau des sons, il peut mixter 96 pistes avec gestion de la spatialisation et de l''effet Doppler.', 'https://fr.wikipedia.org/wiki/Star_Trek:_Voyager_-_Elite_Force'),
  ('Q2816338', '360 (aussi orthographié Three Sixty) est un jeu vidéo de course sorti en 1999 sur PlayStation. Le jeu a été développé et édité par Cryo Interactive.

Une adaptation du jeu sort sur Game Boy Color l''année suivante sous le titre Rip-Tide Racer.', 'https://fr.wikipedia.org/wiki/360_(jeu_vid%C3%A9o)'),
  ('Q1751789', 'Panzer General est un jeu vidéo de type wargame publié en 1994 par Strategic Simulations, Inc. (SSI). Le joueur incarne un général qui participe aux principales batailles terrestres survenues en Europe, en Afrique du Nord et au Moyen-Orient, durant la Seconde Guerre mondiale.

Ce wargame constitue le premier de la série 5-Star General (Panzer General, Allied General, Fantasy General, Pacific General, Star General). Il a été suivi de Panzer General II.', 'https://fr.wikipedia.org/wiki/Panzer_General'),
  ('Q2799616', 'F1 Championship: Saison 2000 (F1 Championship: Season 2000) est un jeu vidéo de course de Formule 1 développé par Image Space Incorporated et Visual Sciences, édité par EA Sports, sorti en 2000 sur Windows, Mac, PlayStation, PlayStation 2 et Game Boy Color.', 'https://fr.wikipedia.org/wiki/F1_Championship_:_Saison_2000'),
  ('Q2506952', 'Hard Edge est un jeu vidéo d''action-aventure développé et édité par Sunsoft, sorti sur PlayStation en 1998 au Japon et en 1999 en Europe et en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Hard_Edge'),
  ('Q42316591', 'Largo Winch: Commando Sar (stylisé Largo Winch.//Commando Sar) est un jeu vidéo d''action-aventure développé par Rebellion et édité par Ubi Soft, sorti en 2002 sur PlayStation.

Il est tiré de la série télévisée du même nom.', 'https://fr.wikipedia.org/wiki/Largo_Winch_:_Commando_Sar'),
  ('Q1750390', 'Formula One 99 est un jeu vidéo de course de Formule 1 développé par Studio 33 et édité par Psygnosis pour la version PlayStation, et par Take 2 Interactive pour la version Windows. Sorti à l’automne 1999, c''est le quatrième opus de la série Formula One.', 'https://fr.wikipedia.org/wiki/Formula_One_99'),
  ('Q1643114', 'Future Cop L.A.P.D. est un jeu vidéo d''action, développé par EA Redwood Shores et édité par Electronic Arts, sorti en 1998. Étant dans la lignée des jeux de la série Strike (Desert Strike: Return to the Gulf, Jungle Strike, Urban Strike, Soviet Strike et Nuclear Strike), il fut même appelé Future Strike dans l''un des tout premiers trailer. Le joueur contrôle un robot, appelé X1-Alpha, spécialement conçu pour combattre le crime organisé en milieu urbain. Le scénario du jeu a lieu à Los Angeles au cours de l''année 2098.', 'https://fr.wikipedia.org/wiki/Future_Cop_L.A.P.D.'),
  ('Q2792119', 'X-Bladez: Inline Skater est un jeu vidéo de course de rollers développé par VisionScape Interactive et édité par Crave Entertainment, sorti en 2002 sur PlayStation et Game Boy Advance.', 'https://fr.wikipedia.org/wiki/X-Bladez:_Inline_Skater'),
  ('Q2816477', '3D Baseball est un jeu vidéo de baseball sorti en 1996 sur PlayStation et Saturn. Le jeu a été développé et édité par Crystal Dynamics.', 'https://fr.wikipedia.org/wiki/3D_Baseball'),
  ('Q2507115', 'Rollcage Stage II est un jeu vidéo de course sorti en 2000 sur PlayStation et PC. Il a été développe par Attention to Detail et édité par Psygnosis. Il s''agit de la suite de Rollcage.', 'https://fr.wikipedia.org/wiki/Rollcage_Stage_II'),
  ('Q45319510', 'Ford Racing est un jeu vidéo de course édité par Empire Interactive pour Windows et la PlayStation. La version Windows a été développée par Elite Systems et publiée le 2 novembre 2000, tandis que la version PlayStation a été développée par Toolbox Design et publiée le 29 janvier 2001.

C’était le premier jeu de la série de jeux vidéo Ford Racing et a reçu des critiques mitigées. Ford Racing est sorti sur PlayStation et téléchargeable sur le PlayStation Store en mai 2009, lui permettant d’être joué sur PlayStation 3 et PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Ford_Racing_(jeu_vid%C3%A9o)'),
  ('Q2485696', '4x4 World Trophy (ou Test Drive Off-Road 3 en dehors d''Europe) est un jeu vidéo de course édité sur PlayStation, Windows et Game Boy Color. Le jeu inclut plusieurs modes de jeu, comme le championnat, course rapide, multijoueur en écran partagé (2 joueurs).', 'https://fr.wikipedia.org/wiki/4x4_World_Trophy'),
  ('Q2495845', 'Philosoma est un jeu vidéo de type shoot them up développé par G-Artists et édité par Sony Computer Entertainment en 1995 sur PlayStation. Il a la particularité de proposer différentes phases de jeux alternant du shoot 2D à scrolling vertical et horizontal et du shoot 3D de type rail shooter.', 'https://fr.wikipedia.org/wiki/Philosoma'),
  ('Q1754058', 'Necronomicon: L''Aube des ténèbres, aussi appelé Necronomicon: The Dawning of Darkness, est un jeu vidéo d''aventure de type point and click sorti en 2000 sur Windows et PlayStation. Il est édité par Wanadoo en Europe et développé et édité par Cryo Interactive en Amérique du Nord. Le jeu s''inspire de la nouvelle L''Affaire Charles Dexter Ward de H. P. Lovecraft et de son univers.', 'https://fr.wikipedia.org/wiki/Necronomicon_:_L%27Aube_des_t%C3%A9n%C3%A8bres'),
  ('Q2803280', 'Destruction Derby Raw est un jeu vidéo de course automobile développé par Studio 33, sorti en 2000 sur PlayStation. Il fait partie de la série Destruction Derby.', 'https://fr.wikipedia.org/wiki/Destruction_Derby_Raw'),
  ('Q42266671', 'Auto Destruct est un jeu vidéo mêlant action-aventure et combat motorisé, développé par le studio suédois Neurostone, et édité par Electronic Arts. Il est publié sur console PlayStation en janvier 1998 en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Auto_Destruct'),
  ('Q2789783', 'Starblade est un jeu vidéo de type shoot ''em up développé et commercialisé par Namco en 1991 sur borne d''arcade. Il a été adapté sur 3DO et Mega-CD en 1994 et sur PlayStation (Starblade α, ou Starblade Alpha) en 1995.', 'https://fr.wikipedia.org/wiki/Starblade'),
  ('Q2811807', '1943 Kai: Midway Kaisen est un jeu vidéo de type shoot ''em up à scrolling vertical développé par Nelvana et édité par Capcom sur le système d''arcade Commando, sorti en 1988. Il a été conçu par Yoshiki Okamoto. Il est ensuite porté sur plusieurs plates-formes: PC-Engine, PlayStation, PlayStation 2, PlayStation Portable, Saturn, Xbox.', 'https://fr.wikipedia.org/wiki/1943_Kai:_Midway_Kaisen'),
  ('Q2526022', 'Front Mission est un tactical RPG de la série des Front Mission. Sorti le 24 février 1995 sur Super Famicom au Japon, il a été développé et distribué par Square Co., Ltd..', 'https://fr.wikipedia.org/wiki/Front_Mission_(jeu_vid%C3%A9o)'),
  ('Q2548236', 'Dead or Alive est un jeu vidéo de combat, diffusé sur arcade en 1996, puis commercialisé sur consoles Saturn en 1997 et sur PlayStation en 1998.

C''est un jeu de combat en 3D reprenant le principe de Virtua Fighter. Les combats ont lieu sur un ring dont les bords sont des zones spéciales, qui explosent et enlèvent de l''énergie à un joueur lorsqu''il y est projeté.

Ce jeu est devenu célèbre pour le niveau technique de ses combats et surtout pour son excellent système de contre. En appuyant sur le bouton de parade au bon moment, le coup de l''adversaire peut être retourné contre lui.', 'https://fr.wikipedia.org/wiki/Dead_or_Alive_(jeu_vid%C3%A9o)'),
  ('Q2524491', 'Darkstone est un jeu vidéo d''action / jeu de rôle développé par le studio Delphine Software International et édité en 1999 par Electronic Arts sur PC puis sur PlayStation en 2001. C''est un hack ''n'' slash fortement inspiré du premier Diablo de la série du même nom. La musique du jeu, The Darkstone will shine, est interprétée par la chanteuse française Audren.

En mars 2014, l''éditeur Anuman Interactive a lancé une nouvelle version du jeu sur iPhone, iPad et appareils Android, en collaboration avec Paul Cuisset, le créateur original du jeu.', 'https://fr.wikipedia.org/wiki/Darkstone'),
  ('Q2544337', 'Dragon Ball: Final Bout, est un jeu vidéo de combat par Bandai sur l''univers de Dragon Ball GT. Le jeu est distribué en 1997 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Dragon_Ball:_Final_Bout'),
  ('Q2529207', 'International Superstar Soccer Deluxe (souvent abrégé en ISS deLuxe) est un jeu vidéo de football de Konami sorti en 1995 (à ne pas confondre avec la série des ISS Pro) sur Super Nintendo, puis converti sur Mega Drive et PlayStation.

Il est la suite de International Superstar Soccer, sorti sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/International_Superstar_Soccer_Deluxe'),
  ('Q2526874', 'Aerobiz est un jeu vidéo de gestion de compagnie aérienne développé et édité par Koei, sorti en 1992 sur Mega Drive, Super Nintendo, FM Towns, PC-98 et X68000.

Le jeu a pour suite Aerobiz Supersonic, sorti en 1994.', 'https://fr.wikipedia.org/wiki/Aerobiz'),
  ('Q2816665', '4-4-2 Soccer est un jeu vidéo de football sorti en 1997 sur PlayStation et DOS. Le jeu est développé par Arc Developments et édité par Virgin Interactive.', 'https://fr.wikipedia.org/wiki/4-4-2_Soccer'),
  ('Q2822967', 'Aces of the Air est un simulateur de vol de combat sorti en 2002 sur PlayStation. Le jeu a été développé et édité par Agetec.', 'https://fr.wikipedia.org/wiki/Aces_of_the_Air'),
  ('Q2823637', 'Action Bass est un jeu vidéo de simulation de pêche sorti le 30 septembre 2000 sur PlayStation. Le jeu a été développé par Syscom Entertainment et édité par Take Two Interactive.', 'https://fr.wikipedia.org/wiki/Action_Bass'),
  ('Q2823646', 'Action Man: Destruction X est un jeu vidéo sorti en 2000 sur PlayStation et en 2001 sur PC.

Le jeu exploite la licence du jouet Action Man.', 'https://fr.wikipedia.org/wiki/Action_Man:_Destruction_X'),
  ('Q2823769', 'Actua Pool (aussi appelé Pool:shark ou encore Ultimate 8-Ball) est un jeu vidéo de billard américain développé et édité par Gremlin Interactive en 1999 sur PlayStation et PC. Le jeu a été réédité sur Nintendo DS en 2007. Il fait partie de la série Actua Sports.', 'https://fr.wikipedia.org/wiki/Actua_Pool'),
  ('Q2823774', 'Actua Soccer est une série de jeux vidéo de football développée par Gremlin Interactive. La série est constituée de quatre titres sortis entre 1995 et 1999. Le jeu officiel de l''Euro 1996, réalisé par Gremlin Interactive ne fait pas partie de la série des Actua Soccer.', 'https://fr.wikipedia.org/wiki/Actua_Soccer'),
  ('Q2860039', 'Archer MacLean''s 3D Pool est un jeu vidéo de billard sorti en 2003 sur PlayStation et Game Boy Advance. Le jeu a été développé et édité par Ignition Entertainment.', 'https://fr.wikipedia.org/wiki/Archer_MacLean%27s_3D_Pool'),
  ('Q2823768', 'Actua Golf est une série de jeux vidéo de golf développé par Gremlin Graphics entre 1996 et 1998. Elle s''inscrit dans la lignée des Actua Sports.', 'https://fr.wikipedia.org/wiki/Actua_Golf'),
  ('Q2819688', 'A Collection of Classic Games from the Intellivision (souvent abrégé en Intellivision Classics) est une compilation de jeu vidéo éditée en 1999 par Activision sur PlayStation.

La compilation regroupe 30 différents jeux sortis sur Intellivision, issus du catalogue Intellivision Productions, émulés et adaptés à la manette de la PlayStation. Chaque jeu est introduit par une courte cinématique et un écran récapitulatif des commandes. Des interviews des programmeurs originaux sont proposées en bonus.', 'https://fr.wikipedia.org/wiki/A_Collection_of_Classic_Games_from_the_Intellivision'),
  ('Q2816658', '3×3 Eyes: Tenrinō Genmu est un jeu vidéo de rôle sorti au Japon en 1997 et fonctionne sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/3%C3%973_Eyes:_Tenrin%C5%8D_Genmu'),
  ('Q2862795', 'Armorines: Project S.W.A.R.M. est un jeu vidéo de tir à la première personne sorti en 1999 sur Nintendo 64, Game Boy Color et PlayStation. Le jeu a été développé et édité par Acclaim. Il s''agit d''une adaptation du comics Armorines (en).

La version Game Boy du jeu est un jeu de tir à la troisième personne en 2D.', 'https://fr.wikipedia.org/wiki/Armorines:_Project_S.W.A.R.M.'),
  ('Q2823648', 'Action Man: Mission Xtreme (Action Man: Operation Extreme aux États-Unis) est un jeu vidéo d''action sorti en 1999 sur PlayStation et Windows. Le jeu a été développé par Blitz Games et édité par Hasbro Interactive.', 'https://fr.wikipedia.org/wiki/Action_Man:_Mission_Xtreme'),
  ('Q2825669', 'Aerosmith: Quest for Fame est un jeu de rythme développé par Virtual Music Entertainment et édité par Namco, sorti en 1997.', 'https://fr.wikipedia.org/wiki/Aerosmith:_Quest_for_Fame'),
  ('Q2836836', 'Alien Resurrection est un jeu vidéo sorti sur PlayStation. Le jeu reprend l''univers du film de 1997, Alien, la résurrection, de Jean-Pierre Jeunet et prend la forme d''un jeu de tir à la première personne.

Le jeu reprend de nombreux détails du film (notamment dans les armes et décors) et permet d''incarner différents personnages: Ripley 8, Call, Di Stephano et Christie.

Un portage du jeu sur Dreamcast a été annulé.', 'https://fr.wikipedia.org/wiki/Alien_Resurrection_(jeu_vid%C3%A9o)'),
  ('Q2849434', 'Angelique Special 2 est un jeu vidéo japonais de simulation de drague de la franchise Angelique, sorti en 1996.', 'https://fr.wikipedia.org/wiki/Angelique_Special_2'),
  ('Q2823180', 'Acid est un jeu vidéo de puzzle sorti en 1999 sur PlayStation uniquement au Japon. Le jeu a été développé et édité par Taki.', 'https://fr.wikipedia.org/wiki/Acid_(jeu_vid%C3%A9o)'),
  ('Q2818204', '70''s Robot Anime: Geppy-X est un jeu vidéo shoot them up sorti en 1999 sur PlayStation uniquement au Japon. Le jeu a été développé et édité par Aroma.', 'https://fr.wikipedia.org/wiki/70%27s_Robot_Anime:_Geppy-X'),
  ('Q2818869', 'A-Train IV est le nom commercial d''A Ressha de Ikō IV.

Le 4e épisode de la série A-Train d''Artdink, est sorti sur PC-98, FM Towns et Windows 3.1 en décembre 1993 et fut décliné sur PlayStation en décembre 1994 au Japon. Une seconde version, sous-titrée Evolution Global, est ressorti sur PlayStation en décembre 1995, laquelle a été commercialisé en occident en 1996, sous le titre A-Train.

L''adaptation française et la version PC de cette version ont été réalisés par Infogrames en 1994. Les portages ont été faits pour l’Espagne, l’Italie, l’Allemagne, l’Angleterre et les États-Unis. Dans la version américaine nommée "CEO", l''acteur James Coburn jouait le PDG de la compagnie A4.', 'https://fr.wikipedia.org/wiki/A-Train_IV'),
  ('Q2862835', 'Army Men: Air Attack (sorti sous le titre Army Men: Air Combat sur Nintendo 64 et Game Boy Color) est un jeu vidéo de type shoot ''em up développé et édité par The 3DO Company, sorti en 1999 sur PlayStation, Nintendo 64, Game Boy Color et Windows.', 'https://fr.wikipedia.org/wiki/Army_Men:_Air_Attack'),
  ('Q2869880', 'Attack of the Saucerman! est un jeu vidéo d''action développé par Psygnosis et édité par Sony Computer Entertainment, sorti en 1999 sur PlayStation. Il a été adapté sous Windows en 2000.', 'https://fr.wikipedia.org/wiki/Attack_of_the_Saucerman!'),
  ('Q2891772', 'BattleTanx: Global Assault est un jeu vidéo d''action sorti en 1999 sur Nintendo 64 et en 2000 sur PlayStation. Le jeu a été développé et édité par 3DO.

Il s''agit de la suite de BattleTanx.', 'https://fr.wikipedia.org/wiki/BattleTanx:_Global_Assault'),
  ('Q2891786', 'Battle Arena Toshinden 3 est jeu de combat en 3D développé par Tamsoft et Takara en 1996 sur PlayStation. Le titre est édité par Takara au Japon, par Playmates Interactive en Amérique du Nord et par Sony Interactive Entertainment en Europe. Le jeu est exclusif à la PlayStation, première fois qu''un épisode de la série Toshinden ne soit pas porté sur Sega Saturn et Windows.', 'https://fr.wikipedia.org/wiki/Battle_Arena_Toshinden_3'),
  ('Q2892932', 'Beat Planet Music est un jeu de rythme sorti sur PlayStation le 20 janvier 2000 au Japon.', 'https://fr.wikipedia.org/wiki/Beat_Planet_Music'),
  ('Q2875256', 'Azure Dreams est un jeu vidéo de rôle sorti en 1998 sur PlayStation et en 2000 sur Game Boy Color. Il a pour suite Tao''s Adventure: Curse of the Demon Seal.', 'https://fr.wikipedia.org/wiki/Azure_Dreams'),
  ('Q2862836', 'Army Men: Sarge''s Heroes est un jeu vidéo d''action développé et édité par The 3DO Company en 2000 sur Dreamcast, Nintendo 64, PlayStation et Windows.', 'https://fr.wikipedia.org/wiki/Army_Men:_Sarge%27s_Heroes'),
  ('Q2862833', 'Army Men: Sarge''s Heroes 2 est un jeu vidéo de tir à la troisième personne sorti en 2000 sur Nintendo 64, PlayStation, Game Boy Color et en 2001 sur PlayStation 2. Le jeu a été développé et édité par 3DO.

La version Game Boy est un shoot them up en 2D isométrique.', 'https://fr.wikipedia.org/wiki/Army_Men:_Sarge%27s_Heroes_2'),
  ('Q2884202', 'Barbie aventurière (Barbie Explorer) est un jeu vidéo d''action développé par Runecraft et édité par Vivendi Games, sorti sur PC et PlayStation en 2001.

Le but du jeu est de retrouver des morceaux du miroir mystérieux.

Le jeu est jouable seul ou à deux.', 'https://fr.wikipedia.org/wiki/Barbie_aventuri%C3%A8re'),
  ('Q2878054', 'Baby Universe (aussi appelé 3D-Kaleidoscope Baby Universe) est un jeu vidéo de musique interactive sorti en 1997 sur PlayStation. Le jeu a été édité par Sony Computer Entertainment Incorporated.', 'https://fr.wikipedia.org/wiki/Baby_Universe'),
  ('Q2891582', 'Batman of the Future: Return of the Joker (Batman Beyond: Return of the Joker aux États-Unis) est un jeu vidéo beat them all sorti en 2000 sur Nintendo 64, PlayStation et Game Boy Color. Le jeu a été développé par Kemco et édité par Ubisoft.

Le jeu est basé sur le film d''animation Batman, la relève: Le Retour du Joker.', 'https://fr.wikipedia.org/wiki/Batman_of_the_Future:_Return_of_the_Joker'),
  ('Q2574957', 'Threads of Fate (Dewprism au Japon) est un jeu vidéo de type action-RPG développé et édité par Square en 1999 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Threads_of_Fate'),
  ('Q2569791', 'Pac-Man World est un jeu vidéo de plate-forme développé et édité sur PlayStation en 1999 par Namco. Il s''agit du premier jeu vidéo de la série Pac-Man World et célèbre par la même occasion le 20e anniversaire de la naissance de Pac-Man.

Ce jeu a été édité sur Game Boy Advance en 2004.', 'https://fr.wikipedia.org/wiki/Pac-Man_World'),
  ('Q2576094', 'The X-Files, le jeu (The X-Files Game) est un jeu vidéo d''aventure développé par HyperBole Studios, sorti en 1998. Il s''agit d''un point & click dans lequel on incarne Craig Willmore, un jeune agent du FBI. Celui-ci doit résoudre une affaire qui concerne la mystérieuse disparition des agents Fox Mulder et Dana Scully (les personnages principaux de la série). L''agent Willmore évolue dans divers environnements, où il récolte des indices et discute avec d''autres personnages lors des cinématiques en full motion video, c.-à-d. jouées par de vrais acteurs. Le jeu se déroule entre les épisodes 22 et 23 de la saison 3 de la série (avril 1996).', 'https://fr.wikipedia.org/wiki/The_X-Files,_le_jeu'),
  ('Q2559819', 'Marvel Super Heroes est un jeu vidéo de combat développé et édité par Capcom en octobre 1995 sur CP System II. Inspiré de la saga Infinity Gauntlet, ce jeu a été produit par Capcom en hommage à Jack Kirby, un des plus grands illustrateurs/scénaristes américain de comic, décédé en 1994.', 'https://fr.wikipedia.org/wiki/Marvel_Super_Heroes'),
  ('Q2580313', 'The X-Files: Unrestricted Access est un jeu vidéo interactif et le premier jeu vidéo basé sur la série télévisée X-Files: Aux frontières du réel. On y trouve des informations sur des personnages principaux, secondaires et des figurants, une fiche des épisodes de la saison 1 à 4. Sur les fiches de chaque épisode il y a des liens vers le mutant, le lieu d''investigation, les victimes, les témoins et les dissimulateurs de fait. Chaque fiche est très détaillée et comporte une image.', 'https://fr.wikipedia.org/wiki/The_X-Files:_Unrestricted_Access'),
  ('Q2568519', 'Digimon Rumble Arena, ou Digimon Tamers Battle Evolution au Japon, est un jeu vidéo de combat et d''action, distribué et développé par Bandai, en association avec Hudson Soft, sur console PlayStation. Il est initialement publié le 6 décembre 2001 au Japon, puis adapté par Infogrames en Amérique du Nord le 24 février 2002 et exporté en Europe la même année.

Partie intégrante de la série des jeux vidéo inspirée de la franchise Digimon, Digimon Rumble Arena met en avant ses créatures numériques accompagnées d''éléments d''un jeu vidéo de combat multi-plateformes. Le joueur incarne l''un des personnages jouables présents dans le jeu et doit combattre plusieurs de ses semblables contrôlés par l''intelligence artificielle à un contre un dans différentes arènes. Un mini-jeu aléatoire apparaît dans le mode « un joueur » après trois combats, au milieu d''un cycle de six combats.', 'https://fr.wikipedia.org/wiki/Digimon_Rumble_Arena'),
  ('Q2568028', 'Yu-Gi-Oh! Forbidden Memories, est un jeu vidéo, sorti en 1999 au Japon et en 2002 aux États-Unis et en Europe sur PlayStation, édité par Konami inspiré de la franchise japonaise Yu-Gi-Oh!. Le jeu se déroule en Égypte antique.', 'https://fr.wikipedia.org/wiki/Yu-Gi-Oh!_Forbidden_Memories'),
  ('Q2562250', 'The Legend of Dragoon est un jeu vidéo de rôle développé et édité par Sony Computer Entertainment en 1999 sur PlayStation.

Le jeu se déroule dans un univers d''heroic fantasy où dragons, humains et magie se côtoient. Les « dragoons », transformations partielles de certains hommes, sont faits pour contrôler les dragons et se battre à leur côtés. Le jeu, qui tient sur 4 CD-ROM, possède une durée de vie importante.', 'https://fr.wikipedia.org/wiki/The_Legend_of_Dragoon'),
  ('Q2571444', 'Clock Tower 2 est un jeu vidéo de type survival horror sorti en 1996 au japon sur PlayStation, en 1997 en Amérique du Nord et en 1998 en Europe. Il n''est connu sous ce nom qu''au Japon. Dans les autres pays, il est connu sous le nom de Clock Tower. Il s''agit de la suite directe de Clock Tower, sorti en 1995 sur Super Nintendo. Deux nouvelles et une dramatique radio furent créées à l''occasion de la sortie du jeu mais ne furent disponibles qu''au Japon. Le jeu devait être porté sur Saturn et Nintendo 64 mais il fut finalement décidé de ne le créer que pour la PlayStation.', 'https://fr.wikipedia.org/wiki/Clock_Tower_2'),
  ('Q2562672', 'FIFA 2000 (ou FIFA 2000 - Major League Soccer aux États-Unis et FIFA 2000 - European League Soccer au Japon) est un jeu vidéo de football sorti en 1999 pour les plateformes PlayStation, Windows et Game Boy Color. Le jeu a été édité par EA Sports et est commenté par Thierry Gilardi et Laurent Paganelli avec notamment la présence de Jean-Luc Reichmann au début de tout match.

Ce jeu avait comme thème principal « It''s Only Us » de Robbie Williams, mais également d''autres titres comme « Stop the Rock » d''Apollo 440 ou encore « Sell Out » de Reel Big Fish.', 'https://fr.wikipedia.org/wiki/FIFA_2000'),
  ('Q2963395', 'Chicken Run est un jeu vidéo d''action développé par Blitz Games et sorti sur Dreamcast, Game Boy Color, PlayStation et PC (Windows) en 2000. Le jeu est adapté du film Chicken Run et propose d''incarner quatre de ses personnages principaux.', 'https://fr.wikipedia.org/wiki/Chicken_Run_(jeu_vid%C3%A9o)'),
  ('Q2963753', 'Chine: Intrigue dans la Cité interdite est un jeu vidéo d''aventure développé par Cryo Interactive, sorti en 1998 sous Windows et sur PlayStation.', 'https://fr.wikipedia.org/wiki/Chine_:_Intrigue_dans_la_Cit%C3%A9_interdite'),
  ('Q2932062', 'CT Special Forces 3: Bioterror est un jeu vidéo de type run and gun développé par LSP Games sorti sur Game Boy Advance et PlayStation en 2004. Le jeu devait sortir en Amérique du Nord via l''éditeur Hip Games sous le titre CT Special Forces 3: Navy Ops mais a été annulé.', 'https://fr.wikipedia.org/wiki/CT_Special_Forces_3:_Bioterror'),
  ('Q2955895', 'Championship Surfer est un jeu vidéo de surf sorti en 2000 sur Dreamcast, PlayStation et Windows.', 'https://fr.wikipedia.org/wiki/Championship_Surfer'),
  ('Q2966741', 'Chronicles of the Sword est un jeu vidéo d''aventure développé par Synthetic Dimensions et édité par Psygnosis en 1996 sur DOS et PlayStation. L''histoire prend place dans l''Angleterre du Roi Arthur.', 'https://fr.wikipedia.org/wiki/Chronicles_of_the_Sword'),
  ('Q2927403', 'Bubsy 3D: Furbitten Planet, plus simplement connu sous le nom de Bubsy 3D, est un jeu vidéo de plates-formes sorti en septembre 1996 sur PlayStation par Accolade en Amérique du Nord et en août 1997 par Telstar en Europe. Quatrième opus de la série Bubsy, son nom est une parodie du titre du film Planète interdite (Forbidden Planet en anglais). Le joueur incarne Bubsy, un lynx roux anthropomorphe dans dix-huit niveaux (dont trois aquatiques) et quatre boss (dont le boss final).', 'https://fr.wikipedia.org/wiki/Bubsy_3D:_Furbitten_Planet'),
  ('Q2927045', 'Brunswick Circuit Pro Bowling est un jeu vidéo de bowling sorti en 1998 sur Nintendo 64, PlayStation et Windows. Le jeu a été développé par Point of View et édité par THQ.', 'https://fr.wikipedia.org/wiki/Brunswick_Circuit_Pro_Bowling'),
  ('Q2909719', 'Bomberman Land est un jeu vidéo de type party game sorti sur PlayStation en 2000 au Japon uniquement. Il s''agit du premier jeu de la série des Bomberman Land et il est sorti pour commémorer les 15 ans de la série Bomberman.

Le jeu est également disponible en téléchargement sur le PlayStation Store du Japon depuis 2008.', 'https://fr.wikipedia.org/wiki/Bomberman_Land_(jeu_vid%C3%A9o,_2000)'),
  ('Q2909732', 'Bomberman World est un jeu vidéo d''action édité par Sony Computer Entertainment et développé par Hudson Soft. Il est sorti en 1992 sur borne d''arcade et en 1998 sur PlayStation. Il s''agit du premier Bomberman à sortir sur cette console. Le jeu propose un mode multijoueur jouable jusqu''à 5 joueurs simultanément, 12 cartes différentes et 3 modes de jeu différents.', 'https://fr.wikipedia.org/wiki/Bomberman_World'),
  ('Q2904020', 'BioF.R.E.A.K.S. est un jeu vidéo de combat sorti en 1998 sur Nintendo 64, PlayStation et arcade. Le jeu a été développé par Saffire et édité par Midway.', 'https://fr.wikipedia.org/wiki/BioF.R.E.A.K.S.'),
  ('Q2913706', 'Super Street Fighter II: The New Challengers est un jeu vidéo de combat en un contre un développé et édité par Capcom sur le nouveau système d''arcade CP System II en septembre 1993. C''est un jeu de la franchise Street Fighter, et plus précisément la quatrième mouture de Street Fighter II publiée par Capcom. Il s''agit, cependant et surtout, du portage du jeu phare sur le système CPS2, là où les trois itérations précédentes étaient sorties sur le système original CPS1.', 'https://fr.wikipedia.org/wiki/Super_Street_Fighter_II:_The_New_Challengers'),
  ('Q2905262', 'Black/Matrix 00 est un jeu de rôle tactique développé par Flight-Plan et publié par NEC InterChannel sur PlayStation et sorti le 13 mai 2004 au Japon. Ce jeu est une adaptation de Black/Matrix Zero sur Game Boy Advance avec des scènes supplémentaires et une histoire plus détaillé.', 'https://fr.wikipedia.org/wiki/Black/Matrix_00'),
  ('Q2906222', 'Blast Radius est un jeu vidéo de combat spatial développé par Psygnosis Camden Studio et édité par Psygnosis, sorti en 1998 sur PlayStation.

Le jeu est assez similaire à Colony Wars (1997).', 'https://fr.wikipedia.org/wiki/Blast_Radius'),
  ('Q2912698', 'Ganbare Goemon: Uchū Kaizoku Akogingu est un jeu d''action-aventure développé et édité par Konami paru sur PlayStation au Japon exclusivement le 22 mars 1996.', 'https://fr.wikipedia.org/wiki/Ganbare_Goemon:_Uch%C5%AB_Kaizoku_Akogingu'),
  ('Q2909728', 'Bomberman Party Edition est un jeu vidéo d''action développé par Hudson Soft et édité par Avalon Interactive. Il est sorti sur PlayStation en 1998 au Japon, en 1999 en Europe et en 2000 aux États-Unis. Il fait partie de la série des Bomberman.

Bomberman Party Edition est également disponible en téléchargement sur le PlayStation Network sur la PlayStation 3 depuis 2008 au Japon.', 'https://fr.wikipedia.org/wiki/Bomberman_Party_Edition'),
  ('Q2905269', 'Black/Matrix est un jeu de rôle tactique développé par Flight-Plan et publié par NEC InterChannel sur Saturn et sorti le 26 août 1998 au Japon. Ce jeu a été ensuite adapté sur PlayStation en 2000 sous le nom de Black/Matrix Cross.', 'https://fr.wikipedia.org/wiki/Black/Matrix_(jeu_vid%C3%A9o)'),
  ('Q2911866', 'Bottom of the 9th est un jeu vidéo de baseball sorti en 1996 sur Nintendo 64, Saturn et PlayStation. Le jeu a été développé et édité par Konami.', 'https://fr.wikipedia.org/wiki/Bottom_of_the_9th'),
  ('Q53678012', 'Alexandra Ledermann: Équitation Passion, ou simplement Alexandra Ledermann, originellement intitulé Riding Star dans sa version internationale, est un jeu vidéo d''équitation, publié en 1998, en Amérique du Nord. En France, il est édité par Midas Interactive, et publié le 14 septembre 2000; il appartient à la série série Alexandra Ledermann.', 'https://fr.wikipedia.org/wiki/Alexandra_Ledermann_:_%C3%89quitation_Passion'),
  ('Q51516642', 'Beach Volleyball (Power Spike Pro Beach Volleyball en Amérique du Nord) est un jeu vidéo de sport (beach-volley) développé par Carapace et édité par Infogrames, sorti en 2000 sur Windows, PlayStation et Game Boy Color. Le jeu s''appelle Beach ''n Ball sur Game Boy Color.', 'https://fr.wikipedia.org/wiki/Beach_Volleyball'),
  ('Q51485736', 'Smash Court 3 est un jeu vidéo de sport (tennis) développé et édité par Namco, sorti en 2000 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Smash_Court_3'),
  ('Q53715664', 'Les 101 Dalmatiens 2: Sur la trace des héros (Disney''s 101 Dalmatians II: Patch''s London Adventure) est un jeu vidéo d''action, publié en 2003 sur console PlayStation, édité par Disney Interactive, Inc.et Eidos Interactive.', 'https://fr.wikipedia.org/wiki/Les_101_Dalmatiens_2_:_Sur_la_trace_des_h%C3%A9ros_(jeu_vid%C3%A9o)'),
  ('Q53788079', 'All Star Racing est un jeu vidéo de course, développé par Mud Duck Productions et Kung Fu Games, publié en 2002. Il a pour suite All Star Racing 2.', 'https://fr.wikipedia.org/wiki/All_Star_Racing'),
  ('Q53715606', 'Aero Dive, intitulé Skydiving Extreme en Amérique du Nord, est un jeu vidéo de sport, publié en 2000, au Japon, développé par Natsume, Inc. et distribué par Metro Corporation.', 'https://fr.wikipedia.org/wiki/Aero_Dive'),
  ('Q53788101', 'All-Star 1997 Featuring Frank Thomas, également intitulé All-Star Baseball ''97, est un jeu vidéo de sport, basé sur le baseball, développé par Iguana Entertainment et édité par Acclaim Entertainment, sorti en 1997 en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/All-Star_1997_Featuring_Frank_Thomas'),
  ('Q52568231', 'Global Domination est un jeu vidéo de stratégie au tour par tour développé et édité par Psygnosis, sorti en 1998 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/Global_Domination_(jeu_vid%C3%A9o,_1998)'),
  ('Q53678416', 'Alexandra Ledermann 2: Équitation Compétition, ou simplement Alexandra Ledermann 2 est un jeu vidéo d''équitation, développé par Midas Interactive et édité par Ubisoft. Il est publié en octobre 2001 sur Microsoft Windows et console PlayStation; il appartient à la série série Alexandra Ledermann.', 'https://fr.wikipedia.org/wiki/Alexandra_Ledermann_2_:_%C3%89quitation_Comp%C3%A9tition'),
  ('Q50376275', 'Uprising (ou Uprising: Join or Die) est un jeu vidéo de stratégie et d’action développé par Cyclone Studios et publié par The 3DO Company sur PC en 1997. Le jeu se déroule dans un univers de science-fiction dans lequel le joueur incarne un rebelle luttant contre un empire tyrannique. Le jeu combine des éléments de jeu de stratégie en temps réel et de jeu de simulation de char d''assaut. Le joueur est en effet aux commandes d’un char de combat futuriste, en vue à la première personne, qui lui permet de participer aux combats mais aussi d’ordonner la construction d’infrastructure, de gérer ses ressources en énergie, de téléporter des troupes, d’ordonner un bombardement ou de diriger une attaque. Le jeu propose une campagne constitué d’une trentaine de missions dans lesquels le joueur débarque sur différentes planètes avec pour objectif de détruire la base ennemie. Une fois arrivé à destination, il peut demander à son vaisseau-mère de déposer ses premières infrastructures sur un emplacement destiné à cet effet et commencer à collecter la seule ressource disponible dans le jeu, l’énergie. Grâce à cette énergie, il peut ordonner l’envoi d’autres constructions, comme des casernes ou des usines, pour produire de nouvelles unités.', 'https://fr.wikipedia.org/wiki/Uprising_(jeu_vid%C3%A9o)'),
  ('Q53935553', 'Baseball 2000, ou Microsoft Baseball 2000 sur sa version PC, est un jeu vidéo de sport, édité par Microsoft Corporation et publié en 1999 sur Microsoft Windows et console PlayStation.', 'https://fr.wikipedia.org/wiki/Baseball_2000'),
  ('Q53866679', 'Animal Snap: Rescue Them 2 By 2, ou simplement Animal Snap, est un jeu vidéo de puzzle, publié en 2002 sur PlayStation et Game Boy Advance, développé par Awesome Developments.', 'https://fr.wikipedia.org/wiki/Animal_Snap:_Rescue_Them_2_By_2'),
  ('Q53866684', 'Aironauts est un jeu vidéo de tir, publié sur console PlayStation, en Europe, développé par Red Lemon Studios et distribué par Take-Two Interactive. En France, à sa sortie en 1999, le jeu coûte 349 francs.', 'https://fr.wikipedia.org/wiki/Aironauts'),
  ('Q53866674', 'The Amazing Virtual Sea-Monkeys est un jeu de puzzle, publié sur consoles PlayStation et Game Boy Advance, et édité par Conspiracy Entertainment Corp. et Red Cap Software GmbH.', 'https://fr.wikipedia.org/wiki/The_Amazing_Virtual_Sea-Monkeys'),
  ('Q136399886', 'SeaBass Fishing 2 est un jeu vidéo de pêche développé par A-Wave inc. et initialement édité par Victor Interactive Software. Le jeu n''est sorti qu''au Japon, d''abord sur Saturn le 25 avril 1997 puis sur PlayStation le 25 septembre 1997.

Il s''agit de la suite de Sea Bass Fishing, sorti l''année précédente exclusivement sur Sega Saturn.', 'https://fr.wikipedia.org/wiki/SeaBass_Fishing_2'),
  ('Q3016352', 'Darkstalkers: The Night Warriors est un jeu vidéo de combat développé et édité par Capcom en juillet 1994 sur CP System II. C''est le premier jeu de la série Darkstalkers.', 'https://fr.wikipedia.org/wiki/Darkstalkers:_The_Night_Warriors'),
  ('Q55381975', 'Santa Claus Saves the Earth (littéralement Le père Noël sauve la Terre en français) est un jeu vidéo d''action et plate-formes sorti en 2002 sur PlayStation et Game Boy Advance. Le jeu a été développé par Ivolgamus (actuellement connu comme Nordcurrent) et édité par Telegames.', 'https://fr.wikipedia.org/wiki/Santa_Claus_Saves_the_Earth'),
  ('Q2988273', 'Vigilante 8 est un jeu vidéo de combat motorisé, développé par Luxoflux, sorti sur PlayStation, Nintendo 64 et Game Boy Color en 1999. C''est le spin-off du jeu PC Interstate ''76. Le jeu possède une suite: Vigilante 8: Second Offense, sorti sur Dreamcast, PlayStation et Nintendo 64.', 'https://fr.wikipedia.org/wiki/Vigilante_8'),
  ('Q3007689', 'Disruptor est un jeu vidéo développé par Insomniac Games. Il s’agit d’un jeu de tir à la première personne sorti sur PlayStation le 30 novembre 1996. Il est édité par Universal Interactive Studios aux États-Unis et distribué par Interplay Productions en Europe et au Japon. L''accueil réservé par la critique est positif; toutefois, le jeu subit un échec commercial.', 'https://fr.wikipedia.org/wiki/Disruptor');

insert into import_summary (wikidata_id, summary, source) values
  ('Q3008121', 'CyberTiger est un jeu vidéo de golf sorti en 1999 et fonctionne sur Nintendo 64, PlayStation et Game Boy Color. Le jeu a été développé par Saffire Corporation et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/CyberTiger'),
  ('Q3002413', 'Creatures est un jeu vidéo de simulation de vie sorti en novembre 1996.', 'https://fr.wikipedia.org/wiki/Creatures_(jeu_vid%C3%A9o,_1996)'),
  ('Q2995315', 'Constructor est un jeu vidéo combinant des éléments de jeu de stratégie en temps réel et city-builder publié en 1997 sur PlayStation et PC. Il a été développé par System 3 et édité par Acclaim. Une suite nommée Constructor: Street Wars (appelée Mob Rule aux États-Unis) est sortie en 1999, sans rencontrer le succès escompté.

Le jeu ressort sur PlayStation 3 et PlayStation Vita via le PlayStation Network le 16 juillet 2009.

System 3 annonce le développement d''une version haute-définition de Constructor dont la sortie est prévue initialement pour le 29 janvier 2016. Le jeu sera reporté à plusieurs reprises, d''abord pour avril 2016 puis à l''été 2016 et enfin au 31 janvier 2017.', 'https://fr.wikipedia.org/wiki/Constructor'),
  ('Q56277492', 'Power Move Pro Wrestling est un jeu vidéo de catch développé par Yuke''s, sorti sur PlayStation en 1995 au Japon par Tomy et en 1996 aux États-Unis par Activision.', 'https://fr.wikipedia.org/wiki/Power_Move_Pro_Wrestling'),
  ('Q3004206', 'Wipeout 2097 (stylisé wipEout 2097), ou Wipeout XL aux États-Unis, est un jeu vidéo créé par la société anglaise Psygnosis, sorti en 1996. Il s''agit du second épisode de la série Wipeout, basée sur des courses futuristes aux commandes de vaisseaux ultra-rapides et armés. L''action se déroule en l''an 2097 et met en scène la ligue de course anti-gravité F5000.

À l''origine édité sur PlayStation en 1996, le titre est adapté l''année suivante sur PC et Saturn, puis sur Amiga et Macintosh. Il connait un succès critique et populaire, et reste considéré comme un opus emblématique de la série. Le jeu pousse plus loin la formule originale: il présente des évolutions importantes dans le gameplay, comme l''apparition d''une jauge d''énergie pour les vaisseaux, une réalisation visuelle plus élaborée, avec la participation de l''agence The Designers Republic, et une bande-son tonitruante, qui contient des morceaux d''artistes influents de la scène électronique britannique, comme The Chemical Brothers, Future Sound of London et The Prodigy.', 'https://fr.wikipedia.org/wiki/Wipeout_2097'),
  ('Q2985661', 'Chocobo Racing est un jeu vidéo de course développé et édité par Square, sorti en 1999 sur PlayStation.

Les pilotes sont issus de l''univers Final Fantasy: un Chocobo, un Mog, un Golem, un Gobelin, un Mage noir, un Mage blanc, un gros Chocobo et un Behemoth.', 'https://fr.wikipedia.org/wiki/Chocobo_Racing'),
  ('Q3008147', 'Cyberbots: Fullmetal Madness est un jeu vidéo de combat développé et édité par Capcom en avril 1995 sur CP System II. Il a été porté sur PlayStation et Saturn en 1997 au Japon uniquement.', 'https://fr.wikipedia.org/wiki/Cyberbots:_Fullmetal_Madness'),
  ('Q54086501', 'Art Camion Sugorokuden est un jeu vidéo de type stratégie, publié en 2000 uniquement au Japon sur console PlayStation. Il est réédité dix ans plus tard sur PlayStation Network le 22 décembre 2010 au Japon, et en 2012 à l''international pour $5,99.', 'https://fr.wikipedia.org/wiki/Art_Camion_Sugorokuden'),
  ('Q53938350', 'Agile Warrior F-111X est un jeu vidéo de simulation, publié en 1996 sur console PlayStation et Microsoft Windows. Il est développé par Black Ops, et édité par Virgin Interactive.', 'https://fr.wikipedia.org/wiki/Agile_Warrior_F-111X'),
  ('Q55507392', 'Breakout est un jeu vidéo de type casse-briques développé par Supersonic Software et édité par Hasbro Interactive, sorti en 2000 sur Windows, Mac et PlayStation.', 'https://fr.wikipedia.org/wiki/Breakout_(jeu_vid%C3%A9o,_2000)'),
  ('Q54106115', 'Dezaemon Kids! est un jeu vidéo de tir, uniquement publié en 1998 au Japon, sur console PlayStation, développé et édité par Athena Co., Ltd. Le jeu est réédité à l''international avec les textes originaux japonais, en 2011 sur PlayStation 3 et PlayStation Portable, et en 2012 sur PlayStation Vita. Il fait partie de la série Dezaemon.', 'https://fr.wikipedia.org/wiki/Dezaemon_Kids!'),
  ('Q52058', 'The Neverhood (sorti au Japon sous le titre Klaymen Klaymen) est un jeu d''aventure en pointer-et-cliquer édité en 1996; créé par l''animateur Douglas TenNapel, il a été entièrement réalisé en animation de pâte à modeler. Plusieurs suites ont été éditées, mais ce ne sont pas des jeux d''aventure: Skullmonkeys, BoomBots, et Klaymen Gun-Hockey. Il a également une suite spirituelle: Armikrog.

Le compositeur Terry Scott Taylor a compilé la musique du jeu et des suites Skullmonkeys et BoomBots dans un double album publié en 2004: Imaginarium: Songs from the Neverhood.', 'https://fr.wikipedia.org/wiki/The_Neverhood'),
  ('Q44346', 'James Pond 2: Codename RoboCod est un jeu vidéo de plates-formes développé par Vectordean et édité par Millennium Interactive en 1991 sur Amiga 500 et Atari ST. Le jeu a été adapté sur Amiga 1200, Amiga CD32, Commodore 64, DOS, Game Gear, Mega Drive et Super Nintendo (Super James Pond II). Dans les années 2000, Play It a commercialisé des versions Game Boy Advance, PlayStation, Nintendo DS et PlayStation 2. Aux États-Unis, la version Super Nintendo est connue sous le nom Super James Pond.

Dans cette aventure, qui fait suite à James Pond: Underwater Agent, James Pond, alias RoboCod, doit déjouer les tours de Dr Maybe qui a plastiqué les fabriques de jouets situées au Pôle Nord.', 'https://fr.wikipedia.org/wiki/James_Pond_2:_Codename_RoboCod'),
  ('Q19431', 'Grand Theft Auto: London 1969, de son nom complet Grand Theft Auto, Mission Pack #1: London 1969, est une extension du jeu vidéo Grand Theft Auto développée par Rockstar Canada. Il s''agit du deuxième jeu vidéo de la série du même nom.

London 1969 est commercialisé le 31 mars 1999 sur Microsoft Windows, et le 30 avril 1999 sur PlayStation. Le jeu utilise le même moteur que le jeu vidéo Grand Theft Auto, d''où les graphismes et le gameplay similaires à celui du premier opus. Comme GTA, le mission pack se divise en deux parties. London 1969 est la première extension commercialisée sur PlayStation. Le pack devient une des meilleures ventes au Royaume-Uni.', 'https://fr.wikipedia.org/wiki/Grand_Theft_Auto:_London_1969'),
  ('Q54839', 'Star Wars Episode I: Jedi Power Battles est un jeu vidéo d''action développé et édité par LucasArts, inspiré de la saga Star Wars, et plus particulièrement du premier opus de la saga: Star Wars, épisode I: La Menace fantôme. La sortie du jeu, en 2000 sur PlayStation et Dreamcast, coïncide avec la sortie en support physique du film.

Le jeu met en scène plusieurs Jedi, padawans, chevaliers ou maîtres, engagés dans la protection de la galaxie, et plus spécifiquement de la planète Naboo et sa reine Padmé Amidala, tel que conté dans Star Wars, épisode I: La Menace fantôme. Le joueur suit Obi-Wan Kenobi, Qui-Gon Jinn, Mace Windu, Plo Koon et Adi Gallia dans leur lutte contre la Fédération du Commerce et son armée de droïdes de combat.', 'https://fr.wikipedia.org/wiki/Star_Wars_Episode_I:_Jedi_Power_Battles'),
  ('Q55257', 'Star Wars: Masters of Teräs Käsi est un jeu vidéo de combat développé et édité par LucasArts, sorti en 1997 sur PlayStation.', 'https://fr.wikipedia.org/wiki/Star_Wars:_Masters_of_Ter%C3%A4s_K%C3%A4si'),
  ('Q54338', 'Star Wars, épisode I: La Menace fantôme est un jeu vidéo d''action-aventure édité par LucasArts sur Windows et PlayStation en 1999. Il s''agit de l''adaptation vidéoludique du film du même nom. Ce jeu permet de prendre le contrôle des personnages de l''histoire comme Obi-Wan Kenobi, du capitaine Panaka, la reine Amidala ou Qui-Gon Jinn.

L''histoire commence avec l''arrivée sur la station du vice-roi Nute Gunray et se finit sur Naboo avec l''affrontement entre Obi-Wan et Dark Maul.

En janvier 2024, une version remastérisée est publiée sur le PlayStation Network, jouable sur PlayStation 4 et PlayStation 5.', 'https://fr.wikipedia.org/wiki/Star_Wars,_%C3%A9pisode_I_:_La_Menace_fant%C3%B4me_(jeu_vid%C3%A9o)'),
  ('Q55287', 'Star Wars: Dark Forces est un jeu vidéo produit par LucasArts et se fondant sur l''univers de Star Wars. Il est sorti en 1995 pour MS-DOS et Mac OS, puis plus tard pour la console PlayStation et en 2023 sur Amiga.

Jeu de tir à la première personne majeur de l''histoire, il est le premier à être codé en 3D, en prenant en compte le fait de s''accroupir et de sauter.

Le jeu se déroule avant, pendant et après les événements de l''Épisode IV. Le joueur prend la place de Kyle Katarn, un mercenaire appelé par la Rébellion pour déjouer un projet de l''Empire: des super-combattants appelés les Dark Troopers. La première mission propose au joueur de voler les plans de l''étoile noire à l''Empire, ce qui permet la victoire de l''Alliance rebelle dans les films.', 'https://fr.wikipedia.org/wiki/Star_Wars:_Dark_Forces'),
  ('Q3025449', 'Devil Dice (Xi) est un jeu vidéo de type puzzle édité par SCEI au Japon et par THQ aux États-Unis et développé par Shift, sorti en 1998 sur PlayStation. Il a pour suite Bombastic.', 'https://fr.wikipedia.org/wiki/Devil_Dice'),
  ('Q3020519', 'Dead Ball Zone est un jeu vidéo de handball futuriste sorti en 1998 sur PlayStation. Il a été développé par Rage Software.

Dans ce jeu, tous les coups sont permis; par exemple, il est possible d''utiliser une tronçonneuse pour arrêter les joueurs adverses. Très violent, il est déconseillé au jeune public.

Les parties se jouent par équipes et il n''est pas rare d''assister à la mort d''un des joueurs sur le terrain.', 'https://fr.wikipedia.org/wiki/Dead_Ball_Zone'),
  ('Q3023715', 'TOCA World Touring Cars (appelé Jarrett and Labonte Stock Car Racing aux États-Unis et WTC: World Touring Car Championship au Japon) est un jeu vidéo de course automobile développé et édité par Codemasters sur PlayStation et Game Boy Advance en 2000. C''est le troisième opus de la série TOCA.', 'https://fr.wikipedia.org/wiki/TOCA_World_Touring_Cars'),
  ('Q3024607', 'Tintin: Objectif Aventure est un jeu vidéo de plateformes et d''action-aventure édité et développé par Infogrames, en collaboration avec le studio satellite Moulinsart Multimédia. Le jeu vidéo est initialement commercialisé en Europe sur PlayStation le 21 septembre 2001, puis adapté et distribué par Atari Inc. sur Microsoft Windows le 16 novembre 2001. Il est le premier jeu vidéo en trois dimensions de la franchise Tintin, cinquième opus du nom, succédant à Le Temple du Soleil sorti en 1997, et précédant Le Secret de la Licorne sorti en 2011. Il a été faiblement accueilli par la majorité des critiques, bien que leurs avis soient partagés.', 'https://fr.wikipedia.org/wiki/Tintin_:_Objectif_Aventure'),
  ('Q3027783', 'Digimon Digital Card Battle, ou Digimon World: Digital Card Arena au Japon, est un jeu vidéo de cartes et stratégie, édité et distribué par Bandai sur console sur PlayStation. Il est initialement publié le 22 décembre 1999 au Japon, et le 5 juillet 2002 en Europe (hors monde francophone).', 'https://fr.wikipedia.org/wiki/Digimon_Digital_Card_Battle'),
  ('Q3027795', 'Digimon World 2 est un jeu vidéo de rôle et de donjon, développé et publié par Bandai sur PlayStation, issu de la franchise japonaise Digimon. Le jeu est publié le 27 juillet 2000 au Japon, et le 19 mai 2001 en Amérique du Nord. Aucune sortie n''a été effectuée en Europe.

Le joueur contrôle Akira, un digisauveur dont le but est de sauver les digimon et le digimonde d''une catastrophe imminente, avec l''aide de plusieurs digimon qu''il rencontrera au fil de ces aventures.', 'https://fr.wikipedia.org/wiki/Digimon_World_2'),
  ('Q3028480', 'Sōkyū Gurentai est un jeu vidéo développé par Raizing. Il s’agit d’un shoot them up à défilement vertical. Il est publié en 1996 sur borne d''arcade, puis porté sur Saturn et PlayStation en 1997.

Il compte parmi les plus célèbres titres du genre sortis sur Saturn, aux côtés de Layer Section ou Radiant Silvergun. Comme ce dernier, il utilise un format d''affichage 4:3 plutôt que le format 3:4, habituellement employé par les shoot theem up sur borne d''arcade.', 'https://fr.wikipedia.org/wiki/S%C5%8Dky%C5%AB_Gurentai'),
  ('Q3020041', 'Twin Cobra, intitulé Ultimate Tiger au Japon, est un jeu vidéo développé par Toaplan et édité par Taito. Il s’agit d’un shoot them up à défilement vertical. Il est commercialisé sur borne d''arcade en 1987. Le jeu est adapté sur Famicom, PC Engine, Mega Drive, X68000 et FM-Towns.', 'https://fr.wikipedia.org/wiki/Twin_Cobra'),
  ('Q3031547', 'ESPN Extreme Games est un jeu vidéo de sport de glisse sorti en 1995 sur PlayStation et PC. Le jeu a été développé par 989 Studios et édité par SCEA. Il est basé sur l''évènement sportif X Games. Il a connu deux suites: 2Xtreme et 3Xtreme. ESPN Extreme Games a été réédité sous le titre 1Xtreme en 1998.', 'https://fr.wikipedia.org/wiki/ESPN_Extreme_Games'),
  ('Q3028642', 'Le Monde perdu: Jurassic Park (The Lost World: Jurassic Park en version originale) est un jeu vidéo de plateformes 3D développé par DreamWorks Interactive et édité par Electronic Arts. Il est sorti en 1997 sur la PlayStation et la Saturn, et est basé sur le deuxième film de la franchise Jurassic Park. Dans le jeu, vous interprétez divers dinosaures et humains, en avançant de plus en plus dans la chaîne alimentaire de Isla Sorna.', 'https://fr.wikipedia.org/wiki/Le_Monde_perdu_:_Jurassic_Park_(jeu_vid%C3%A9o,_consoles_de_salon)'),
  ('Q3045847', 'ECW Anarchy Rulz est un jeu vidéo de catch sortit par la Acclaim Entertainment en 2000 et basé sur la Extreme Championship Wrestling (ECW). Il est sorti seulement sur PlayStation et Dreamcast. Le jeu est le successeur de ECW Hardcore Revolution.', 'https://fr.wikipedia.org/wiki/ECW_Anarchy_Rulz_(jeu_vid%C3%A9o)'),
  ('Q3043129', 'Défi au Tetris magique (titré Magical Tetris Challenge Featuring Mickey au Japon, et Magical Tetris Challenge dans le reste du monde) est un jeu vidéo de puzzle développé et édité par Capcom en octobre 1998 sur système d''arcade Aleck 64, sur console Nintendo 64 en novembre 1998. Le jeu est édité par Activision en Europe et par Capcom dans le reste du monde. Il a été porté sur PlayStation et Game Boy Color en 1999.

Il s''agit d''une version de Tetris incluant des personnages de l''univers de The Walt Disney Company.', 'https://fr.wikipedia.org/wiki/D%C3%A9fi_au_Tetris_magique'),
  ('Q3038307', 'Down in the Dumps (Au fond des décharges) est un jeu d''aventure en pointer-cliquer sorti en 1996, développé par Haiku Studios et édité par Philips Media.', 'https://fr.wikipedia.org/wiki/Down_in_the_Dumps'),
  ('Q3038754', 'Dragon Quest Monster 2 est un jeu vidéo réalisé par le développeur TOSE en 2001 pour l''éditeur japonais Enix.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_Monsters_2'),
  ('Q3047184', 'Three Wonders (Wonder 3 au Japon) est une compilation de jeu vidéo développée et éditée par Capcom sur CP System en mai 1991. La compilation comporte trois jeux vidéo:

Midnight Wanderers: Quest for the Chariot: un jeu de plates-formes;

Chariot: Adventure through the Sky: un shoot ''em up;

Don''t Pull: un jeu de puzzle.', 'https://fr.wikipedia.org/wiki/Three_Wonders'),
  ('Q3039299', 'Dreams to Reality, ou simplement Dreams sur PlayStation, est un jeu vidéo d''action-aventure, publié en 1997 sur PC (DOS et Windows) et en 1998 sur PlayStation, développé et édité par Cryo Interactive.', 'https://fr.wikipedia.org/wiki/Dreams_to_Reality'),
  ('Q3047924', 'Star Gladiator: I - Final Crusade "スターグラディエイター"est un jeu vidéo de combat développé et édité par Capcom en juin 1996 sur système d''arcade ZN-1. C''est le premier jeu de la série Star Gladiator.', 'https://fr.wikipedia.org/wiki/Star_Gladiator:_I_-_Final_Crusade'),
  ('Q3088434', 'Front Mission 3 est un jeu vidéo développé et édité par Square. Il s’agit d’un Tactical RPG sorti en 1999 sur PlayStation. Il fait partie de la série de jeux vidéo Front Mission, et le premier à paraître en Europe.', 'https://fr.wikipedia.org/wiki/Front_Mission_3'),
  ('Q3067262', 'Hellboy: Dogs of the Night, ou Hellboy: Asylum Seeker dans sa version pour console, est un jeu vidéo d''action-aventure développé et édité par Cryo Interactive, sorti en 2000 sur ordinateurs PC et sur la console PlayStation. Le jeu reprend et adapte l''univers et les personnages du comic Hellboy, de Mike Mignola, publié aux États-Unis par Dark Horse Comics à partir de 1993.', 'https://fr.wikipedia.org/wiki/Hellboy:_Dogs_of_the_Night'),
  ('Q3051007', 'Eliminator est un jeu vidéo d''action sorti en 1999 sur PlayStation et Windows. Le jeu a été développé par Magenta Software et édité par Psygnosis.', 'https://fr.wikipedia.org/wiki/Eliminator_(jeu_vid%C3%A9o,_1999)'),
  ('Q3067854', 'RayStorm est un jeu vidéo de type shoot ''em up développé et édité par Taito sur borne d''arcade en 1996. Il est porté sur PlayStation fin 96 / début 97, et sur Saturn en octobre 1997 sous le titre Layer Section II uniquement au Japon.', 'https://fr.wikipedia.org/wiki/RayStorm'),
  ('Q3091499', 'Suikoden est un jeu vidéo de rôle, développé et édité par Konami, sorti sur PlayStation en 1995. Il s''agit du premier jeu d''une série de jeux de rôle.

Le jeu repose sur une légende chinoise selon laquelle cent-sept personnes seraient regroupés par un leader, pour former les cent-huit étoiles du destin (concept inspiré du roman Au bord de l''eau). C''est ce que le jeu propose: le héros (dont vous déterminez le nom en début de partie), fils du général Teo McDohl, commence par entrer dans la rébellion, et finira par en prendre la tête, s’opposant ainsi à l''empereur Barbarossa et à ses six Grands Généraux. Ce jeu de rôle est donc imprégné de stratégie militaire, et laisse une place importante au recrutement des personnages. En effet, une fois un quartier général trouvé, votre armée aura besoin de stratèges, de soldats, mais aussi de marchands, de sorciers, etc. Il faudra aussi former des alliances avec les diverses régions de l''Empire de la Lune Écarlate, et détrôner son dirigeant.', 'https://fr.wikipedia.org/wiki/Suikoden_(jeu_vid%C3%A9o)'),
  ('Q3051600', 'Elmo''s Letter Adventure (aussi appelé Elmo''s Letter Parade) est un jeu vidéo ludo-éducatif sorti en 1999 sur Nintendo 64 et PlayStation. Le jeu a été développé par NewKidCo et édité par Realtime Associates.

Le jeu est basé sur l''univers de 1, rue Sésame.', 'https://fr.wikipedia.org/wiki/Elmo%27s_Letter_Adventure'),
  ('Q3091280', 'Futur Racer (titré Defeat Lightning au Japon) est un jeu vidéo de course sorti sur PlayStation en 1997. Il a été développé et édité par D Cruise au Japon, et a été édité par Midas Interactive Entertainment en Europe en 2001.

Dans une ambiance futuriste, le joueur choisit l''un des six robots géants disponibles pour lancer une course.

Le but du jeu est de marquer le plus de points possibles grâce à diverses actions (gêner un adversaire, franchir la ligne d''arrivée en premier...).

Ce jeu, assez orienté pour un public nippon, ne possède pas de mode deux joueurs.', 'https://fr.wikipedia.org/wiki/Future_Racer'),
  ('Q3082829', 'Frank Thomas Big Hurt Baseball est un jeu vidéo de baseball sorti en 1995 et fonctionne sur PlayStation, DOS, Game Boy, Game Gear, Mega Drive, Saturn et Super Nintendo. Le jeu a été développé par Iguana Entertainment et édité par Acclaim.', 'https://fr.wikipedia.org/wiki/Frank_Thomas_Big_Hurt_Baseball'),
  ('Q3099937', 'Glover est un jeu vidéo de plates-formes par Hasbro Interactive sorti sur Nintendo 64, PlayStation et PC. Un remake du jeu a été édité sur Steam par Piko Interactive. Il met en scène un gant et une balle dans 6 mondes différents de 3 à 5 niveaux chacun.

Un deuxième portage Windows mis à jour est sorti en 2022 et un portage pour Nintendo Switch Xbox One Xbox Series X/S PS4 PS5 sera disponible le 27 février 2025', 'https://fr.wikipedia.org/wiki/Glover_(jeu_vid%C3%A9o)'),
  ('Q3094545', 'Galaxy Fight: Universal Warriors est un jeu vidéo de combat développé par Sunsoft et édité par SNK en 1995 sur Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD (NGM / NGH 078). Il est également porté sur PlayStation et Saturn.', 'https://fr.wikipedia.org/wiki/Galaxy_Fight:_Universal_Warriors'),
  ('Q3096283', 'NASCAR 2000 est un jeu vidéo de course NASCAR sorti en 1999 et fonctionne sur PlayStation, Game Boy Color, Nintendo 64 et Windows.

Le jeu est développé par Stormfront Studios et édité par EA Sports. Il s''agit du troisième titre NASCAR d''Electronic Arts, après NASCAR 99 et NASCAR 98.', 'https://fr.wikipedia.org/wiki/NASCAR_2000'),
  ('Q3112747', 'Hellnight est un jeu vidéo sorti sur PlayStation édité par Konami et développé par Atlus.', 'https://fr.wikipedia.org/wiki/Hellnight'),
  ('Q3118833', 'Gubble est un jeu vidéo sorti en 1997 et développé par Mud Duck Productions.

Sorti sur Mac et sur PC en 1997 et sur PlayStation en 2002, l''objectif du jeu est de commander l''extraterrestre (Un Zymbot) Gubble dans différents niveaux labyrinthique, en utilisant des outils (comme un marteau ou un tournevis) pour dévisser vis, clous et verrous.

Le scénario reste vague sur l''univers de Gubble (il n''est guère mentionné que dans le manuel) et n''est là que pour ajouter un peu de rationalité au jeu. Bien qu''aucune planète ne soit nommée, celles-ci sont similaires à celles existantes (Lave ressemble par exemple à Vénus).', 'https://fr.wikipedia.org/wiki/Gubble'),
  ('Q3120813', 'Gunbird est un shoot ''em up à défilement vertical développé par Psikyo en 1994.', 'https://fr.wikipedia.org/wiki/Gunbird'),
  ('Q3117320', 'Mega Man Legends 2, connu au Japon sous le nom de Rockman DASH 2 - Episode 2: Ōinaru Isan, est un jeu d''action-aventure développé par Capcom Production Studio 2 et édité par Capcom. Il fait partie de la franchise Mega Man et est le troisième de la série dérivée Mega Man Legends (le deuxième étant The Misadventures of Tron Bonne). Il est distribué en 2000 sur PlayStation, en 2002 sur PC (Windows) et en 2005 sur PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Mega_Man_Legends_2'),
  ('Q3110001', 'Jackie Chan Stuntmaster est un jeu vidéo d''action mettant en vedette Jackie Chan. Ce jeu a été édité par Sony Computer Entertainment et développé par Radical Entertainment. Il est sorti sur console PlayStation le 17 mai 2000.', 'https://fr.wikipedia.org/wiki/Jackie_Chan_Stuntmaster'),
  ('Q3110746', 'Goofy''s Fun House est un jeu vidéo d''action sorti en 2001 sur PlayStation. Le jeu a été développé par The Code Monkeys et édité par NewKidCo/Disney Interactive. Il met en scène le personnage de Dingo.', 'https://fr.wikipedia.org/wiki/Goofy%27s_Fun_House'),
  ('Q3120817', 'Gundam: Battle Assault 2 est un jeu vidéo de combat développé par Natsume et édité par Bandai en juillet 2002 sur PlayStation. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et c''est le troisième opus d''une série composée de cinq jeux vidéo de combat.', 'https://fr.wikipedia.org/wiki/Gundam:_Battle_Assault_2'),
  ('Q3120818', 'Gundam: The Battle Master est un jeu vidéo de combat développé par Natsume et édité par Bandai en juin 1997 sur PlayStation. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et c''est le premier opus d''une série composée de cinq jeux vidéo de combat.', 'https://fr.wikipedia.org/wiki/Gundam:_The_Battle_Master'),
  ('Q3121514', 'Samurai Shodown IV: Amakusa''s Revenge est un jeu vidéo de combat développé et édité par SNK en 1996 sur système d''arcade Neo-Geo MVS, sur console Neo-Geo AES et Neo-Geo CD (NGM 222). L''histoire du jeu se déroule entre Samurai Shodown III: Blades of Blood et Samurai Shodown II.

Samurai Shodown IV: Amakusa''s Revenge est publié sur arcade via le système Neo-Geo MVS le 25 octobre 1996 puis sur les consoles de SNK le 29 novembre 1996 (Neo-Geo AES) et le 27 décembre 1996 (Neo-Geo CD).

Samurai Shodown IV est porté sur Sega Saturn le 2 octobre 1997 et sur PlayStation le 25 décembre 1997 uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Samurai_Shodown_IV:_Amakusa%27s_Revenge'),
  ('Q3121523', 'Samurai Shodown III: Blades of Blood connu au Japon sous le titre de Samurai Spirits: Zankurō Musōken, est un jeu vidéo de combat développé et édité par SNK en 1995 sur système d''arcade Neo-Geo MVS, sur console Neo-Geo AES et Neo-Geo CD (NGM 087).

L''histoire du jeu se déroule entre Samurai Shodown et Samurai Shodown IV.

Sur Neo-Geo, SNK publie Samurai Shodown III sur arcade via le système MVS le 15 novembre 1995 puis sur support cartouche pour la Neo-Geo AES le 1er décembre 1995, et enfin sur disque compact pour la Neo-Geo CD le 22 décembre 1995.

Samurai Shodown III est développé par Ukiyotei pour la conversion sur PlayStation. Cette version est publiée au Japon le 30 août 1996, en Amérique du Nord le 30 novembre 1996 et en Europe, le 1er mars 1997. La version Sega Saturn est développée par SIMS Co., le titre est publié uniquement au Japon le 8 novembre 1996.', 'https://fr.wikipedia.org/wiki/Samurai_Shodown_III:_Blades_of_Blood'),
  ('Q3120826', 'Gundam 0079: The War for Earth est un jeu vidéo de stratégie développé par Presto Studios et édité par Bandai en 1997 sur PC (Windows 95) et Power Macintosh. C''est une adaptation en jeu vidéo de l''anime Mobile Suit Gundam. Il a été porté sur PlayStation la même année.', 'https://fr.wikipedia.org/wiki/Gundam_0079:_The_War_for_Earth'),
  ('Q3129109', 'Yusha: Heaven''s Gate est un jeu de combat sorti en 1996 sur borne d''arcade, développé par Racdym (maintenant connu sous le nom Racjin) et publié par Atlus.

Le 13 décembre 1996, le jeu a été porté sur PlayStation au Japon. En octobre 1997, JVC Digital Studios le distribue en Europe', 'https://fr.wikipedia.org/wiki/Yusha:_Heaven%27s_Gate'),
  ('Q60742149', 'NASCAR Racing est un jeu vidéo de course développé et édité par Papyrus Design Group, sorti en 1994 sur DOS, Mac et PlayStation.', 'https://fr.wikipedia.org/wiki/NASCAR_Racing'),
  ('Q60786589', 'Tokyo Highway Battle (ou Shutokō Battle: Drift King sur PlayStation et Shutokō Battle ''97 sur Saturn, au Japon) est un jeu vidéo de course développé par Genki, sorti en 1996 sur PlayStation et en 1997 sur Saturn.', 'https://fr.wikipedia.org/wiki/Tokyo_Highway_Battle'),
  ('Q57171071', 'NBA Action 98 est un jeu vidéo de basket-ball développé par Visual Concepts Entertainment et édité par Sega sur Saturn, PlayStation et PC (Windows).

La version PlayStation s''intitule NBA Fastbreak ''98.', 'https://fr.wikipedia.org/wiki/NBA_Action_98'),
  ('Q60755300', 'Enigma est un jeu vidéo d''action-aventure développé par Omega Force et publié par Koei, sorti le 2 avril 1998 au Japon pour la PlayStation. Se déroulant en 1920, le jeu met en scène trois personnages jouables originaires d''Angleterre, du Japon et des États-Unis, qui parcourent le monde pour résoudre des énigmes dans diverses ruines et temples.', 'https://fr.wikipedia.org/wiki/Enigma_(jeu_vid%C3%A9o,_1998)'),
  ('Q3140909', 'Hoshigami: Ruining Blue Earth est un jeu vidéo de rôle tactique développé par Max Five et édité par Atlus, sorti sur PlayStation en 2001 aux États-Unis et en 2002 au Japon.', 'https://fr.wikipedia.org/wiki/Hoshigami:_Ruining_Blue_Earth'),
  ('Q3134227', 'Hermie Hopperhead (ou Hermie Hopperhead: Scrap Panic) est un jeu vidéo de plate-forme sorti en 1996 et qui fonctionne sur PlayStation.

Le jeu a été développé par Yuke''s Media Creations puis édité par Hudson Soft.', 'https://fr.wikipedia.org/wiki/Hermie_Hopperhead'),
  ('Q3156408', 'Iwatobi Penguin: Rocky × Hopper est un jeu vidéo édité par Nippon Rental, sorti le 5 novembre 1998 sur PlayStation. Il a pour suite Iwatobi Penguin: Rocky × Hopper 2 – Tantei Monogatari.', 'https://fr.wikipedia.org/wiki/Iwatobi_Penguin:_Rocky_%C3%97_Hopper'),
  ('Q3154541', 'Iron and Blood: Warriors of Ravenloft est un jeu de combat en 3D développé par Take-Two Interactive pour Acclaim et sorti sous MS-DOS et sur PlayStation en 1996.

Iron and Blood est basé sur l''univers de campagne de Ravenloft, univers horrifique de dark fantasy créé pour le jeu de rôle Advanced Dungeons and Dragons en 1990 et dérivé d''un scénario édité en 1983. C''est le troisième jeu vidéo à exploiter cet univers après Ravenloft: Strahd''s Possession et Ravenloft: Stone Prophet, deux jeux vidéo de rôle sortis respectivement en 1994 et 1995.

Une version pour la console Saturn de Sega était aussi prévue mais fut annulée.', 'https://fr.wikipedia.org/wiki/Iron_and_Blood:_Warriors_of_Ravenloft'),
  ('Q3141103', 'Hot Wheels Turbo Racing est un jeu vidéo de course sorti en 1999 sur PlayStation et Nintendo 64. Le jeu a été développé par Stormfront Studios et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Hot_Wheels_Turbo_Racing'),
  ('Q3153293', 'International Rally Championship ou IRC est un jeu vidéo de course de rallye automobile sorti en 1997 sur PC, puis en 1998 sur PlayStation. Le jeu est sorti sous l''appellation Tommi Mäkinen Rally sur PlayStation sur les territoires non francophones.

Il restera un jeu de course célèbre pour Europress après Rally Championship. Avec l''éditeur de circuits, un grand nombre de nouvelles fonctions étonnantes, des voitures supplémentaires et des décors plus attrayants, cette simulation plonge le pilote virtuel dans une atmosphère authentique du sport automobile, offrant les décors vertigineux de la Suisse, le désert d''Égypte, la jungle indonésienne, les pistes verglacées de Russie... Aux commandes d''une des neuf voitures proposées, il doit affronter des éléments imprévisibles dans le but d''aboutir à la victoire.', 'https://fr.wikipedia.org/wiki/International_Rally_Championship'),
  ('Q3156407', 'Iwatobi Penguin: Rocky × Hopper 2 − Tantei Monogatari est un jeu vidéo édité par Culture Publishers, sorti en 1998 sur PlayStation. C''est la suite de Iwatobi Penguin: Rocky × Hopper.', 'https://fr.wikipedia.org/wiki/Iwatobi_Penguin:_Rocky_%C3%97_Hopper_2_-_Tantei_Monogatari'),
  ('Q3143715', 'Hydro Thunder est un jeu vidéo de course de bateau sorti en 1999 sur arcade et Dreamcast puis en 2000 sur Nintendo 64, PlayStation, et PC. Le jeu a été développé et édité par Midway. Le jeu a reçu le label Sega All Stars sur Dreamcast. Une « suite » à ce jeu est sortie en 2010 sous le nom de Hydro Thunder Hurricane, disponible sur le Xbox Live Arcade sur Xbox 360 et rétrocompatible sur Xbox One.

Le jeu est intégré dans Midway Arcade Treasures 3 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Hydro_Thunder'),
  ('Q3133608', 'Spider-Man 2: La Revanche d''Electro est un jeu vidéo d''action développé par Vicarious Visions et édité par Activision en 2001 sur PlayStation. Il fait suite à Spider-Man sorti 1 an auparavant sur la même plate-forme.

Comme son titre l''indique, il est proposé au joueur de vivre une aventure avec l''homme araignée provenant des Marvel Comics américains.', 'https://fr.wikipedia.org/wiki/Spider-Man_2_:_La_Revanche_d%27Electro'),
  ('Q63225768', 'Sabrina, l''apprentie sorcière (Sabrina the Teenage Witch) est une série et un personnage de comics de l''éditeur Archie Comics.

Introduite pour la première fois en 1962 dans le numéro 22 du comics Archie''s Mad House et après plusieurs apparitions dans les publications mettant en scène Archie Andrews et sa bande, notamment dans Archie''s TV Laugh-Out, Sabrina Spellman obtient sa propre série en 1971.

C''est l''un des personnages les plus populaires de l''univers des comics Archie, connaissant de nombreuses adaptations à la télévision diffusées partout dans le monde. Sabrina a également été le personnage principal de quelques séries de comics spin-off se déroulant dans des chronologies alternatives comme l''horrifique Chilling Adventures of Sabrina.', 'https://fr.wikipedia.org/wiki/Sabrina,_l%27apprentie_sorci%C3%A8re'),
  ('Q65083171', 'VMX Racing est un jeu vidéo de course développé par Studio e et publié en 1997 par Playmates Interactive Entertainment sur PlayStation.', 'https://fr.wikipedia.org/wiki/VMX_Racing'),
  ('Q62554786', 'UEFA Champions League Season 1998/99 est un jeu vidéo de football développé par Silicon Dreams Studio et édité par Eidos Interactive, sorti en 1999 sur Windows et PlayStation.', 'https://fr.wikipedia.org/wiki/UEFA_Champions_League_Season_1998/99'),
  ('Q3190124', 'Jupiter Strike (Zeitgeist au Japon) est un jeu vidéo de type shoot them up en 3D, sorti en 1995 sur PlayStation. Le jeu a été développé par Taito et édité par Taito et Acclaim.', 'https://fr.wikipedia.org/wiki/Jupiter_Strike'),
  ('Q3176640', 'Puzzle Bobble 2, aussi connu sous le nom Bust-a-Move Again, est un jeu vidéo de type puzzle game développé par Taito et édité par Taito en 1995 sur borne d''arcade Taito F3. Le jeu a été adapté à partir de 1996 sur consoles et Windows sous le titre Bust-a-Move 2: Arcade Edition. Une version Neo-Geo MVS est sortie en 1999 (NGM 248)

Il s''agit du second épisode de la série Puzzle Bobble. Le but est de vider l''écran de toutes les bulles présentes (mode 1 joueur) ou d''envoyer le plus de bulle à son adversaire afin de le faire perdre (mode 2 joueurs).', 'https://fr.wikipedia.org/wiki/Puzzle_Bobble_2'),
  ('Q3197113', 'Kingsley''s Adventure est un jeu vidéo d''aventure/plateformes sorti en 1999 sur PlayStation. Le jeu a été développé par Psygnosis et édité par SCEE.', 'https://fr.wikipedia.org/wiki/Kingsley%27s_Adventure'),
  ('Q3179631', 'Railroad Tycoon II est un jeu vidéo développé par PopTop Software et édité par Gathering, sorti dans un premier temps sur PC (18 novembre 1998), puis sur Dreamcast en 2000 ainsi que sur PlayStation en 2001.

Il est le deuxième opus de la série Railroad Tycoon.', 'https://fr.wikipedia.org/wiki/Railroad_Tycoon_II'),
  ('Q3179262', 'Mega Man Legends (Rockman DASH au Japon), est un jeu vidéo d''action-aventure sorti initialement sur PlayStation, développé par Capcom Production Studio 2 et édité par Capcom en 1997. Le jeu est ensuite porté sur Nintendo 64, sous le titre Mega Man 64 en 2000, ainsi que sur PC (Windows) et sur PlayStation Portable par la suite. Le jeu a été conçu par Yoshinori Kawano. Le jeu fait partie de la série Mega Man Legends, série dérivée de Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_Legends_(jeu_vid%C3%A9o)'),
  ('Q3171293', 'O.D.T., sous-titré Escape... Or Die Trying aux États-Unis, est un jeu vidéo d''action-aventure édité par Psygnosis en 1998 sur PlayStation et Windows.', 'https://fr.wikipedia.org/wiki/O.D.T.'),
  ('Q3187953', 'Judge Dredd est un jeu de tir au pistolet optique du type rail shooter en trois dimensions développé par Gremlin Interactive et édité en 1997 par Acclaim Entertainment sur borne d''arcade, et par Activision sur PlayStation. C''est une adaptation du comics Judge Dredd. Le jeu est réédité en 2008 sur le PlayStation Network, disponible sur PlayStation 3, PlayStation Portable et PlayStation Vita.', 'https://fr.wikipedia.org/wiki/Judge_Dredd_(jeu_vid%C3%A9o,_1997)'),
  ('Q3189970', 'Jumping Flash! est un jeu vidéo de plates-formes développé par le studio japonais Exact et édité par Sony Computer Entertainment, sorti en 1995 sur la console PlayStation.

Le jeu a donné suite à Jumping Flash! 2, Robbit mon Dieu et Pocket MuuMuu (en).', 'https://fr.wikipedia.org/wiki/Jumping_Flash!'),
  ('Q3223059', 'Le Gardien des ténèbres est un jeu vidéo d''aventure et d''action développé et édité par le studio français Cryo Interactive en 1999. Il a été édité pour PC sous Windows et sur console PlayStation. Le joueur incarne un moine au service d''une organisation occulte qui doit retrouver et combattre diverses entités surnaturelles.', 'https://fr.wikipedia.org/wiki/Le_Gardien_des_t%C3%A9n%C3%A8bres'),
  ('Q3224187', 'Le Maillon faible est un jeu vidéo de quiz sorti en 2001 sur PC, PlayStation et PlayStation 2 aux États-Unis, et en 2002 en Europe. Il a été développé par Traveller''s Tales et édité par Activision. Il s''agit d''une adaptation du jeu télévisé du même nom. La PEGI a noté ce jeu +3.', 'https://fr.wikipedia.org/wiki/Le_Maillon_faible_(jeu_vid%C3%A9o)'),
  ('Q3198037', 'Knockout Kings est un jeu vidéo de boxe anglaise sorti en 1998 sur PlayStation. Il a été développé High Score Entertainment et édité par EA Sports.', 'https://fr.wikipedia.org/wiki/Knockout_Kings'),
